// What the property will look like, said back in plain words.
//
// Built from `toRecord(draft)` rather than from the draft, so this is not a
// summary of what was typed — it is a description of what publishing would
// actually put on the website. Those differ in exactly the place it matters:
// a property switched to Ask for Pricing still has the old number sitting in
// the draft, and a review screen that showed it would be describing a page
// that will never exist.
//
// Every figure comes through MTC-KRP-024's derivations, so the review shows
// the same price, the same bedroom summary and the same availability the
// public page will. Re-deriving them here with slightly different rules is how
// a review screen quietly becomes a lie.
//
// No React: this is data, and it is tested as data.

import {
  availabilityOf,
  bedroomSummary,
  startingPrice,
  photoCount as countPhotos,
} from "../../property/derive.ts";
import type { PropertyRecord } from "../../property/types";
import type { PropertyDraft } from "./draft";
import { toRecord } from "./draft.ts";
import { categoriesUsed, featuredImage, hasChosenFeatured } from "./images.ts";
import { plansWithoutImage } from "./floorPlans.ts";
import { resolveSimilar } from "./similar.ts";
import { publishBlockers } from "./validation.ts";

const money = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});

const count = new Intl.NumberFormat("en-US");

const AVAILABILITY_WORDS: Record<string, string> = {
  available: "Available now",
  limited: "Available soon",
  contact: "Contact for availability",
  unavailable: "Not available",
};

/** "$1,995 / month", or the honest alternative. Never a manufactured zero. */
export function priceLine(record: PropertyDraft): string {
  const price = startingPrice(record);
  return price.kind === "monthly"
    ? `${money.format(price.amount)} / month`
    : "Contact for pricing";
}

export function sizeLine(record: PropertyDraft): string {
  const parts: string[] = [];

  const beds = bedroomSummary(record);
  if (beds) parts.push(beds);

  if (typeof record.bathrooms === "number" && record.bathrooms > 0) {
    parts.push(`${record.bathrooms} ${record.bathrooms === 1 ? "bathroom" : "bathrooms"}`);
  }

  if (typeof record.area === "number" && record.area > 0) {
    parts.push(`${count.format(record.area)} sq ft`);
  }

  return parts.join(" · ");
}

export type ReviewLine = {
  label: string;
  /** Already formatted. Empty means the fact is not there yet. */
  value: string;
};

export type ReviewSection = {
  /** The step its Edit link goes to. */
  stepId: string;
  title: string;
  lines: ReviewLine[];
  /** Shown instead of the lines when there is genuinely nothing to show. */
  empty?: string;
};

export function buildReview(
  draft: PropertyDraft,
  all: PropertyRecord[]
): ReviewSection[] {
  const record = toRecord(draft);

  const amenities = record.amenities ?? [];
  const images = record.images ?? [];
  const plans = record.floorPlans ?? [];
  const similar = resolveSimilar(record, all);

  const featured = featuredImage(images);
  const categories = categoriesUsed(images);
  const missingPlanImages = plansWithoutImage(record);

  return [
    {
      stepId: "basics",
      title: "Property Basics",
      lines: [
        { label: "Name", value: record.title?.trim() ?? "" },
        { label: "Location", value: record.location?.trim() ?? "" },
        { label: "Type", value: record.type?.trim() ?? "" },
        { label: "Size", value: sizeLine(record) },
        {
          label: "Availability",
          value: AVAILABILITY_WORDS[availabilityOf(record)] ?? "",
        },
        { label: "Price", value: priceLine(record) },
      ],
    },
    {
      stepId: "content",
      title: "Content & Amenities",
      lines: [
        { label: "Section title", value: record.content?.title?.trim() ?? "" },
        { label: "Short description", value: record.summary?.trim() ?? "" },
        {
          label: "Description",
          value: describeParagraphs(record.content?.paragraphs),
        },
        {
          label: "Amenities",
          value: amenities.length ? amenities.join(", ") : "",
        },
      ],
    },
    {
      stepId: "images",
      title: "Images & Floor Plans",
      empty: images.length === 0 && plans.length === 0 ? "No photographs or floor plans yet." : undefined,
      lines: [
        {
          label: "Featured image",
          /* Named by its caption, never by its internal id — the manager chose
             a picture, not a record. */
          value: featured
            ? `${featured.label || "Untitled photograph"}${
                hasChosenFeatured(images) ? "" : " (first photograph, not chosen)"
              }`
            : "",
        },
        {
          label: "Photographs",
          value: images.length
            ? `${countPhotos(record)} ${countPhotos(record) === 1 ? "photograph" : "photographs"}`
            : "",
        },
        { label: "Categories", value: categories.join(", ") },
        {
          label: "Floor plans",
          value: plans.length
            ? `${plans.length} ${plans.length === 1 ? "floor plan" : "floor plans"}${
                missingPlanImages
                  ? ` · ${missingPlanImages} without a drawing`
                  : ""
              }`
            : "",
        },
      ],
    },
    {
      stepId: "similar",
      title: "Similar Properties",
      lines: [
        {
          label: "Chosen by hand",
          value: similar.pinned.map((item) => item.title).join(", "),
        },
        {
          label: "Chosen automatically",
          value: similar.automatic.map((item) => item.title).join(", "),
        },
        {
          label: "Left out",
          value: similar.excluded.map((item) => item.title).join(", "),
        },
      ],
    },
  ];
}

function describeParagraphs(paragraphs: string[] | undefined): string {
  const list = paragraphs ?? [];
  if (list.length === 0) return "";
  return `${list.length} ${list.length === 1 ? "paragraph" : "paragraphs"}`;
}

/* ── readiness ───────────────────────────────────────────── */

export type ReadinessState = "done" | "todo" | "optional";

export type ReadinessLine = {
  label: string;
  state: ReadinessState;
  /** Why it is not done, where that is not obvious. */
  detail?: string;
};

/**
 * What still stands between this property and the website.
 *
 * Three states rather than two, because "not done" and "not required" are
 * different things and collapsing them is how a workflow ends up feeling like
 * it is nagging. Every state carries a word — a tick, a circle and a colour
 * would leave a colour-blind manager reading two identical rows.
 */
export function readiness(draft: PropertyDraft): ReadinessLine[] {
  const record = toRecord(draft);
  const blockers = publishBlockers(draft);

  const forStep = (stepId: string) => blockers.filter((issue) => issue.stepId === stepId);

  const basics = forStep("basics");
  const content = forStep("content");
  const plans = forStep("images");

  const images = record.images ?? [];

  return [
    {
      label: "Property basics",
      state: basics.length === 0 ? "done" : "todo",
      detail: basics.map((issue) => issue.label).join(", ") || undefined,
    },
    {
      label: "Content",
      state: content.length === 0 ? "done" : "todo",
      detail: content.map((issue) => issue.label).join(", ") || undefined,
    },
    {
      label: "Featured image",
      /* Optional, not required: the public page has always coped without
         photography, and a rule forcing one would teach people to upload
         anything at all to get past this screen. */
      state: hasChosenFeatured(images)
        ? "done"
        : images.length > 0
          ? "optional"
          : "optional",
      detail: hasChosenFeatured(images)
        ? undefined
        : images.length > 0
          ? "The first photograph will be used."
          : "No photographs yet.",
    },
    {
      label: "Floor plans",
      state: plans.length > 0 ? "todo" : "optional",
      detail:
        plans.length > 0
          ? plans.map((issue) => issue.label).join(", ")
          : (record.floorPlans ?? []).length === 0
            ? "None added."
            : undefined,
    },
  ];
}
