// @ppm--version--1.0

import React from "react";
import { FaInbox } from "react-icons/fa";

import LeadAvatar from "./LeadAvatar";
import LeadQuickActions from "./LeadQuickActions";
import StatusBadge from "./StatusBadge";
import { formatReceived } from "./format";
import type { Lead } from "./types";
import { TableToggles } from "../../config/gh-leads--ui-table-settings";
import template from "../../config/gh-leads--template";


type Props = {
  leads: Lead[];
  loading: boolean;
  now: number | null;
  selectedIds: string[];
  onToggle: (id: string) => void;
  onToggleAll: () => void;
  /** Wired to LeadPopout in a later task. */
  onOpenLead?: (lead: Lead) => void;
  emptyTitle: string;
  emptyText: string;
};

const COLUMNS = 7;

const { columns } = template.labels;

export default function LeadsTable({
  leads,
  loading,
  now,
  selectedIds,
  onToggle,
  onToggleAll,
  onOpenLead,
  emptyTitle,
  emptyText,
}: Props) {
  const selected = new Set(selectedIds);
  const allChecked = leads.length > 0 && leads.every((lead) => selected.has(lead.id));

  const openRow = (lead: Lead) => {
    if (onOpenLead) onOpenLead(lead);
  };

  const handleKeyDown = (event: React.KeyboardEvent, lead: Lead) => {
    if (event.key !== "Enter" && event.key !== " ") return;

    event.preventDefault();
    openRow(lead);
  };



  return (
    <div className="leads-table-wrap">
      <table className="leads-table">
        <thead>
          <tr>
             { !TableToggles.STATUS ? <></> :
              <th scope="col" className="leads-c-check">
                <input
                  type="checkbox"
                  className="leads-check"
                  checked={allChecked}
                  onChange={onToggleAll}
                  disabled={leads.length === 0}
                  aria-label={allChecked ? "Clear selection" : "Select all leads"}
                />
              </th>
            }
            <th scope="col" className="leads-c-name">
              {columns.name}
            </th>
            
            { !TableToggles.QUICK_ACTIONS ? <></> :
              <th scope="col" className="leads-c-actions">
                {columns.actions}
              </th>
            }
            
            <th scope="col" className="leads-c-phone">
              {columns.phone}
            </th>
            <th scope="col" className="leads-c-email">
              {columns.email}
            </th>
            <th scope="col" className="leads-c-received">
              {columns.received}
            </th>
             { !TableToggles.STATUS ? <></> :
              <th scope="col" className="leads-c-status">
                {columns.status}
              </th>
            }
          </tr>
        </thead>

        <tbody>
          {loading &&
            Array.from({ length: 6 }).map((_, index) => (
              <tr key={`skeleton-${index}`}>
                {Array.from({ length: COLUMNS }).map((__, cell) => (
                  <td key={cell}>
                    <span className="leads-skeleton" style={{ display: "block" }} />
                  </td>
                ))}
              </tr>
            ))}

          {!loading && leads.length === 0 && (
            <tr>
              <td colSpan={COLUMNS}>
                <div className="leads-empty">
                  <span className="leads-empty__icon">
                    <FaInbox size={28} />
                  </span>
                  <span className="leads-empty__title">{emptyTitle}</span>
                  <p className="leads-empty__text">{emptyText}</p>
                </div>
              </td>
            </tr>
          )}

          {!loading &&
            leads.map((lead) => {
              const isSelected = selected.has(lead.id);

              return (
                <tr
                  key={lead.id}
                  className={isSelected ? "leads-row leads-row--selected" : "leads-row"}
                  tabIndex={0}
                  onClick={() => openRow(lead)}
                  onKeyDown={(event) => handleKeyDown(event, lead)}
                > 

                 { !TableToggles.STATUS ? <></> :
                    <td
                      className="leads-c-check"
                      onClick={(event) => event.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        className="leads-check"
                        checked={isSelected}
                        onChange={() => onToggle(lead.id)}
                        aria-label={`Select ${lead.name}`}
                      />
                    </td>
                  }

                  <td className="leads-c-name">
                    <div className="leads-name">
                      <LeadAvatar name={lead.name} />
                      <div className="leads-name__text">
                        <span className="leads-name__label leads-truncate" title={lead.name}>
                          {lead.name}
                        </span>
                      </div>
                    </div>
                  </td>

                { !TableToggles.QUICK_ACTIONS ? <></> :
                  <td className="leads-c-actions">
                    <LeadQuickActions lead={lead} />
                  </td> 
                }

                  <td className="leads-c-phone">
                    <span className="leads-truncate leads-tabular" title={lead.phone}>
                      {lead.phone}
                    </span>
                  </td>

                  <td className="leads-c-email">
                    <span className="leads-truncate leads-muted" title={lead.email}>
                      {lead.email}
                    </span>
                  </td>

                  <td className="leads-c-received">
                    <span className="leads-truncate leads-muted">
                      {formatReceived(lead.receivedAt, now)}
                    </span>
                  </td>
                  { !TableToggles.STATUS ? <></> :
                    <td className="leads-c-status">
                      <StatusBadge status={lead.status} />
                    </td>
                  }
                </tr>
              );
            })}
        </tbody>
      </table>
    </div>
  );
}
