// The property catalogue, in Supabase.
//
// The whole catalogue is ONE document — { version, properties[] } at
// "properties/properties.json" — which is exactly the shape contracts/
// getProperties.ts specifies. That is deliberate: a Gatsby build can fetch this
// one row and generate a page per property, which is the thing a per-property
// table would have made fiddlier rather than easier.
//
// It also means the document holds the full catalogue, bundled samples
// included, rather than only the edits. Storing only the edits would have been
// slightly simpler here and useless to a build, which has no way to know what
// the twelve samples were.
//
// ── the trade, stated ────────────────────────────────────────────────────
// Saving one property reads the catalogue, replaces that property, and writes
// the catalogue back. Two people editing two different properties in the same
// few seconds would have the second write win the whole document, losing the
// first. For one property manager and a dozen listings that is the right call;
// if the client grows a team, the fix is a row per property, and this file is
// the only thing that changes.

import { PATH } from "../../contracts/getProperties.ts";
import type { PropertyRecord } from "../property/types";
import { loadDocument, saveDocument } from "./documents.ts";
import type { SupabaseResult } from "./client";

export type PropertiesDocument = {
  version: number;
  properties: PropertyRecord[];
};

export const PROPERTIES_PATH = PATH;

/** Rejects anything that is not the document shape, rather than trusting it. */
export function parsePropertiesDocument(
  value: unknown
): PropertiesDocument | null {
  if (!value || typeof value !== "object") return null;

  const doc = value as Partial<PropertiesDocument>;
  if (!Array.isArray(doc.properties)) return null;

  return {
    version: typeof doc.version === "number" ? doc.version : 1,
    /* An entry with no slug cannot be routed to, displayed or edited. Dropped
       rather than rejecting the whole document, so one bad record cannot cost
       the client every other property they have. */
    properties: doc.properties.filter(
      (record): record is PropertyRecord =>
        Boolean(record) && typeof (record as PropertyRecord).slug === "string"
    ),
  };
}

/**
 * The catalogue, or null when the site has never saved one.
 *
 * Null and empty are different answers. Null means "no document yet, use the
 * bundled samples"; an empty array would mean "somebody deleted everything",
 * and quietly replacing that with the samples would resurrect twelve
 * properties the client had removed.
 */
export async function loadPropertiesDocument(): Promise<
  SupabaseResult<PropertyRecord[] | null>
> {
  const result = await loadDocument<unknown>(PROPERTIES_PATH);
  if (!result.ok) return result;
  if (!result.data) return { ok: true, data: null };

  const parsed = parsePropertiesDocument(result.data);
  return { ok: true, data: parsed ? parsed.properties : null };
}

export async function savePropertiesDocument(
  properties: PropertyRecord[]
): Promise<SupabaseResult<null>> {
  return saveDocument<PropertiesDocument>(PROPERTIES_PATH, {
    version: 1,
    properties,
  });
}
