// The words this CMS offers, in one place.
//
// Every list here is a set of choices the property manager picks from, and
// every one of them is read from the real Kelley Road dataset rather than
// invented for the form. That matters in both directions: an option the site
// has never used would be a promise the public page cannot keep, and a value
// already in the data that the form cannot express would make the CMS unable
// to re-save a property it just loaded.
//
// One source, so a new property type is added once and appears in the wizard,
// in validation and in the review screen together.

import type { FloorPlanAvailability } from "../../floor-plans/types";

/* ── property type ───────────────────────────────────────────
   The four kinds the twelve listings actually use. `Studio` is a property
   type here, not a bedroom count — a building of studios is an Apartment
   whose units have no bedroom; a Studio property is a single dwelling. The
   bedroom field below is what carries the count either way. */
export const PROPERTY_TYPES = ["Apartment", "Townhome", "House", "Studio"] as const;

export type PropertyTypeName = (typeof PROPERTY_TYPES)[number];

/* ── availability ────────────────────────────────────────────
   Property-level availability is authored prose on the record, and
   derive.availabilityOf() reads it with a loose match ("now" → available,
   "soon" → limited, anything else → contact). Offering exactly these three
   means what the manager picks and what the page derives cannot disagree —
   which is the whole point of not inventing a second vocabulary.

   `derives` records what each choice becomes, so the wizard can show the
   consequence rather than making the user learn it. */
export type AvailabilityChoice = {
  value: string;
  derives: FloorPlanAvailability;
  help: string;
};

export const AVAILABILITY_CHOICES: AvailabilityChoice[] = [
  {
    value: "Available Now",
    derives: "available",
    help: "Someone could move in today.",
  },
  {
    value: "Available Soon",
    derives: "limited",
    help: "Coming up, but not ready yet.",
  },
  {
    value: "Contact for Availability",
    derives: "contact",
    help: "Ask us — it depends.",
  },
];

export const AVAILABILITY_VALUES = AVAILABILITY_CHOICES.map((choice) => choice.value);

/* ── floor-plan availability ─────────────────────────────────
   A unit stores the state itself rather than prose, because the floor-plan
   section renders it directly. Same four states the type allows, with the
   wording the public section uses. */
export const UNIT_AVAILABILITY: { value: FloorPlanAvailability; label: string }[] = [
  { value: "available", label: "Available now" },
  { value: "limited", label: "Limited availability" },
  { value: "contact", label: "Contact for availability" },
  { value: "unavailable", label: "Not available" },
];

/* ── amenities ───────────────────────────────────────────────
   The eight the bundled listings use, which is also exactly what the public
   search filter offers — it builds its options from the union of these, so a
   ninth invented here would appear as a filter nothing matches.

   The manager can still add their own; see normaliseAmenity below. */
export const PREDEFINED_AMENITIES = [
  "Parking",
  "In-Unit Laundry",
  "Pet Friendly",
  "Outdoor Space",
  "Dishwasher",
  "Air Conditioning",
  "Elevator",
  "Fitness Center",
];

/**
 * The comparison key for an amenity.
 *
 * Case and surrounding space are noise: " Parking", "parking" and "Parking"
 * are one amenity, and a list that shows all three makes the property look
 * carelessly kept. Compared on this, stored as typed — so a manager who
 * writes "Rooftop BBQ" keeps their capitals.
 */
export function amenityKey(value: string): string {
  return value.trim().toLowerCase().replace(/\s+/g, " ");
}

/** Trimmed and space-collapsed, with the author's own casing intact. */
export function normaliseAmenity(value: string): string {
  return value.trim().replace(/\s+/g, " ");
}

/**
 * Adds an amenity unless it is already there under any casing.
 *
 * Returns the list unchanged when it is a duplicate, so the caller can tell
 * whether anything happened without comparing arrays.
 */
export function addAmenity(current: string[], value: string): string[] {
  const clean = normaliseAmenity(value);
  if (!clean) return current;

  const key = amenityKey(clean);
  if (current.some((item) => amenityKey(item) === key)) return current;

  return [...current, clean];
}

export function removeAmenity(current: string[], value: string): string[] {
  const key = amenityKey(value);
  return current.filter((item) => amenityKey(item) !== key);
}

export function hasAmenity(current: string[], value: string): boolean {
  const key = amenityKey(value);
  return current.some((item) => amenityKey(item) === key);
}

/**
 * The amenities on this property that are not one of the predefined ones.
 *
 * Used to render the manager's own additions as removable entries — they
 * behave like any other amenity, they simply have no checkbox waiting for
 * them.
 */
export function customAmenities(current: string[]): string[] {
  const known = new Set(PREDEFINED_AMENITIES.map(amenityKey));
  return current.filter((item) => !known.has(amenityKey(item)));
}

/* ── image categories ────────────────────────────────────────
   These drive the gallery's filter row, and derive.galleryCategories() only
   shows a chip for a category some photograph actually has. "No category" is
   the absence of one rather than a fourth value: a chip reading "No category"
   would be an authoring state shown to a visitor. */
export const IMAGE_CATEGORIES = ["Exterior", "Interior", "Community"];

/** The value the select uses for "no category", since a select needs one. */
export const NO_CATEGORY = "";

/* ── image roles ─────────────────────────────────────────────
   024's answer to "large image and small image": an asset carries the roles
   it serves, and the renderer decides the size. Uploading a photograph twice
   because the page shows it twice is the thing this prevents. */
export const ROLE_GALLERY = "gallery";
export const ROLE_FEATURED = "featured";
