// The property's photographs, as data.
//
// One list. A photograph is uploaded once and carries the roles it serves, so
// there is no "large image" and "small image" to keep in step — that pair was
// the same asset described twice, and the second description was always the
// one that went stale. The renderer decides the size; the record decides which
// picture it is.
//
// Featured is a role rather than a field for the same reason. A separate
// `featuredImage` would be a second place the same photograph lives, and the
// day somebody deletes the picture from the gallery the hero keeps showing it.
// As a role it cannot outlive the asset.

import type { GalleryImage } from "../../gallery/types";
import { ROLE_FEATURED, ROLE_GALLERY } from "./vocabulary.ts";

export type NewImage = {
  src: string;
  srcSet?: string;
  /** The library's own id where the photograph came from the Images CMS. */
  id?: string;
  /** File or asset name, used to make a first guess at a readable label. */
  name?: string;
};

/**
 * A readable first label from a file name.
 *
 * "front-exterior-2.jpg" becomes "Front exterior 2". Not clever, and not a
 * substitute for the manager typing what the picture actually is — but a
 * gallery caption reading "IMG_4821" is worse than one that guessed.
 */
export function labelFromName(name: string | undefined): string {
  const base = (name ?? "")
    .replace(/\.[a-z0-9]+$/i, "")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (!base) return "";
  return base.charAt(0).toUpperCase() + base.slice(1);
}

let counter = 0;

/** Ids only have to be unique within one property, hence the simple counter. */
function makeId(seed?: string): string {
  counter += 1;
  return seed ? `img-${seed}` : `img-${counter}`;
}

export function makeGalleryImage(input: NewImage): GalleryImage {
  return {
    id: makeId(input.id),
    src: input.src,
    srcSet: input.srcSet,
    label: labelFromName(input.name),
    alt: "",
    roles: [ROLE_GALLERY],
  };
}

/**
 * The alt text a photograph will actually be published with.
 *
 * Written by hand where somebody has written one. Otherwise built from what is
 * already known about the picture, because a caption a sighted visitor gets and
 * a screen-reader user does not is a gap nobody notices until it matters. An
 * empty alt is never emitted for a content photograph.
 */
export function altTextFor(image: GalleryImage, propertyName?: string): string {
  const own = image.alt?.trim();
  if (own) return own;

  const label = image.label?.trim();
  const category = image.category?.trim();
  const name = (propertyName ?? "").trim();

  if (label && name) return `${label} at ${name}`;
  if (label) return label;
  if (category && name) return `${category.toLowerCase()} photograph of ${name}`;
  if (name) return `Photograph of ${name}`;
  return "Property photograph";
}

/* ── changes ─────────────────────────────────────────────── */

const map = (
  images: GalleryImage[],
  id: string,
  change: (image: GalleryImage) => GalleryImage
): GalleryImage[] => images.map((image) => (image.id === id ? change(image) : image));

export function setCategory(
  images: GalleryImage[],
  id: string,
  category: string
): GalleryImage[] {
  return map(images, id, (image) => {
    const next = { ...image };
    /* No category is the absence of one rather than a fourth value: a filter
       chip reading "No category" would show the visitor an authoring state. */
    if (category.trim()) next.category = category.trim();
    else delete next.category;
    return next;
  });
}

export function setTagline(
  images: GalleryImage[],
  id: string,
  label: string
): GalleryImage[] {
  return map(images, id, (image) => ({ ...image, label: label.trim() }));
}

export function setAlt(images: GalleryImage[], id: string, alt: string): GalleryImage[] {
  return map(images, id, (image) => ({ ...image, alt: alt.trim() }));
}

const withoutRole = (roles: string[] | undefined, role: string) =>
  (roles ?? []).filter((item) => item !== role);

/**
 * Makes one photograph the featured one, and unmakes every other.
 *
 * Enforced here rather than trusted to the interface, because "exactly one" is
 * a property of the data — two featured photographs is not a thing the page
 * could render even if a button allowed it.
 */
export function setFeatured(images: GalleryImage[], id: string): GalleryImage[] {
  return images.map((image) => {
    const roles = withoutRole(image.roles, ROLE_FEATURED);
    if (image.id !== id) return { ...image, roles };
    return { ...image, roles: [...roles, ROLE_FEATURED] };
  });
}

export function clearFeatured(images: GalleryImage[]): GalleryImage[] {
  return images.map((image) => ({
    ...image,
    roles: withoutRole(image.roles, ROLE_FEATURED),
  }));
}

/**
 * Which photograph is featured.
 *
 * Falls back to the first one, which is the behaviour the page already has for
 * a property whose photographs nobody has ranked. A property with no
 * photographs returns null, and every caller handles that — the public page has
 * always had to.
 */
export function featuredImage(images: GalleryImage[] | undefined): GalleryImage | null {
  const list = images ?? [];
  return list.find((image) => image.roles?.includes(ROLE_FEATURED)) ?? list[0] ?? null;
}

/** True only when somebody actually chose, as against the fallback above. */
export function hasChosenFeatured(images: GalleryImage[] | undefined): boolean {
  return (images ?? []).some((image) => image.roles?.includes(ROLE_FEATURED));
}

/**
 * Removes a photograph.
 *
 * Nothing is promoted in its place: the fallback in `featuredImage` already
 * covers the gap, and silently making a different picture featured would be
 * the CMS making an editorial choice on the manager's behalf.
 */
export function removeImage(images: GalleryImage[], id: string): GalleryImage[] {
  return images.filter((image) => image.id !== id);
}

export function addImages(
  images: GalleryImage[] | undefined,
  incoming: NewImage[]
): GalleryImage[] {
  const existing = images ?? [];
  const known = new Set(existing.map((image) => image.src));

  /* Choosing the same library photograph twice is a slip, not an intention —
     the gallery would show it twice and the count would be wrong. */
  const fresh = incoming
    .filter((item) => item.src && !known.has(item.src))
    .map(makeGalleryImage);

  return [...existing, ...fresh];
}

/** The categories in use, for the review screen. First-seen order. */
export function categoriesUsed(images: GalleryImage[] | undefined): string[] {
  const seen: string[] = [];
  for (const image of images ?? []) {
    const category = image.category?.trim();
    if (category && !seen.includes(category)) seen.push(category);
  }
  return seen;
}
