import React, { useCallback, useState } from "react";
import {
  LuArrowDown,
  LuArrowLeft,
  LuArrowUp,
  LuCheck,
  LuEye,
  LuPencil,
  LuPlus,
  LuTrash2,
} from "react-icons/lu";

import formTemplate from "../../config/application-form--template";
import GForm from "../gh-leads/GForm";
import ApplicationMiniature from "./ApplicationMiniature";
import SelectionToast from "../shared/SelectionToast";
import ApplyDialog from "./ApplyDialog";
import QuestionEditor, {
  QUESTION_TYPES,
  needsChoices,
  typeLabel,
} from "./QuestionEditor";
import {
  activeApplication,
  addQuestion as ruleAdd,
  canDelete,
  createApplication as ruleCreate,
  deleteApplication as ruleDelete,
  deleteApplications as ruleDeleteMany,
  deleteQuestion as ruleDeleteQuestion,
  liveApplications,
  TRASH_DAYS,
  makeId,
  moveQuestion as ruleMove,
  planBulkDelete,
  renameApplication as ruleRename,
  updateQuestion as ruleUpdate,
} from "./applicationRules";
import type { Application, ApplicationQuestion, ApplicationsDocument, QuestionType } from "./types";

export type BuilderTabProps = {
  doc: ApplicationsDocument;
  /** Every change goes through here, which persists before committing state. */
  onChange: (next: ApplicationsDocument, description: string) => void;
  saving: boolean;
  /** Which application to open on mount. Omit to start on the list. */
  initialEditingId?: string;
};

type Dialog =
  | { kind: "create" }
  | { kind: "rename"; application: Application }
  | { kind: "delete"; application: Application }
  | { kind: "deleteMany"; ids: string[] }
  | { kind: "blocked"; reason: string }
  | { kind: "addType" }
  | { kind: "question"; question: ApplicationQuestion | null; type: QuestionType }
  | null;

/**
 * The Builder tab.
 *
 * Three screens in one place, which is as many as this needs: the list of
 * applications, one application's questions, and a preview. They are local
 * state rather than routes because an editor moves between them constantly and
 * a URL for "the question list" is not something anybody links to; the tab
 * itself is in the URL, which is the part worth sharing.
 */
export default function BuilderTab({
  doc,
  onChange,
  saving,
  initialEditingId,
}: BuilderTabProps) {
  const [editingId, setEditingId] = useState<string | null>(
    initialEditingId ?? null
  );
  const [previewId, setPreviewId] = useState<string | null>(null);
  const [dialog, setDialog] = useState<Dialog>(null);
  const [draftName, setDraftName] = useState("");

  /* ── delete mode ──────────────────────────────────────
     The same selection mode the Properties CMS gained in MTC-KRP-036, asked
     for here in MTC-KRP-038. What is selected is UI state and stays that way:
     it is a thing the user is doing right now, not a fact about an
     application, so it is not persisted and leaving the tab clears it. */
  const [selecting, setSelecting] = useState(false);
  const [selected, setSelected] = useState<string[]>([]);

  const leaveSelection = useCallback(() => {
    setSelecting(false);
    setSelected([]);
  }, []);

  const toggleSelected = useCallback((id: string) => {
    setSelected((current) =>
      current.includes(id)
        ? current.filter((item) => item !== id)
        : [...current, id]
    );
  }, []);

  const live = liveApplications(doc);
  const active = activeApplication(doc);
  const editing = live.find((a) => a.id === editingId) ?? null;
  const previewing = doc.applications.find((a) => a.id === previewId) ?? null;

  const close = () => setDialog(null);

  /* ── preview ─────────────────────────────────────────── */

  if (previewing) {
    return (
      <div>
        <div className="kr-apply-cms__preview-head">
          <div>
            <p className="kr-apply-cms__eyebrow">Preview</p>
            <h2 className="kr-apply-cms__section-title">{previewing.name}</h2>
            <p className="kr-apply-cms__hint">
              This is how applicants will see this application. Nothing here is
              submitted.
            </p>
          </div>
          <button
            type="button"
            className="kr-apply-cms__btn"
            onClick={() => setPreviewId(null)}
          >
            <LuArrowLeft size={14} /> Back to Builder
          </button>
        </div>

        <div className="kr-apply-cms__card kr-apply-cms__preview-body">
          {previewing.questions.length === 0 ? (
            <p className="kr-apply-cms__hint">
              This application has no questions yet.
            </p>
          ) : (
            /* The real renderer, the same one the public page uses. Submitting
               is neutralised rather than mocked: the handler resolves without
               sending, so a preview can never create an applicant record. */
            <GForm
              fields={previewing.questions}
              template={formTemplate}
              submitLabel="Submit Application"
              onSubmit={async () => {
                /* Preview only. */
              }}
            />
          )}
        </div>
      </div>
    );
  }

  /* ── one application's questions ─────────────────────── */

  if (editing) {
    const usedNames = editing.questions.map((q) => q.name);

    return (
      <div>
        <button
          type="button"
          className="kr-apply-cms__btn"
          style={{ marginBottom: 18 }}
          onClick={() => setEditingId(null)}
        >
          <LuArrowLeft size={14} /> Applications
        </button>

        <div className="kr-apply-cms__section-head">
          <div>
            <h2 className="kr-apply-cms__section-title" style={{ fontSize: 20 }}>
              {editing.name}
            </h2>
            <p className="kr-apply-cms__hint">
              {editing.id === doc.activeId
                ? "This is the application applicants are using."
                : "Not currently in use."}
            </p>
          </div>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            <button
              type="button"
              className="kr-apply-cms__btn"
              data-tutorial="rename-application"
              onClick={() => {
                setDraftName(editing.name);
                setDialog({ kind: "rename", application: editing });
              }}
            >
              <LuPencil size={14} /> Rename
            </button>
            <button
              type="button"
              className="kr-apply-cms__btn"
              onClick={() => setPreviewId(editing.id)}
            >
              <LuEye size={14} /> Preview
            </button>
          </div>
        </div>

        <p className="kr-apply-cms__eyebrow">Questions</p>

        <div
          className="kr-apply-cms__card"
          style={{ marginBottom: 18 }}
          data-tutorial="question-list"
        >
          {editing.questions.length === 0 ? (
            <div className="kr-apply-cms__empty">
              <p className="kr-apply-cms__empty-title">No questions yet</p>
              <p className="kr-apply-cms__empty-text">
                Add your first question to start building this application.
              </p>
            </div>
          ) : (
            editing.questions.map((question, index) => (
              <div className="kr-apply-cms__question" key={question.id}>
                <span className="kr-apply-cms__question-index">{index + 1}</span>

                <div className="kr-apply-cms__question-main">
                  <p className="kr-apply-cms__question-label">
                    {question.label ?? question.name}
                  </p>
                  <p className="kr-apply-cms__question-meta">
                    {typeLabel(String(question.type ?? "text"))}
                    {question.required ? " · Required" : ""}
                    {needsChoices(String(question.type))
                      ? ` · ${(question.options ?? []).length} options`
                      : ""}
                  </p>
                </div>

                <div className="kr-apply-cms__question-actions">
                  <button
                    type="button"
                    className="kr-apply-cms__qbtn"
                    title={`Edit ${question.label ?? question.name}`}
                    onClick={() =>
                      setDialog({
                        kind: "question",
                        question,
                        type: (question.type as QuestionType) ?? "text",
                      })
                    }
                  >
                    <LuPencil size={14} aria-hidden="true" /> Edit
                  </button>
                  <button
                    type="button"
                    className="kr-apply-cms__qbtn"
                    aria-label={`Move ${question.label ?? question.name} up`}
                    title="Move up"
                    disabled={index === 0 || saving}
                    onClick={() =>
                      onChange(
                        move(doc, editing.id, question.id, "up"),
                        `Moved "${question.label}" up`
                      )
                    }
                  >
                    <LuArrowUp size={15} aria-hidden="true" />
                  </button>
                  <button
                    type="button"
                    className="kr-apply-cms__qbtn"
                    aria-label={`Move ${question.label ?? question.name} down`}
                    title="Move down"
                    disabled={index === editing.questions.length - 1 || saving}
                    onClick={() =>
                      onChange(
                        move(doc, editing.id, question.id, "down"),
                        `Moved "${question.label}" down`
                      )
                    }
                  >
                    <LuArrowDown size={15} aria-hidden="true" />
                  </button>
                  <button
                    type="button"
                    className="kr-apply-cms__qbtn kr-apply-cms__qbtn--danger"
                    aria-label={`Delete ${question.label ?? question.name}`}
                    title="Delete"
                    disabled={saving}
                    onClick={() =>
                      onChange(
                        removeQuestion(doc, editing.id, question.id),
                        `Deleted "${question.label}"`
                      )
                    }
                  >
                    <LuTrash2 size={15} aria-hidden="true" />
                  </button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* The action that continues the job, so it spans the list and reads
            as the next step rather than one more button among four. */}
        <button
          type="button"
          className="kr-apply-cms__add-question"
          data-tutorial="add-question"
          onClick={() => setDialog({ kind: "addType" })}
        >
          <LuPlus size={16} aria-hidden="true" /> Add Question
        </button>

        {renderDialog()}
      </div>
    );
  }

  /* ── the list of applications ────────────────────────── */

  return (
    <div>
      <div className="kr-apply-cms__card kr-apply-cms__active" data-tutorial="active-banner">
        <div>
          <p className="kr-apply-cms__eyebrow">Active Application</p>
          <p className="kr-apply-cms__active-name">
            {active ? active.name : "None"}
          </p>
          <p className="kr-apply-cms__hint">
            This is the application people fill in on the website.
          </p>
        </div>
        {active ? (
          <button
            type="button"
            className="kr-apply-cms__btn"
            data-tutorial="preview-active"
            onClick={() => setPreviewId(active.id)}
          >
            <LuEye size={14} /> Preview
          </button>
        ) : null}
      </div>

      <div className="kr-apply-cms__section-head">
        <div>
          <h2 className="kr-apply-cms__section-title">Applications</h2>
          <p className="kr-apply-cms__hint">
            Choose which application people should currently use.
          </p>
        </div>
        <div className="kr-apply-cms__head-actions">
          {/* Cancel appears to the LEFT of Delete, as in the Properties CMS. */}
          {selecting ? (
            <button
              type="button"
              className="kr-apply-cms__btn"
              onClick={leaveSelection}
            >
              Cancel
            </button>
          ) : null}

          <button
            type="button"
            className="kr-apply-cms__btn kr-apply-cms__btn--danger"
            /* Out of selection mode this arms the mode; in it, this IS the
               delete and needs something selected. */
            disabled={saving || (selecting && selected.length === 0)}
            onClick={() =>
              selecting
                ? setDialog({ kind: "deleteMany", ids: selected })
                : setSelecting(true)
            }
          >
            <LuTrash2 size={15} /> Delete
          </button>

          {selecting ? null : (
            <button
              type="button"
              className="kr-apply-cms__btn kr-apply-cms__btn--primary"
              data-tutorial="create-application"
              onClick={() => {
                setDraftName("");
                setDialog({ kind: "create" });
              }}
            >
              <LuPlus size={15} /> Create New Application
            </button>
          )}
        </div>
      </div>

      <div className="kr-apply-cms__grid">
        {live.map((application, cardIndex) => {
          const isActive = application.id === doc.activeId;
          /* Only the first card carries the tutorial hooks. A selector
             matching several elements would spotlight whichever came
             first in the DOM, which is not a promise worth making. */
          const hook = (name: string) =>
            cardIndex === 0 ? { "data-tutorial": name } : {};

          return (
            <div
              key={application.id}
              className={`kr-apply-cms__card kr-apply-cms__app${
                isActive ? " kr-apply-cms__app--active" : ""
              }${selecting ? " kr-apply-cms__app--selectable" : ""}${
                selecting && selected.includes(application.id)
                  ? " kr-apply-cms__app--selected"
                  : ""
              }`}
              /* In selection mode the card carries the choice. It gets the
                 checkbox role rather than being made a <button>, because a
                 card here contains its own buttons in normal mode and nesting
                 those inside one would be invalid markup — the role gives the
                 same keyboard and announced state without restructuring. */
              {...(selecting
                ? {
                    role: "checkbox" as const,
                    tabIndex: 0,
                    "aria-checked": selected.includes(application.id),
                    "aria-label": `Select ${application.name} for deletion`,
                    onClick: () => toggleSelected(application.id),
                    onKeyDown: (event: React.KeyboardEvent) => {
                      if (event.key === " " || event.key === "Enter") {
                        event.preventDefault();
                        toggleSelected(application.id);
                      }
                    },
                  }
                : {})}
            >
              {selecting ? (
                <span className="kr-apply-cms__app-mark" aria-hidden="true">
                  {selected.includes(application.id) ? <LuCheck size={14} /> : null}
                </span>
              ) : null}
              {isActive ? (
                <p className="kr-apply-cms__app-flag" style={{ margin: 0 }}>
                  <LuCheck size={13} /> Active
                </p>
              ) : null}

              <div className="kr-apply-cms__app-body">
                <h3 className="kr-apply-cms__app-name">{application.name}</h3>
                <p className="kr-apply-cms__app-meta">
                  {application.questions.length}{" "}
                  {application.questions.length === 1 ? "question" : "questions"}
                </p>
                <ApplicationMiniature questions={application.questions} />
              </div>

              {/* Hidden while selecting, so a click cannot open Edit or
                  switch the active application by accident, and so there are
                  no nested controls inside the card's checkbox role. */}
              {selecting ? null : (
              <div className="kr-apply-cms__app-actions">
                <button
                  type="button"
                  className="kr-apply-cms__btn"
                  {...hook("edit-application")}
                  onClick={() => setEditingId(application.id)}
                >
                  Edit
                </button>
                <button
                  type="button"
                  className="kr-apply-cms__btn"
                  {...hook("preview-application")}
                  onClick={() => setPreviewId(application.id)}
                >
                  Preview
                </button>

                <span className="kr-apply-cms__app-spacer" />

                {!isActive ? (
                  <button
                    type="button"
                    className="kr-apply-cms__btn"
                    data-tutorial="use-this"
                    disabled={saving}
                    onClick={() =>
                      onChange(
                        { ...doc, activeId: application.id },
                        `"${application.name}" is now the active application`
                      )
                    }
                  >
                    Use This
                  </button>
                ) : null}

                <button
                  type="button"
                  className="kr-apply-cms__btn kr-apply-cms__btn--danger kr-apply-cms__btn--icon"
                  aria-label={`Delete ${application.name}`}
                  {...hook("delete-application")}
                  onClick={() => {
                    const guard = canDelete(doc, application.id);
                    setDialog(
                      guard.ok
                        ? { kind: "delete", application }
                        : { kind: "blocked", reason: guard.reason }
                    );
                  }}
                >
                  <LuTrash2 size={14} />
                </button>
              </div>
              )}
            </div>
          );
        })}
      </div>

      <SelectionToast
        count={selecting ? selected.length : 0}
        noun="application"
        classPrefix="kr-apply-cms"
      />

      {renderDialog()}
    </div>
  );

  /* ── dialogs ─────────────────────────────────────────── */

  function renderDialog() {
    if (!dialog) return null;

    if (dialog.kind === "blocked") {
      return (
        <ApplyDialog
          title="You need at least one application"
          text={dialog.reason}
          onClose={close}
        />
      );
    }

    if (dialog.kind === "create" || dialog.kind === "rename") {
      const renaming = dialog.kind === "rename";

      return (
        <ApplyDialog
          title={renaming ? "Rename Application" : "Create Application"}
          onConfirm={() => {
            const name = draftName.trim();
            if (!name) return;

            if (renaming) {
              onChange(
                rename(doc, dialog.application.id, name),
                `Renamed to "${name}"`
              );
            } else {
              const created = create(doc, name);
              onChange(created.doc, `Created "${name}"`);
              setEditingId(created.id);
            }
            close();
          }}
          confirmLabel={renaming ? "Save" : "Create"}
          confirmDisabled={!draftName.trim()}
          onClose={close}
        >
          <div className="kr-apply-cms__field">
            <label className="kr-apply-cms__label" htmlFor="kr-app-name">
              Application Name
            </label>
            <input
              id="kr-app-name"
              className="kr-apply-cms__input"
              data-tutorial="application-name"
              value={draftName}
              placeholder="Standard Rental Application"
              onChange={(event) => setDraftName(event.target.value)}
            />
          </div>
        </ApplyDialog>
      );
    }

    if (dialog.kind === "deleteMany") {
      /* Worked out BEFORE the question is asked, so a selection that cannot be
         honoured in full says so here rather than quietly doing less than it
         was told. */
      const plan = planBulkDelete(doc, dialog.ids);
      const count = plan.deleting.length;

      return (
        <ApplyDialog
          title={
            count === 1
              ? "Move this application to Trash?"
              : `Move ${count} applications to Trash?`
          }
          text={
            count === 1
              ? "It will be removed from the list."
              : "They will be removed from the list."
          }
          note={`Deletions are final, but you can put ${
            count === 1 ? "it" : "them"
          } back from the Trash for ${TRASH_DAYS} days.${
            plan.reason ? ` ${plan.reason}` : ""
          }`}
          confirmLabel={count === 1 ? "Move to Trash" : "Move to Trash"}
          confirmDanger
          confirmDisabled={count === 0}
          onConfirm={() => {
            onChange(
              ruleDeleteMany(doc, plan.deleting, Date.now()),
              count === 1
                ? "Application moved to Trash"
                : `${count} applications moved to Trash`
            );
            setDialog(null);
            leaveSelection();
          }}
          onClose={() => setDialog(null)}
        />
      );
    }

    if (dialog.kind === "delete") {
      const others = live.filter((a) => a.id !== dialog.application.id);
      const isActive = dialog.application.id === doc.activeId;

      return (
        <ApplyDialog
          title="Move this application to Trash?"
          text={`"${dialog.application.name}" will remain available in Trash for 30 days.${
            isActive
              ? ` ${others[0]?.name ?? "Another application"} will become the active application.`
              : ""
          }`}
          onConfirm={() => {
            onChange(
              softDelete(doc, dialog.application.id, others[0]?.id),
              `"${dialog.application.name}" moved to Trash`
            );
            close();
          }}
          confirmLabel="Move to Trash"
          confirmDanger
          onClose={close}
        />
      );
    }

    if (dialog.kind === "addType") {
      return (
        <ApplyDialog title="Add a Question" onClose={close}>
          <div style={{ display: "grid", gap: 8 }} data-tutorial="question-types">
            {QUESTION_TYPES.map((entry) => (
              <button
                key={entry.type}
                type="button"
                className="kr-apply-cms__btn"
                style={{
                  justifyContent: "flex-start",
                  flexDirection: "column",
                  alignItems: "flex-start",
                  gap: 2,
                  padding: "12px 14px",
                }}
                onClick={() =>
                  setDialog({ kind: "question", question: null, type: entry.type })
                }
              >
                <span>{entry.label}</span>
                <span style={{ fontWeight: 400, fontSize: 12, opacity: 0.7 }}>
                  {entry.hint}
                </span>
              </button>
            ))}
          </div>
        </ApplyDialog>
      );
    }

    if (dialog.kind === "question" && editing) {
      return (
        <QuestionEditor
          question={dialog.question}
          type={dialog.type}
          usedNames={editing.questions.map((q) => q.name)}
          onSave={(draft) => {
            if (dialog.question) {
              onChange(
                patchQuestion(doc, editing.id, dialog.question.id, draft),
                `Updated "${draft.label}"`
              );
            } else {
              const question: ApplicationQuestion = {
                ...draft,
                id: makeId("q", Date.now()),
              };
              onChange(
                appendQuestion(doc, editing.id, question),
                `Added "${draft.label}"`
              );
            }
            close();
          }}
          onClose={close}
        />
      );
    }

    return null;
  }
}

/* The rules module owns every mutation; these are thin, named call sites so
   the JSX above reads as intent rather than argument lists. */

const create = (doc: ApplicationsDocument, name: string) =>
  ruleCreate(doc, name, Date.now());

const rename = (doc: ApplicationsDocument, id: string, name: string) =>
  ruleRename(doc, id, name, Date.now());

const softDelete = (doc: ApplicationsDocument, id: string, next?: string) =>
  ruleDelete(doc, id, Date.now(), next);

const appendQuestion = (
  doc: ApplicationsDocument,
  appId: string,
  question: ApplicationQuestion
) => ruleAdd(doc, appId, question, Date.now());

const patchQuestion = (
  doc: ApplicationsDocument,
  appId: string,
  questionId: string,
  patch: Partial<ApplicationQuestion>
) => ruleUpdate(doc, appId, questionId, patch, Date.now());

const removeQuestion = (
  doc: ApplicationsDocument,
  appId: string,
  questionId: string
) => ruleDeleteQuestion(doc, appId, questionId, Date.now());

const move = (
  doc: ApplicationsDocument,
  appId: string,
  questionId: string,
  direction: "up" | "down"
) => ruleMove(doc, appId, questionId, direction, Date.now());
