import React, { useEffect, useMemo, useRef, useState } from "react";
import { LuCheck, LuSearch, LuX } from "react-icons/lu";

import type { LibraryImage } from "./useImageLibrary";

/**
 * Choose from photographs already in the CMS.
 *
 * Nate's requirement in plain terms: do not make somebody upload a picture the
 * site already has. This is the same library the Images section shows, read
 * through the same adapter — see useImageLibrary.
 *
 * A dialog rather than a second page because choosing a photograph is a
 * detour, and coming back to find the property step exactly as you left it is
 * the whole point of it being one.
 */
export type ImageLibraryDialogProps = {
  images: LibraryImage[];
  loading: boolean;
  error: string | null;
  /** Already on the property, so it cannot be added twice. */
  usedSrc: string[];
  onChoose: (chosen: LibraryImage[]) => void;
  onClose: () => void;
  onRetry: () => void;
  title?: string;
  /** Floor plans take one drawing, not a set. */
  single?: boolean;
};

export default function ImageLibraryDialog({
  images,
  loading,
  error,
  usedSrc,
  onChoose,
  onClose,
  onRetry,
  title = "Choose existing photos",
  single = false,
}: ImageLibraryDialogProps) {
  const [term, setTerm] = useState("");
  const [picked, setPicked] = useState<string[]>([]);

  const panel = useRef<HTMLDivElement | null>(null);
  const search = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    search.current?.focus();

    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };

    document.addEventListener("keydown", onKey);
    const previous = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = previous;
    };
  }, [onClose]);

  const used = useMemo(() => new Set(usedSrc), [usedSrc]);

  const shown = useMemo(() => {
    const needle = term.trim().toLowerCase();
    if (!needle) return images;
    return images.filter((image) => image.name.toLowerCase().includes(needle));
  }, [images, term]);

  const toggle = (id: string) =>
    setPicked((current) => {
      if (single) return current.includes(id) ? [] : [id];
      return current.includes(id)
        ? current.filter((item) => item !== id)
        : [...current, id];
    });

  const confirm = () => {
    const byId = new Map(images.map((image) => [image.id, image]));
    onChoose(picked.map((id) => byId.get(id)).filter(Boolean) as LibraryImage[]);
  };

  return (
    <div
      className="kr-wiz__scrim"
      onMouseDown={(event) => {
        if (!panel.current?.contains(event.target as Node)) onClose();
      }}
    >
      <div
        className="kr-wiz__dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="kr-wiz-library-title"
        ref={panel}
      >
        <div className="kr-wiz__dialog-head">
          <h3 className="kr-wiz__dialog-title" id="kr-wiz-library-title">
            {title}
          </h3>
          <button type="button" className="kr-wiz__icon-btn" onClick={onClose}>
            <LuX size={16} aria-hidden="true" />
            <span className="kr-sr-only">Close</span>
          </button>
        </div>

        <div className="kr-wiz__dialog-search">
          <LuSearch size={15} aria-hidden="true" />
          <label className="kr-sr-only" htmlFor="kr-wiz-library-search">
            Search photos by name
          </label>
          <input
            id="kr-wiz-library-search"
            ref={search}
            className="kr-props__input"
            value={term}
            placeholder="Search photos by name"
            onChange={(event) => setTerm(event.target.value)}
          />
        </div>

        <div className="kr-wiz__dialog-body">
          {loading ? (
            <p className="kr-wiz__help">Loading the image library…</p>
          ) : error ? (
            <div className="kr-wiz__trouble">
              <p>{error}</p>
              <button type="button" className="kr-props__btn" onClick={onRetry}>
                Try again
              </button>
            </div>
          ) : shown.length === 0 ? (
            <p className="kr-wiz__help">
              {images.length === 0
                ? "There are no photos in the library yet."
                : "No photos match that search."}
            </p>
          ) : (
            <ul className="kr-wiz__library">
              {shown.map((image) => {
                const already = used.has(image.src);
                const on = picked.includes(image.id);

                return (
                  <li key={image.id}>
                    <button
                      type="button"
                      className={`kr-wiz__library-item${on ? " kr-wiz__library-item--on" : ""}`}
                      aria-pressed={on}
                      disabled={already}
                      onClick={() => toggle(image.id)}
                    >
                      <img src={image.src} alt="" loading="lazy" decoding="async" />
                      <span className="kr-wiz__library-name">{image.name}</span>
                      {/* Said in words, not only by the tick, and not only by
                          the control being dimmed. */}
                      {already ? (
                        <span className="kr-wiz__library-flag">Already added</span>
                      ) : on ? (
                        <span className="kr-wiz__library-flag kr-wiz__library-flag--on">
                          <LuCheck size={12} aria-hidden="true" /> Selected
                        </span>
                      ) : null}
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </div>

        <div className="kr-wiz__dialog-foot">
          <p className="kr-wiz__help">
            {picked.length === 0
              ? "Nothing selected yet."
              : `${picked.length} selected.`}
          </p>
          <span className="kr-props__spacer" />
          <button type="button" className="kr-props__btn" onClick={onClose}>
            Cancel
          </button>
          <button
            type="button"
            className="kr-props__btn kr-props__btn--primary"
            disabled={picked.length === 0}
            onClick={confirm}
          >
            Add {picked.length || ""}
          </button>
        </div>
      </div>
    </div>
  );
}
