// The five steps of the property workflow, as configuration.
//
// MTC-KRP-025 settled the ORDER and the shape a step has to satisfy;
// MTC-KRP-026 filled the steps in. What did NOT change when the real fields
// arrived is this file's structure or the navigation — which was the point of
// building it this way. Completion is delegated to validation.ts so the tick in
// the sidebar, the tick in the dots, the Continue button and the review screen
// are four views of one rule rather than four rules that agree today.
//
// ── the image decision ───────────────────────────────────────────────────
// Nate asked whether images belong alongside the information or in their own
// step, and left the choice to us. They get their own step, third, after the
// property's information exists.
//
// The reason is failure, not tidiness. Uploads are the slowest and least
// reliable thing in this workflow: they are large, they depend on a network,
// and they can fail halfway. Anything typed before an upload that dies is at
// risk of going with it. Establishing the property's identity and text first
// means an image problem costs the user the image, not the half hour of typing
// that preceded it. It also means every uploaded file has something definite to
// attach to.
//
// The user is told this once, plainly, in step one — as a plan, not an
// apology.

import type { PropertyDraft } from "./draft";
import { canContinueFromStep, isStepSatisfied } from "./validation.ts";
import type { WizardStep } from "./wizardMachine";

export const PROPERTY_WIZARD_STEPS: WizardStep<PropertyDraft>[] = [
  {
    id: "basics",
    title: "Property Basics",
    shortTitle: "Property Basics",
    description: "The name, where it is, what kind of home it is and what it costs.",
    isComplete: (draft) => isStepSatisfied("basics", draft),
    canContinue: (draft) => canContinueFromStep("basics", draft),
  },
  {
    id: "content",
    title: "Content & Amenities",
    shortTitle: "Content & Amenities",
    description: "What you would tell someone who asked what it is like to live here.",
    isComplete: (draft) => isStepSatisfied("content", draft),
    canContinue: (draft) => canContinueFromStep("content", draft),
  },
  {
    id: "images",
    title: "Images & Floor Plan",
    shortTitle: "Images & Floor Plan",
    description: "Photographs of the property, and floor plans if you have them.",
    /* Deliberately always complete. A property with no photography yet is a
       real and ordinary state, and a workflow that refuses to finish without
       pictures pushes people into uploading anything to get past it. A floor
       plan that has been STARTED and left nameless is a different matter, and
       validation blocks that — see canContinue. */
    canContinue: (draft) => canContinueFromStep("images", draft),
  },
  {
    id: "similar",
    title: "Similar Properties",
    shortTitle: "Similar Properties",
    description: "Which other properties to suggest at the bottom of this one.",
    /* Chosen automatically unless somebody overrides it, so doing nothing here
       is a correct and complete answer. */
    canContinue: (draft) => canContinueFromStep("similar", draft),
  },
  {
    id: "review",
    title: "Review & Publish",
    shortTitle: "Review & Publish",
    description: "Check it over, then put it on the website.",
    /* Never ticked by arriving. This step is complete when the property has
       actually been published — which means a save that succeeded, not a
       screen that was reached. */
    isComplete: (draft) => draft.publication === "published",
  },
];

/** Shown in step one, so the order of the workflow is never a surprise. */
export const IMAGE_PLAN_NOTE =
  "Let's set up the property information first. You'll add photos and floor-plan images in the Images & Floor Plan step.";
