// Structure, style and colour for My Properties.
//
// The card is the Application Builder card adapted, not copied: same width band,
// same status flag across the top, same header/preview/actions rhythm, same
// restrained palette. What changes is the middle — an application previews its
// first few questions, a property previews its photograph, because that is what
// makes each recognisable at a glance.
//
// Nate's final word on geometry was that the rectangle was right, so the card is
// not forced square. The photograph carries a 16:10 frame and the card takes
// whatever height its content needs.

import theme from "../../config/opencms--theme";
import { wizardCss } from "./wizard-css";
import { wizardFormsCss } from "./wizard-forms-css";

export type PropertiesTemplate = {
  css: string;
  rootClass: string;
  labels: {
    navLabel: string;
  };
};

const radius = theme.cardRadius ?? 14;
const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-props { color: ${theme.text}; }
.kr-props *, .kr-props *::before, .kr-props *::after { box-sizing: border-box; }

/* ── page head ────────────────────────────────────────── */
.kr-props__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 20px;
}
.kr-props__title { margin: 0; font-size: 15px; font-weight: 700; letter-spacing: -0.01em; }
.kr-props__hint { margin: 4px 0 0; color: ${theme.textMuted}; font-size: 13px; line-height: 1.6; }

.kr-props__note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 18px;
  padding: 9px 12px;
  border: 1px solid ${theme.border};
  border-radius: 8px;
  background: ${theme.background};
  color: ${theme.textMuted};
  font-size: 12.5px;
  line-height: 1.5;
}
.kr-props__note-icon { flex-shrink: 0; margin-top: 1px; }
.kr-props__note strong { color: ${theme.text}; font-weight: 600; }

/* ── buttons ──────────────────────────────────────────── */
.kr-props__btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 15px;
  border-radius: 8px;
  border: 1px solid ${theme.border};
  background: ${theme.sidebar};
  color: ${theme.text};
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: border-color 160ms ${ease}, background 160ms ${ease}, color 160ms ${ease};
}
.kr-props__btn:hover:not(:disabled) { border-color: ${theme.primary}; }
.kr-props__btn:focus-visible { outline: 2px solid ${theme.primary}; outline-offset: 2px; }
.kr-props__btn:disabled { opacity: .45; cursor: not-allowed; }
.kr-props__btn--primary {
  background: ${theme.primary};
  border-color: ${theme.primary};
  color: #fff;
}
.kr-props__btn--primary:hover { background: ${theme.primaryHover}; border-color: ${theme.primaryHover}; }

/* ── form fields ────────────────────────────────
   One composition, used by every field in the plugin:

       label
       [ control, full width ]
       helper text

   These class names were being used before they were written, which is what
   made the description box render as a 20-column monospace default with its
   label beside it: an unstyled label is inline, and an unstyled textarea falls
   back to cols=20. Defining them here rather than per field means the many
   fields arriving with the property workflow inherit the same geometry. */
.kr-props__field { display: block; min-width: 0; }

/* ── the field label ─────────────────────────────────────
   The strongest thing in a field card, and deliberately a step ABOVE the
   value it introduces. It used to be 12.5px against a 14px input, so the
   question was quieter than the answer and everything on the screen had to be
   read to work out which was which. */
.kr-props__label {
  display: block;
  margin-bottom: 9px;
  color: ${theme.text};
  font-size: 16px;
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: -0.01em;
}

.kr-props__input {
  display: block;
  width: 100%;
  max-width: 100%;
  min-height: 48px;
  padding: 12px 14px;
  border: 1px solid ${theme.border};
  border-radius: 8px;
  background: ${theme.sidebar};
  color: ${theme.text};
  /* Inherited deliberately: a textarea otherwise renders in the browser
     monospace default, which is what the description box was doing. */
  font: inherit;
  /* One step below the label, and larger than it was. */
  font-size: 15px;
  line-height: 1.55;
  transition: border-color 140ms ${ease}, box-shadow 140ms ${ease};
}
/* A placeholder is a suggestion, a value is an answer. They must not look the
   same: the old sheet left both at the input colour, so a filled field and an
   empty one read alike at a glance. */
.kr-props__input::placeholder { color: ${theme.textMuted}; opacity: 1; }
.kr-props__input:hover:not(:disabled) { border-color: ${theme.textMuted}55; }
.kr-props__input:focus-visible {
  outline: none;
  border-color: ${theme.primary};
  box-shadow: 0 0 0 3px ${theme.primary}1f;
}
.kr-props__input:disabled {
  background: ${theme.background};
  color: ${theme.textMuted};
  cursor: not-allowed;
}

/* Room for a couple of sentences without being dragged, and growable by the
   person writing rather than by the layout. */
textarea.kr-props__input {
  min-height: 124px;
  resize: vertical;
  line-height: 1.6;
}

select.kr-props__input {
  appearance: none;
  padding-right: 38px;
  cursor: pointer;
  background-image: linear-gradient(45deg, transparent 50%, ${theme.textMuted} 50%),
    linear-gradient(135deg, ${theme.textMuted} 50%, transparent 50%);
  background-position: calc(100% - 19px) 50%, calc(100% - 14px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

/* ── tabs ─────────────────────────────────────────────────
   MTC-KRP-036. The same strip the Application Builder has, from the same
   component (modules/shared/CmsTabs) — only the paint is per-module, which is
   why the class prefix is a prop. Matching it here rather than importing the
   other module's stylesheet keeps the two plugins independent. */
.kr-props__tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-bottom: 22px;
  border-bottom: 1px solid ${theme.border};
}
.kr-props__tab {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 11px 14px;
  margin-bottom: -1px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: none;
  color: ${theme.textMuted};
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: color 160ms ${ease}, border-color 160ms ${ease};
}
.kr-props__tab:hover { color: ${theme.text}; }
.kr-props__tab[aria-selected="true"] {
  color: ${theme.text};
  border-bottom-color: ${theme.primary};
}
.kr-props__tab:focus-visible { outline: 2px solid ${theme.primary}; outline-offset: -2px; }
.kr-props__tab-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: ${theme.background};
  color: ${theme.textMuted};
  font-size: 11px;
  font-weight: 700;
}
.kr-props__tab[aria-selected="true"] .kr-props__tab-count {
  background: ${theme.primary};
  color: #fff;
}

/* ── the action row ───────────────────────────────────── */
.kr-props__actions-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}
.kr-props__actions-bar .kr-props__btn { white-space: nowrap; }

.kr-props__problem {
  margin: 0 0 16px;
  padding: 11px 14px;
  border: 1px solid ${theme.danger}40;
  border-left: 3px solid ${theme.danger};
  border-radius: 8px;
  background: ${theme.danger}0a;
  color: ${theme.danger};
  font-size: 13.5px;
  line-height: 1.6;
}

/* ── selection mode ───────────────────────────────────────
   Only while deleting. Ordinary browsing is untouched: without
   --selectable the card has no pointer, no tint and no hover state beyond
   what it always had. */
.kr-props__card--selectable {
  appearance: none;
  width: 100%;
  padding: 0;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
  position: relative;
  transition: border-color 160ms ${ease}, box-shadow 160ms ${ease};
}
/* The hover preview Nate asked for, at a strength that still lets you read the
   property you are about to delete — the point is to see WHICH card you are
   choosing, so covering it defeats the exercise. */
.kr-props__card--selectable:hover { border-color: ${theme.danger}80; }
.kr-props__card--selectable:hover .kr-props__media::after,
.kr-props__card--selected .kr-props__media::after {
  content: "";
  position: absolute;
  inset: 0;
  background: ${theme.danger};
  opacity: .18;
  pointer-events: none;
}
.kr-props__card--selectable:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: 2px;
}

/* Selected: a red border, as specified — plus a tick, because a border is a
   colour and colour must not be the only thing carrying state. */
.kr-props__card--selected {
  border-color: ${theme.danger};
  box-shadow: 0 0 0 1px ${theme.danger};
}
.kr-props__select-mark {
  position: absolute;
  top: 10px;
  right: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 1px solid ${theme.border};
  background: ${theme.sidebar};
  color: transparent;
}
.kr-props__card--selected .kr-props__select-mark {
  background: ${theme.danger};
  border-color: ${theme.danger};
  color: #fff;
}

/* ── the selection toast ──────────────────────────────────
   Shaped like the upload toasts in gh-image so the CMS has one idea of what a
   transient message is; bottom-centre rather than top-right because it follows
   the cards being clicked. */
.kr-props__toast {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 18px;
  border-radius: 999px;
  background: ${theme.primary};
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  box-shadow: 0 10px 32px rgba(15, 23, 42, .24);
}
.kr-props__toast-icon { display: inline-flex; flex-shrink: 0; }
.kr-props__toast-text { white-space: nowrap; }

/* ── trash ────────────────────────────────────────────── */
.kr-props__trash {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-props__trash-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
  background: ${theme.sidebar};
  border: 1px solid ${theme.border};
  border-radius: ${radius}px;
}
.kr-props__trash-media {
  width: 62px;
  height: 46px;
  flex-shrink: 0;
  border-radius: 6px;
  overflow: hidden;
  background: ${theme.background};
}
.kr-props__trash-media img { width: 100%; height: 100%; object-fit: cover; display: block; }
.kr-props__trash-body { flex: 1; min-width: 160px; }
.kr-props__trash-name { margin: 0; font-size: 14.5px; font-weight: 600; }
.kr-props__trash-meta { margin: 3px 0 0; color: ${theme.textMuted}; font-size: 12.5px; }
.kr-props__trash-left {
  margin: 0;
  color: ${theme.textMuted};
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.kr-props__trash-left--soon { color: ${theme.danger}; }

@media (max-width: 640px) {
  .kr-props__actions-bar { width: 100%; }
  .kr-props__actions-bar .kr-props__btn { flex: 1; justify-content: center; min-height: 44px; }
  .kr-props__tab { padding: 11px 11px; font-size: 13.5px; }
  .kr-props__trash-row { align-items: flex-start; }
  .kr-props__trash-row .kr-props__btn { width: 100%; justify-content: center; min-height: 44px; }
  /* A toast pinned to the bottom centre would sit under a thumb on a phone. */
  .kr-props__toast { left: 16px; right: 16px; transform: none; justify-content: center; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-props__tab, .kr-props__card--selectable { transition: none; }
}

/* ── the grid ─────────────────────────────────────────────
   Columns sized rather than counted, the same rule the dashboard uses since
   MTC-KRP-022, so the count follows the space instead of a breakpoint. The
   minimum is the Application Builder card's comfortable width. */
.kr-props__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(290px, 1fr));
  gap: 18px;
  align-items: start;
}

/* ── the card ─────────────────────────────────────────── */
.kr-props__card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: ${theme.sidebar};
  border: 1px solid ${theme.border};
  border-radius: ${radius}px;
  box-shadow: 0 1px 3px rgba(15, 23, 42, .04);
}

/* The status band, exactly where the Application Builder puts ACTIVE. Charcoal
   for published, outlined for draft — status by tone and word, never by colour
   alone. */
.kr-props__flag {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.kr-props__flag--published { background: ${theme.primary}; color: #fff; }
.kr-props__flag--draft {
  background: ${theme.background};
  color: ${theme.textMuted};
  border-bottom: 1px solid ${theme.border};
}

.kr-props__body { padding: 15px 17px 0; }
.kr-props__name {
  margin: 0 0 3px;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.01em;
  line-height: 1.3;
  /* Two lines, then ellipsis: a long name must not push every card in the row
     out of shape, and shrinking the type instead would be worse. */
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  word-break: break-word;
}
.kr-props__place {
  margin: 0 0 13px;
  color: ${theme.textMuted};
  font-size: 12.5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── the photograph ───────────────────────────────────────
   Where an application card previews its first questions, a property previews
   its photograph. 16:10 so the card stays a restrained rectangle rather than
   the tall portrait a 4:3 or square frame would make of it. */
.kr-props__media {
  position: relative;
  aspect-ratio: 16 / 10;
  border-radius: 9px;
  overflow: hidden;
  background: ${theme.background};
  border: 1px solid ${theme.border};
}
.kr-props__image { width: 100%; height: 100%; object-fit: cover; display: block; }

/* Drawn rather than a broken image icon, and rather than a remote placeholder
   the CMS would have to fetch. */
.kr-props__placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  color: ${theme.textMuted};
  background:
    repeating-linear-gradient(
      45deg,
      ${theme.border}55 0 6px,
      transparent 6px 12px
    );
}
.kr-props__placeholder span {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
}

/* ── metadata ─────────────────────────────────────────── */
.kr-props__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  margin: 13px 0 0;
  padding: 0;
  list-style: none;
  color: ${theme.textMuted};
  font-size: 12.5px;
}
.kr-props__meta li { display: inline-flex; align-items: center; gap: 6px; }
.kr-props__meta li + li::before {
  content: "";
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: ${theme.border};
}

.kr-props__pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 12px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid ${theme.border};
  font-size: 11.5px;
  font-weight: 600;
}
.kr-props__pill::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  flex-shrink: 0;
}
.kr-props__pill--now { color: #15803d; background: #f0fdf4; border-color: #bbf7d0; }
.kr-props__pill--soon { color: ${theme.primaryHover}; background: ${theme.primaryHover}14; border-color: ${theme.primaryHover}55; }
.kr-props__pill--none { color: ${theme.textMuted}; }

/* ── actions ──────────────────────────────────────────── */
.kr-props__actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: auto;
  padding: 15px 17px;
}
.kr-props__actions .kr-props__btn { font-size: 12.5px; padding: 8px 13px; }
.kr-props__spacer { flex: 1; }

/* ── empty state ──────────────────────────────────────── */
.kr-props__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 240px;
  padding: 40px 24px;
  text-align: center;
  background: ${theme.sidebar};
  border: 1px solid ${theme.border};
  border-radius: ${radius}px;
}
.kr-props__empty-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  margin-bottom: 15px;
  border-radius: 50%;
  background: ${theme.primary}0f;
  color: ${theme.textMuted};
}
.kr-props__empty-title { margin: 0 0 6px; font-size: 16px; font-weight: 700; }
.kr-props__empty-text {
  margin: 0 auto 20px;
  max-width: 34ch;
  color: ${theme.textMuted};
  font-size: 13.5px;
  line-height: 1.65;
}

/* ── the add / edit shell ─────────────────────────────── */
.kr-props__shell { max-width: 640px; }
.kr-props__shell-card {
  padding: 26px;
  background: ${theme.sidebar};
  border: 1px solid ${theme.border};
  border-radius: ${radius}px;
}
.kr-props__shell-title { margin: 0 0 8px; font-size: 19px; font-weight: 800; letter-spacing: -0.02em; }
.kr-props__shell-text {
  margin: 0 0 18px;
  color: ${theme.textMuted};
  font-size: 13.5px;
  line-height: 1.7;
}
.kr-props__steps {
  margin: 0 0 22px;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 1px;
  background: ${theme.border};
  border: 1px solid ${theme.border};
  border-radius: 9px;
  overflow: hidden;
}
.kr-props__steps li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  background: ${theme.sidebar};
  font-size: 13.5px;
}
.kr-props__steps b {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  border-radius: 50%;
  background: ${theme.background};
  color: ${theme.textMuted};
  font-size: 11px;
  font-weight: 700;
}
.kr-props__shell-actions { display: flex; flex-wrap: wrap; gap: 10px; }

/* ── narrow screens ─────────────────────────────────────
   Follows the MTC-KRP-019 contract: one card per row, 44px targets, and
   nothing that makes the page scroll sideways. */
@media (max-width: 640px) {
  .kr-props__grid { grid-template-columns: minmax(0, 1fr); gap: 14px; }
  .kr-props__head { align-items: stretch; }
  .kr-props__head .kr-props__btn--primary { justify-content: center; min-height: 44px; }
  .kr-props__actions { flex-wrap: wrap; }
  .kr-props__actions .kr-props__btn { flex: 1 1 auto; justify-content: center; min-height: 42px; }
  .kr-props__spacer { display: none; }
  .kr-props__empty { min-height: 200px; padding: 32px 20px; }
  .kr-props__shell-actions .kr-props__btn { flex: 1 1 auto; justify-content: center; min-height: 44px; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-props__btn { transition: none; }
}
`;

const template: PropertiesTemplate = {
  /* The workflow's styles ride with the plugin's, so the view emits one sheet
     and the wizard is never rendered unstyled on a deep link into a step. */
  css: css + wizardCss + wizardFormsCss,
  rootClass: "kr-props",
  labels: { navLabel: "Properties" },
};

export default template;
