import type React from "react";

import theme from "../../config/opencms--theme";

/**
 * The dashboard card's shared look.
 *
 * The previews disagreed with each other before this existed: Images and Leads
 * used a 42px icon with a 17px heading and an action on the right of the header,
 * while the two newer cards used a 34px icon, a 14px heading and an action at
 * the bottom. Side by side on one screen that read as three cards and two
 * strangers.
 *
 * Slot components receive no props and the dashboard does not emit any plugin's
 * stylesheet, so a preview has to carry its own inline styles. Sharing them from
 * here is what stops the next card drifting again.
 *
 * Width and outer spacing are deliberately absent — the dashboard grid owns
 * those, and a card that set its own would fight it.
 */
export const dashCard: Record<string, React.CSSProperties> = {
  card: {
    padding: theme.cardPadding || 24,
    borderRadius: theme.cardRadius || 14,
    border: `1px solid ${theme.border}`,
    background: theme.sidebar,
    boxShadow: "0 1px 3px rgba(15,23,42,.04)",
    color: theme.text,
  },
  header: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    gap: 16,
  },
  headingWrap: { display: "flex", alignItems: "center", gap: 14, minWidth: 0 },
  icon: {
    width: 42,
    height: 42,
    flex: "0 0 42px",
    borderRadius: 10,
    background: `${theme.primary}14`,
    color: theme.primary,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },
  title: { margin: 0, color: theme.text, fontSize: 17, fontWeight: 800 },
  subtitle: {
    margin: "4px 0 0",
    color: theme.textMuted,
    fontSize: 13,
    lineHeight: 1.5,
  },
  action: {
    display: "inline-flex",
    alignItems: "center",
    gap: 7,
    color: theme.text,
    fontSize: 13,
    fontWeight: 700,
    textDecoration: "none",
    whiteSpace: "nowrap",
    flexShrink: 0,
  },
  /* One rule for the space between the header and whatever a card shows below
     it, which is where the vertical rhythm was drifting. */
  body: {
    marginTop: 18,
    paddingTop: 18,
    borderTop: `1px solid ${theme.border}`,
  },
  eyebrow: {
    margin: 0,
    color: theme.textMuted,
    fontSize: 11,
    fontWeight: 700,
    letterSpacing: "0.12em",
    textTransform: "uppercase",
  },
  lead: { margin: "6px 0 0", fontSize: 17, fontWeight: 700, lineHeight: 1.25 },
  meta: { margin: "10px 0 0", color: theme.textMuted, fontSize: 13 },
  figure: { margin: 0, fontSize: 26, fontWeight: 800, lineHeight: 1.1 },
};
