import React from "react";
import { LuRotateCcw, LuTrash2 } from "react-icons/lu";

import { daysRemaining, trashedNewestFirst, TRASH_DAYS } from "./propertyRules";
import type { PropertyCardModel } from "./propertyCard";

export type TrashedProperty = PropertyCardModel & { deletedAt?: string | null };

export type PropertiesTrashTabProps = {
  properties: TrashedProperty[];
  onRestore: (slug: string) => void;
  busy: boolean;
  /** Passed in so the list and the countdown agree, and so tests can fix it. */
  now: number;
};

const dateFormat = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
});

/**
 * Trash.
 *
 * The countdown is derived from each record's `deletedAt` on every render
 * rather than stored, so it is right whenever the CMS is opened rather than
 * right only if something kept counting.
 *
 * Worth being precise about what this does and does not do, the same way the
 * Application Builder's Trash is: an expired property stops being listed and
 * stops being restorable, but nothing here removes it from storage. Actually
 * purging it belongs to whatever owns the stored document, and pretending a
 * React render does it would be a lie about where the data lives.
 */
export default function PropertiesTrashTab({
  properties,
  onRestore,
  busy,
  now,
}: PropertiesTrashTabProps) {
  const trashed = trashedNewestFirst(properties, now);

  if (trashed.length === 0) {
    return (
      <div className="kr-props__empty">
        <span className="kr-props__empty-icon" aria-hidden="true">
          <LuTrash2 size={21} />
        </span>
        <h2 className="kr-props__empty-title">Trash is empty</h2>
        <p className="kr-props__empty-text">
          Deleted properties stay here for {TRASH_DAYS} days, so you can put one
          back if you change your mind.
        </p>
      </div>
    );
  }

  return (
    <>
      <div className="kr-props__head">
        <div>
          <h2 className="kr-props__title">Trash</h2>
          <p className="kr-props__hint">
            {trashed.length} {trashed.length === 1 ? "property" : "properties"}{" "}
            waiting. Each one can be put back for {TRASH_DAYS} days.
          </p>
        </div>
      </div>

      <ul className="kr-props__trash">
        {trashed.map((property) => {
          const left = daysRemaining(property.deletedAt as string, now);

          return (
            <li key={property.slug} className="kr-props__trash-row">
              <div className="kr-props__trash-media">
                {property.image ? (
                  <img
                    src={property.image}
                    alt=""
                    loading="lazy"
                    decoding="async"
                  />
                ) : null}
              </div>

              <div className="kr-props__trash-body">
                <p className="kr-props__trash-name">{property.title}</p>
                <p className="kr-props__trash-meta">
                  {property.location}
                  {property.deletedAt ? (
                    <>
                      {" · Deleted "}
                      {dateFormat.format(new Date(property.deletedAt))}
                    </>
                  ) : null}
                </p>
              </div>

              {/* Said in words rather than only shown as a bar, and the wording
                  changes at the point where it starts to matter. */}
              <p
                className={`kr-props__trash-left${
                  left <= 7 ? " kr-props__trash-left--soon" : ""
                }`}
              >
                {left === 0
                  ? "Removed today"
                  : left === 1
                    ? "1 day left"
                    : `${left} days left`}
              </p>

              <button
                type="button"
                className="kr-props__btn"
                disabled={busy}
                onClick={() => onRestore(property.slug)}
              >
                <LuRotateCcw size={13} aria-hidden="true" /> Put back
                <span className="kr-sr-only">{property.title}</span>
              </button>
            </li>
          );
        })}
      </ul>
    </>
  );
}
