// @ppm--version--1.0

export type ThreeStageResult =
  | "thumbnail"
  | "raw"
  | "final";

export type ThreeStageParams = {
  id: string;
  finalUrl: string;
  originalFileName: string;
  checkUrl: (url: string) => Promise<boolean>;
  setStage: (
    id: string,
    stage: ThreeStageResult,
    url: string
  ) => void;
  complete: (id: string) => void;
};

const timestamp = () =>
  new Date().toISOString();

const log = (
  label: string,
  ...args: any[]
) => {
  console.log(
    `[three-stage ${timestamp()}] ${label}`,
    ...args
  );
};

export function getRawImageUrl(
  finalUrl: string,
  originalFileName: string
): string {
  const match = finalUrl.match(
    /^https:\/\/[^./]+\.github\.io\/([^/]+)\//
  );

  if (!match) {
    return "";
  }

  const repo = match[1];

  return `https://raw.githubusercontent.com/MTCMarketing/${repo}/refs/heads/main/originals/${originalFileName}`;
}

export function checkImageUrl(
  url: string
): Promise<boolean> {
  return new Promise(resolve => {
    const started = performance.now();

    const separator =
      url.includes("?") ? "&" : "?";

    const testUrl =
      `${url}${separator}ppm_check=${Date.now()}`;

    log("CHECK START", {
      url,
      testUrl,
    });

    const img = new window.Image();

    img.onload = () => {
      const elapsed =
        Math.round(performance.now() - started);

      log("CHECK OK", {
        url,
        elapsedMs: elapsed,
        naturalWidth: img.naturalWidth,
        naturalHeight: img.naturalHeight,
      });

      resolve(true);
    };

    img.onerror = event => {
      const elapsed =
        Math.round(performance.now() - started);

      log("CHECK FAIL", {
        url,
        elapsedMs: elapsed,
        event,
      });

      resolve(false);
    };

    img.src = testUrl;
  });
}


function removeRawTestButton(
  id: string
) {
  if (typeof document === "undefined") {
    return;
  }

  document
    .getElementById(
      `ppm-three-stage-test-${id}`
    )
    ?.remove();
}

export async function runThreeStageImageFlow({
  id,
  finalUrl,
  originalFileName,
  checkUrl,
  setStage,
  complete,
}: ThreeStageParams): Promise<ThreeStageResult> {
  const rawUrl =
    getRawImageUrl(
      finalUrl,
      originalFileName
    );

  log("POLL START", {
    id,
    finalUrl,
    rawUrl,
  });

  log("POLL FINAL CHECK", {
    id,
    url: finalUrl,
  });

  const finalAvailable =
    await checkUrl(finalUrl);

  log("POLL FINAL RESULT", {
    id,
    available: finalAvailable,
    url: finalUrl,
  });

  if (finalAvailable) {
    log("STAGE 3 ACTIVATED", {
      id,
      finalUrl,
    });

    setStage(
      id,
      "final",
      finalUrl
    );

    removeRawTestButton(id);
    complete(id);

    return "final";
  }

  log("POLL RAW CHECK", {
    id,
    url: rawUrl,
  });

  const rawAvailable =
    await checkUrl(rawUrl);

  log("POLL RAW RESULT", {
    id,
    available: rawAvailable,
    url: rawUrl,
  });

  if (rawAvailable) {
    log("STAGE 2 ACTIVATED", {
      id,
      rawUrl,
    });

    setStage(
      id,
      "raw",
      rawUrl
    );

    return "raw";
  }

  log("STAGE 1 RETAINED", {
    id,
    reason:
      "Neither final nor raw image is currently loadable",
  });

  return "thumbnail";
}
