import React from "react";
import CmsLayout from "./CmsLayout";
import { DashboardView } from "./Dashboard";
import SettingsView from "./Settings";
import { cmsPluginViews } from "./plugins";
import { resolveCmsView, toDashboardRoute } from "./resolveCmsView";

export default function CmsRouter({
  pathname,
}: {
  pathname: string;
}) {
  const relative = toDashboardRoute(pathname);

  if (!relative) {
    return (
      <CmsLayout title="Dashboard" pathname={pathname}>
        <DashboardView />
      </CmsLayout>
    );
  }

  if (relative === "settings") {
    return (
      <CmsLayout title="Settings" pathname={pathname}>
        <SettingsView />
      </CmsLayout>
    );
  }

  /* Exact match first, then a view may claim its own subtree at a segment
     boundary - see resolveCmsView, which is where the rules and their tests
     live. A view that owns sub-pages (tabs, a record detail) reads them off
     the pathname it is already given. */
  const resolved = resolveCmsView(cmsPluginViews, pathname);

  if (resolved) {
    const View = resolved.view.component;
    const view = resolved.view;

    return (
      <CmsLayout title={view.label} pathname={pathname}>
        <View pathname={pathname} />
      </CmsLayout>
    );
  }

  return (
    <CmsLayout title="Not Found" pathname={pathname}>
      <div>That CMS view is not installed.</div>
    </CmsLayout>
  );
}