import React, { useEffect, useRef, useState } from "react";
import {
  LuImage,
  LuImagePlus,
  LuLibraryBig,
  LuPlus,
  LuStar,
  LuTrash2,
  LuTriangleAlert,
  LuUpload,
} from "react-icons/lu";

import { NumberField, SelectField, TextArea, TextField, errorFor } from "../Field";
import ImageLibraryDialog from "../ImageLibraryDialog";
import {
  addFloorPlan,
  removeFloorPlan,
  setFloorPlanImage,
  updateFloorPlan,
} from "../floorPlans";
import {
  addImages,
  altTextFor,
  hasChosenFeatured,
  removeImage,
  setAlt,
  setCategory,
  setFeatured,
  setTagline,
} from "../images";
import type { StepProps } from "./types";
import { useImageLibrary } from "../useImageLibrary";
import type { LibraryImage } from "../useImageLibrary";
import { IMAGE_CATEGORIES, ROLE_FEATURED, UNIT_AVAILABILITY } from "../vocabulary";

/**
 * Page 3 — photographs and floor plans.
 *
 * Every photograph here is an ordinary CMS image. Uploading goes through the
 * same adapter as the Images section, so a picture added while setting up a
 * property is available to every other property afterwards, and a picture
 * already in the library can simply be chosen. There is no such thing as a
 * "wizard image".
 *
 * Floor plans sit on this step because a floor plan is mostly a drawing, and
 * because splitting them onto a sixth step would separate "the picture of the
 * unit" from "the unit" for no reason a manager would recognise.
 */
export default function ImagesStep({ draft, onChange, issues }: StepProps) {
  const images = draft.images ?? [];
  const plans = draft.floorPlans ?? [];

  const { library, loading, loadError, busy, load, upload } = useImageLibrary();

  const [picking, setPicking] = useState<null | { forPlan?: string }>(null);
  const [failures, setFailures] = useState<{ name: string; reason: string }[]>([]);
  const [dragging, setDragging] = useState(false);

  const fileInput = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    void load();
  }, [load]);

  const takeFiles = async (files: FileList | File[] | null) => {
    const list = Array.from(files ?? []).filter((file) =>
      file.type.startsWith("image/")
    );
    if (list.length === 0) return;

    setFailures([]);
    const report = await upload(list);

    if (report.uploaded.length) {
      onChange({
        images: addImages(
          draft.images,
          report.uploaded.map((item) => ({ src: item.src, name: item.name }))
        ),
      });
    }

    /* Reported rather than swallowed. An upload that silently does nothing is
       the single most confusing thing a CMS can do. */
    setFailures(report.failures);
  };

  const chooseFromLibrary = (chosen: LibraryImage[]) => {
    if (picking?.forPlan) {
      const [first] = chosen;
      if (first) {
        onChange({
          floorPlans: setFloorPlanImage(plans, picking.forPlan, {
            src: first.src,
            alt: first.name,
          }),
        });
      }
    } else {
      onChange({
        images: addImages(
          draft.images,
          chosen.map((item) => ({ src: item.src, name: item.name, id: item.id }))
        ),
      });
    }

    setPicking(null);
  };

  return (
    <div className="kr-wiz__fields">
      {/* ── adding photographs ──────────────────────────── */}
      <div
        className={`kr-wiz__drop${dragging ? " kr-wiz__drop--over" : ""}`}
        onDragOver={(event) => {
          event.preventDefault();
          setDragging(true);
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(event) => {
          event.preventDefault();
          setDragging(false);
          void takeFiles(event.dataTransfer?.files ?? null);
        }}
      >
        <span className="kr-wiz__drop-icon" aria-hidden="true">
          <LuUpload size={22} />
        </span>
        <p className="kr-wiz__drop-title">Drag photos here</p>
        <p className="kr-wiz__help">JPG, PNG or WebP. You can add several at once.</p>

        <div className="kr-wiz__drop-actions">
          {/* A real file input, labelled, rather than a div that opens one —
              so the keyboard and the screen reader both reach it. */}
          <input
            id="kr-wiz-photos"
            ref={fileInput}
            className="kr-sr-only"
            type="file"
            accept="image/*"
            multiple
            onChange={(event) => {
              void takeFiles(event.target.files);
              event.target.value = "";
            }}
          />
          <button
            type="button"
            className="kr-props__btn kr-props__btn--primary"
            onClick={() => fileInput.current?.click()}
          >
            <LuImagePlus size={14} aria-hidden="true" /> Upload photos
          </button>

          <button
            type="button"
            className="kr-props__btn"
            onClick={() => setPicking({})}
          >
            <LuLibraryBig size={14} aria-hidden="true" /> Choose existing
          </button>
        </div>
      </div>

      {busy ? (
        <p className="kr-wiz__note kr-wiz__note--tight" role="status">
          <span>{busy}</span>
        </p>
      ) : null}

      {failures.length > 0 ? (
        <div className="kr-wiz__trouble" role="alert">
          <p className="kr-wiz__trouble-title">
            <LuTriangleAlert size={15} aria-hidden="true" />
            {failures.length === 1
              ? "One photo could not be uploaded"
              : `${failures.length} photos could not be uploaded`}
          </p>
          <ul>
            {failures.map((failure) => (
              <li key={failure.name}>
                <strong>{failure.name}</strong> — {failure.reason}
              </li>
            ))}
          </ul>
          <p className="kr-wiz__help">
            Image storage is not connected for this site yet. Everything else on
            this property still works, and photos can be added once it is.
          </p>
        </div>
      ) : null}

      {/* ── the photographs ─────────────────────────────── */}
      {images.length > 0 ? (
        <fieldset className="kr-wiz__group">
          <legend className="kr-props__label">
            Photos ({images.length})
          </legend>
          <p className="kr-wiz__help kr-wiz__help--above">
            {hasChosenFeatured(images)
              ? "The featured photo is the one used at the top of the page."
              : "No featured photo chosen, so the first one will be used."}
          </p>

          <ul className="kr-wiz__photos">
            {images.map((image) => {
              const featured = image.roles?.includes(ROLE_FEATURED) ?? false;

              return (
                <li
                  key={image.id}
                  className={`kr-wiz__photo${featured ? " kr-wiz__photo--featured" : ""}`}
                >
                  <div className="kr-wiz__photo-media">
                    <img
                      src={image.src}
                      alt={altTextFor(image, draft.title)}
                      loading="lazy"
                      decoding="async"
                    />
                    {featured ? (
                      <p className="kr-wiz__photo-flag">
                        <LuStar size={12} aria-hidden="true" /> Featured
                      </p>
                    ) : null}
                  </div>

                  <div className="kr-wiz__photo-fields">
                    <SelectField
                      id={`kr-wiz-image-${image.id}-category`}
                      label="Where is this?"
                      value={image.category ?? ""}
                      onChange={(category) =>
                        onChange({ images: setCategory(images, image.id, category) })
                      }
                      options={IMAGE_CATEGORIES.map((category) => ({
                        value: category,
                        label: category,
                      }))}
                      placeholder="No category"
                    />

                    <TextField
                      id={`kr-wiz-image-${image.id}-label`}
                      label="Caption"
                      optional
                      value={image.label ?? ""}
                      placeholder="Front exterior"
                      onChange={(label) =>
                        onChange({ images: setTagline(images, image.id, label) })
                      }
                    />

                    <TextField
                      id={`kr-wiz-image-${image.id}-alt`}
                      label="Describe it for screen readers"
                      optional
                      value={image.alt ?? ""}
                      placeholder={altTextFor(image, draft.title)}
                      onChange={(alt) =>
                        onChange({ images: setAlt(images, image.id, alt) })
                      }
                      help="Leave blank to use the caption."
                    />

                    <div className="kr-wiz__photo-actions">
                      <button
                        type="button"
                        className="kr-props__btn"
                        disabled={featured}
                        onClick={() =>
                          onChange({ images: setFeatured(images, image.id) })
                        }
                      >
                        <LuStar size={13} aria-hidden="true" />
                        {featured ? "Featured" : "Set as featured"}
                      </button>

                      <button
                        type="button"
                        className="kr-props__btn kr-props__btn--quiet"
                        onClick={() =>
                          onChange({ images: removeImage(images, image.id) })
                        }
                      >
                        <LuTrash2 size={13} aria-hidden="true" /> Remove
                        <span className="kr-sr-only">
                          {image.label || "this photo"}
                        </span>
                      </button>
                    </div>
                  </div>
                </li>
              );
            })}
          </ul>
        </fieldset>
      ) : null}

      {/* ── floor plans ─────────────────────────────────── */}
      <fieldset className="kr-wiz__group">
        <legend className="kr-props__label">Floor plans</legend>
        <p className="kr-wiz__help kr-wiz__help--above">
          Only if this property has more than one layout, or you want to show
          the unit&rsquo;s own size and price. A floor plan does not need a
          drawing — the page shows its details either way. You can publish
          without any of this.
        </p>

        {plans.length > 0 ? (
          <ol className="kr-wiz__plans">
            {plans.map((plan, index) => (
              <li key={plan.id} className="kr-wiz__plan">
                <div className="kr-wiz__plan-head">
                  <h4 className="kr-wiz__plan-title">
                    {plan.label?.trim() || `Floor plan ${index + 1}`}
                  </h4>
                  <button
                    type="button"
                    className="kr-props__btn kr-props__btn--quiet"
                    onClick={() =>
                      onChange({ floorPlans: removeFloorPlan(plans, plan.id) })
                    }
                  >
                    <LuTrash2 size={13} aria-hidden="true" /> Remove
                    <span className="kr-sr-only">
                      {plan.label || `floor plan ${index + 1}`}
                    </span>
                  </button>
                </div>

                <div className="kr-wiz__fields">
                  <TextField
                    id={`kr-wiz-plan-${plan.id}-label`}
                    label="Name"
                    value={plan.label}
                    placeholder="1 Bed + Den"
                    onChange={(label) =>
                      onChange({ floorPlans: updateFloorPlan(plans, plan.id, { label }) })
                    }
                    error={errorFor(issues, `kr-wiz-plan-${plan.id}-label`)}
                    help="What the tab on the property page says."
                  />

                  <TextArea
                    id={`kr-wiz-plan-${plan.id}-description`}
                    label="Description"
                    optional
                    rows={2}
                    value={plan.description}
                    placeholder="An open plan with a walled sleeping alcove and a full-width kitchen."
                    onChange={(description) =>
                      onChange({
                        floorPlans: updateFloorPlan(plans, plan.id, { description }),
                      })
                    }
                  />

                  <div className="kr-wiz__row">
                    <NumberField
                      id={`kr-wiz-plan-${plan.id}-bedrooms`}
                      label="Bedrooms"
                      value={plan.bedrooms}
                      min={0}
                      step={1}
                      onChange={(bedrooms) =>
                        onChange({
                          floorPlans: updateFloorPlan(plans, plan.id, {
                            bedrooms: bedrooms ?? 0,
                          }),
                        })
                      }
                      help="0 for a studio."
                    />

                    <NumberField
                      id={`kr-wiz-plan-${plan.id}-bathrooms`}
                      label="Bathrooms"
                      value={plan.bathrooms}
                      min={0}
                      step={0.5}
                      onChange={(bathrooms) =>
                        onChange({
                          floorPlans: updateFloorPlan(plans, plan.id, {
                            bathrooms: bathrooms ?? 0,
                          }),
                        })
                      }
                    />

                    <NumberField
                      id={`kr-wiz-plan-${plan.id}-area`}
                      label="Square feet"
                      value={plan.squareFeet}
                      min={1}
                      step={1}
                      onChange={(squareFeet) =>
                        onChange({
                          floorPlans: updateFloorPlan(plans, plan.id, {
                            squareFeet: squareFeet ?? 0,
                          }),
                        })
                      }
                      error={errorFor(issues, `kr-wiz-plan-${plan.id}-area`)}
                    />
                  </div>

                  <div className="kr-wiz__row">
                    <SelectField
                      id={`kr-wiz-plan-${plan.id}-availability`}
                      label="Availability"
                      value={plan.availability}
                      onChange={(value) =>
                        onChange({
                          floorPlans: updateFloorPlan(plans, plan.id, {
                            availability: value as typeof plan.availability,
                          }),
                        })
                      }
                      options={UNIT_AVAILABILITY.map((option) => ({
                        value: option.value,
                        label: option.label,
                      }))}
                      placeholder="Choose"
                      help="This unit's own. The property at the top of the page follows the best of them."
                    />

                    <NumberField
                      id={`kr-wiz-plan-${plan.id}-rent`}
                      label="Monthly price"
                      optional
                      value={plan.rentFrom ?? undefined}
                      min={1}
                      step={1}
                      prefix="$"
                      /* Empty is not zero. Null has meant "contact for
                         pricing" since MTC-KRP-024, and the page prints
                         exactly that rather than inventing a figure. */
                      onChange={(rentFrom) =>
                        onChange({
                          floorPlans: updateFloorPlan(plans, plan.id, {
                            rentFrom: rentFrom ?? null,
                          }),
                        })
                      }
                      help="Leave empty for Contact for pricing."
                    />
                  </div>

                  <div className="kr-wiz__plan-image">
                    {plan.image ? (
                      <>
                        <img src={plan.image.src} alt={plan.image.alt} loading="lazy" />
                        <div>
                          <p className="kr-wiz__plan-image-title">Drawing added</p>
                          <button
                            type="button"
                            className="kr-props__btn kr-props__btn--quiet"
                            onClick={() =>
                              onChange({
                                floorPlans: setFloorPlanImage(plans, plan.id, null),
                              })
                            }
                          >
                            <LuTrash2 size={13} aria-hidden="true" /> Remove drawing
                          </button>
                        </div>
                      </>
                    ) : (
                      <>
                        <span className="kr-wiz__plan-image-empty" aria-hidden="true">
                          <LuImage size={19} />
                        </span>
                        <div>
                          <p className="kr-wiz__plan-image-title">No drawing</p>
                          <p className="kr-wiz__help">
                            That is fine. The page shows this unit&rsquo;s name,
                            size, availability and price without one.
                          </p>
                          <button
                            type="button"
                            className="kr-props__btn"
                            onClick={() => setPicking({ forPlan: plan.id })}
                          >
                            <LuLibraryBig size={13} aria-hidden="true" /> Choose a
                            drawing
                          </button>
                        </div>
                      </>
                    )}
                  </div>
                </div>
              </li>
            ))}
          </ol>
        ) : null}

        <button
          type="button"
          className="kr-props__btn"
          onClick={() => onChange({ floorPlans: addFloorPlan(draft) })}
        >
          <LuPlus size={14} aria-hidden="true" />
          {plans.length === 0 ? "Add a floor plan" : "Add another floor plan"}
        </button>

        {plans.length === 0 ? (
          <p className="kr-wiz__help">
            The first one starts from the size and price you entered on step 1,
            so a single-layout property is two clicks.
          </p>
        ) : null}
      </fieldset>

      {picking ? (
        <ImageLibraryDialog
          images={library}
          loading={loading}
          error={loadError}
          usedSrc={picking.forPlan ? [] : images.map((image) => image.src)}
          single={Boolean(picking.forPlan)}
          title={picking.forPlan ? "Choose a floor-plan drawing" : "Choose existing photos"}
          onChoose={chooseFromLibrary}
          onClose={() => setPicking(null)}
          onRetry={() => void load()}
        />
      ) : null}
    </div>
  );
}
