import React, { useEffect, useRef } from "react";

export type ApplyDialogProps = {
  title: string;
  /** Explanatory line under the title. Nate asked for the reason, not a bare no. */
  text?: string;
  children?: React.ReactNode;
  /** Omit to render an acknowledge-only dialog. */
  onConfirm?: () => void;
  confirmLabel?: string;
  /** A quieter second line under the question, e.g. what can be undone. */
  note?: string;
  confirmDanger?: boolean;
  confirmDisabled?: boolean;
  cancelLabel?: string;
  onClose: () => void;
};

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

/**
 * The CMS's confirm/prompt dialog.
 *
 * Small on purpose — the plugin needs four of these (create, rename, delete,
 * and the you-need-at-least-one explanation) and none of them warrants a modal
 * framework. Focus is trapped while open and returned on close, and Escape
 * closes, because an overlay you cannot tab out of is a trap in the literal
 * sense.
 *
 * `onClose` is read through a ref rather than being an effect dependency:
 * callers pass an inline arrow, so depending on it re-runs the whole setup on
 * every render, which moves focus on each pass and — with anything listening
 * for blur — spins. That exact mistake froze the properties page earlier in
 * this project.
 */
export default function ApplyDialog({
  title,
  text,
  children,
  onConfirm,
  confirmLabel = "Confirm",
  note,
  confirmDanger = false,
  confirmDisabled = false,
  cancelLabel = "Cancel",
  onClose,
}: ApplyDialogProps) {
  const panelRef = useRef<HTMLDivElement | null>(null);
  const restoreTo = useRef<HTMLElement | null>(null);

  const onCloseRef = useRef(onClose);
  useEffect(() => {
    onCloseRef.current = onClose;
  });

  useEffect(() => {
    restoreTo.current = document.activeElement as HTMLElement | null;

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    const panel = panelRef.current;
    panel?.querySelector<HTMLElement>(FOCUSABLE)?.focus();

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onCloseRef.current();
        return;
      }
      if (event.key !== "Tab" || !panel) return;

      const focusable = Array.from(
        panel.querySelectorAll<HTMLElement>(FOCUSABLE)
      ).filter((element) => element.offsetParent !== null);
      if (!focusable.length) return;

      const first = focusable[0];
      const last = focusable[focusable.length - 1];

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.body.style.overflow = previousOverflow;
      restoreTo.current?.focus();
    };
  }, []);

  return (
    <div className="kr-apply-cms__veil" role="presentation" onClick={onClose}>
      <div
        className="kr-apply-cms__dialog"
        role="dialog"
        aria-modal="true"
        aria-label={title}
        ref={panelRef}
        data-tutorial="confirm-dialog"
        onClick={(event) => event.stopPropagation()}
      >
        <h2 className="kr-apply-cms__dialog-title">{title}</h2>
        {text ? <p className="kr-apply-cms__dialog-text">{text}</p> : null}
        {note ? <p className="kr-apply-cms__dialog-note">{note}</p> : null}

        {children}

        <div className="kr-apply-cms__dialog-actions">
          <button type="button" className="kr-apply-cms__btn" onClick={onClose}>
            {onConfirm ? cancelLabel : "Got it"}
          </button>

          {onConfirm ? (
            <button
              type="button"
              className={`kr-apply-cms__btn kr-apply-cms__btn--primary${
                confirmDanger ? " kr-apply-cms__btn--danger" : ""
              }`}
              data-tutorial="confirm-action"
              disabled={confirmDisabled}
              onClick={onConfirm}
            >
              {confirmLabel}
            </button>
          ) : null}
        </div>
      </div>
    </div>
  );
}
