// @ppm--version--1.0
// @ppm--dependency--config.template--leads
//
// Detail panel for a single lead (MTC-CX2-006).
//
// Follows the CMS's existing overlay convention (SeoModal in the gh-image
// plugin): overlay click closes, clicks inside the panel do not, Escape
// closes, body scroll is locked while open, and the panel carries
// role="dialog" aria-modal="true".
//
// Renders ONLY fields the normalized Lead actually carries. No scores, no
// enrichment, no invented CRM fields.

import React, { useEffect } from "react";
import { FaTimes } from "react-icons/fa";
import template from "../../templates/gh-leads/default-template";
import LeadQuickActions from "./LeadQuickActions";
import { formatAbsolute } from "./format";
import type { Lead } from "./types";
import { LeadPopoutToggles } from "../../config/gh-leads--ui-table-settings";


const labels = template.labels;
const fields = labels.popoutFields;

type Props = {
  lead: Lead;
  onClose: () => void;
};

/** One label/value row. Renders nothing when the value is absent. */
function Field({
  toggle, 
  label,
  value,
  href,
  className,
}: {
  toggle ?: boolean, 
  label: string;
  value?: string;
  href?: string;
  className?: string;
}) {
  if (!value) return null;
  if (toggle===false) return null;
  return (
    <div className="leads-field">
      <span className="leads-field__label">{label}</span>
      <span className={className ? `leads-field__value ${className}` : "leads-field__value"}>
        {href ? <a href={href}>{value}</a> : value}
      </span>
    </div>
  );
}

export default function LeadPopout({ lead, onClose }: Props) {
  useEffect(() => {
    const previous = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };

    window.addEventListener("keydown", onKey);

    return () => {
      document.body.style.overflow = previous;
      window.removeEventListener("keydown", onKey);
    };
  }, [onClose]);

  const received = lead.receivedAt ? formatAbsolute(lead.receivedAt) : "";

  return (
    <div className="leads-popout-overlay" onClick={onClose}>
      <div
        className="leads-popout"
        onClick={(event) => event.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-label={lead.name || "Lead details"}
      >
        <div className="leads-popout__header">
          <button
            type="button"
            className="leads-popout__close"
            onClick={onClose}
            title={labels.popoutClose}
            aria-label={labels.popoutClose}
          >
            <FaTimes size={13} />
          </button>

          <div className="leads-popout__heading">
            <h2 className="leads-popout__title">{lead.name || "Lead"}</h2>
            {received && <p className="leads-popout__sub">{received}</p>}
          </div>

          {/* Same component the table rows use — one implementation. */}
          <LeadQuickActions lead={lead} toggle={{ phone : false, submenu : false, email : false }}/>
        </div>

        <div className="leads-popout__body">
          <div className="leads-popout__pane">
            <p className="leads-popout__section">{labels.popoutMessage}</p>

            {lead.message ? (
              <p className="leads-popout__message">{lead.message}</p>
            ) : (
              <p className="leads-popout__message leads-popout__message--empty">
                {labels.popoutNoMessage}
              </p>
            )}
          </div>

          <div className="leads-popout__pane leads-popout__pane--details">
            <p className="leads-popout__section">{labels.popoutDetails}</p>

            <Field label={fields.name} value={lead.name} />
            <Field
              label={fields.email}
              value={lead.email}
              href={lead.email ? `mailto:${lead.email}` : undefined}
            />
            <Field
              label={fields.phone}
              value={lead.phone}
              href={lead.phone ? `tel:${lead.phone.replace(/[^\d+]/g, "")}` : undefined}
            />
            <Field label={fields.form} value={lead.form}  toggle={LeadPopoutToggles.FORM_ID} />
            <Field label={fields.site} value={lead.siteId} toggle={LeadPopoutToggles.SITE_ID} />
            <Field label={fields.tag} value={lead.tag}  toggle={LeadPopoutToggles.SITE_TAG} />
            <Field label={fields.received} value={received} />
            <Field
              label={fields.submissionId}
              value={lead.id}
              className="leads-field__value--id leads-field__value--muted"
              toggle={LeadPopoutToggles.SUBMISSION_ID}
            />
          
          </div>
        </div>
      </div>
    </div>
  );
}
