import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { navigate } from "gatsby";
import { LuInfo } from "react-icons/lu";

import ApplyTabs from "./ApplyTabs";
import BuilderTab from "./BuilderTab";
import HelpTab from "./HelpTab";
import TrashTab from "./TrashTab";
import { liveApplications, trashedApplications } from "./applicationRules";
import TutorialOverlay from "./tutorial/TutorialOverlay";
import { canRun, start } from "./tutorial/tutorialMachine";
import type { TutorialState } from "./tutorial/tutorialMachine";
import { findTutorial, tutorials } from "./tutorial/tutorials";
import { applicationsApi, isNotConnected } from "./applicationsApi";
import type { LoadSource } from "./applicationsApi";
import demoLocalStorage from "../../toggles/demo-local-storage";
import { usingSupabase } from "../supabase/enabled";
import { LEADS_ROUTE } from "../gh-leads/types";
import { APPLY_ROUTE } from "./types";
import type { ApplicationsDocument } from "./types";

/* Applicants left in MTC-KRP-030. It was a conceptual duplicate: a submission
   is a Lead, the Leads plugin already owns them, and this tab's data source was
   never provisioned — it rendered an empty state and nothing else. Builder,
   Trash and Help are all about the FORM, which is what this view is for. */
const TAB_KEYS = ["builder", "trash", "help"] as const;
type TabKey = (typeof TAB_KEYS)[number];

const isTabKey = (value: string): value is TabKey =>
  (TAB_KEYS as readonly string[]).includes(value);

export type ApplyViewProps = {
  /** The full browser pathname; the view resolves its own tail. */
  pathname: string;
};

/**
 * The Application Builder view.
 *
 * Owns the document and every write to it. The tabs are presentation and take
 * a document plus an onChange; nothing below this component talks to the
 * network, which is what keeps the save-then-commit rule in one place.
 *
 * The tab and any open applicant live in the URL — /dashboard/applications,
 * /dashboard/applications/builder, /dashboard/applications/a/<id> — which the
 * segment-aware router resolves to this view with the remainder intact.
 */
export default function ApplyView({ pathname }: ApplyViewProps) {
  const [doc, setDoc] = useState<ApplicationsDocument | null>(null);
  const [remote, setRemote] = useState(false);
  const [source, setSource] = useState<LoadSource>("seed");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [notice, setNotice] = useState<{
    tone: "ok" | "bad" | "note";
    text: string;
  } | null>(null);

  /* One clock for the whole view, so the trash list and its countdown cannot
     disagree mid-render. */
  const now = useMemo(() => Date.now(), [doc]);

  /* Walkthrough state is UI state and nothing else. It is never written to the
     applications document — a tutorial is something a person is doing now, not
     a property of the form they are editing. */
  const [tutorial, setTutorial] = useState<TutorialState | null>(null);

  /* The document as it was before a walkthrough began.
     Practice changes are put back when the walkthrough ends, so running Create
     an Application three times does not leave three phantom applications that
     were never saved and vanish on the next reload. */
  const beforeTutorial = useRef<ApplicationsDocument | null>(null);
  /* Read inside `change`, which is memoised and must not be rebuilt per step. */
  const inTutorial = useRef(false);
  inTutorial.current = tutorial !== null;

  useEffect(() => {
    let cancelled = false;

    applicationsApi
      .load()
      .then((result) => {
        if (cancelled) return;
        setDoc(result.doc);
        setRemote(result.remote);
        setSource(result.source);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, []);

  /* Resolve the tail this view was handed. */
  const tail = pathname
    .replace(/[?#].*$/, "")
    .replace(/^\/+|\/+$/g, "")
    .replace(/^dashboard\/applications\/?/, "");

  const segments = tail ? tail.split("/") : [];

  /* Builder is where this view opens now. It is what the whole destination is
     for: the form and its questions. */
  const tab: TabKey = segments[0] && isTabKey(segments[0]) ? segments[0] : "builder";

  /* An address from before the split — /dashboard/applications/applicants, or
     a link to one submission at /dashboard/applications/a/<id>. Submissions
     live in Leads now, so the link is honoured by sending the person there
     rather than showing them a CMS screen that no longer exists. */
  const movedToLeads =
    segments[0] === "applicants" || (segments[0] === "a" && Boolean(segments[1]));

  useEffect(() => {
    if (!movedToLeads) return;
    const id = segments[0] === "a" ? segments[1] : "";
    navigate(id ? `${LEADS_ROUTE}/${encodeURIComponent(id)}` : LEADS_ROUTE, {
      replace: true,
    });
  }, [movedToLeads, segments]);

  const goTo = useCallback((key: TabKey) => {
    navigate(`${APPLY_ROUTE}/${key}`);
  }, []);

  /**
   * Persist first, then commit.
   *
   * The interface must not show a change that did not survive — the site's
   * storage is not provisioned yet, so a failed save is the likely case, not
   * the rare one. Nothing is applied to state until the write returns.
   */
  const change = useCallback(
    async (next: ApplicationsDocument, description: string) => {
      setSaving(true);
      setNotice(null);

      try {
        await applicationsApi.save(next);
        setDoc(next);
        setRemote(true);
        /* A demo save is a real save to this browser; calling it "remote"
           would be the lie the old banner told in reverse. */
        setSource(usingSupabase() || !demoLocalStorage ? "remote" : "local");
        setNotice({ tone: "ok", text: description });
      } catch (error) {
        /* Practice mode.
           A walkthrough teaches by having the reader use the real controls, so
           the screen has to respond — Create an Application cannot reach its
           last step if pressing Create leaves nothing to open. While a
           walkthrough is running and the only thing wrong is that this site has
           no storage yet, the change is applied on screen so the lesson works.

           It is not dressed up as a save. `remote` stays false, the notice says
           plainly that nothing was stored, and the document is put back when the
           walkthrough ends. Any other failure still just fails. */
        if (inTutorial.current && isNotConnected(error)) {
          setDoc(next);
          setNotice({
            tone: "note",
            text: `${description} — practice only, nothing was saved.`,
          });
        } else {
          setNotice({
            tone: "bad",
            text:
              error instanceof Error
                ? error.message
                : "Changes couldn't be saved. Nothing was saved.",
          });
        }
      } finally {
        setSaving(false);
      }
    },
    []
  );

  /**
   * The single storage line.
   *
   * Null when the real backend is answering, because then there is nothing
   * unusual to report and a permanent banner is just furniture.
   */
  const storageNote = usingSupabase()
    ? null
    : demoLocalStorage
      ? "Demo mode · Changes are saved on this device until permanent storage is connected."
      : source === "remote"
        ? null
        : "Application storage isn't connected yet, so changes cannot be saved. You are looking at the starting application.";

  if (loading || !doc) {
    return (
      <div className="kr-apply-cms">
        <p className="kr-apply-cms__hint">Loading applications…</p>
      </div>
    );
  }

  /* Which walkthroughs have something to point at, given what exists. Checked
     before starting rather than discovered three steps in. */
  const context = {
    trashCount: trashedApplications(doc, now).length,
    applicationCount: liveApplications(doc).length,
  };

  const unavailable = Object.fromEntries(
    tutorials.map((entry) => [
      entry.id,
      canRun(entry, context) ? null : entry.unavailable ?? null,
    ])
  );

  const activeTutorial = tutorial ? findTutorial(tutorial.tutorialId) : null;

  const tabs = [
    { key: "builder" as const, label: "Builder" },
    {
      key: "trash" as const,
      label: "Trash",
      count: trashedApplications(doc, now).length,
    },
    { key: "help" as const, label: "Help" },
  ];

  return (
    <div className="kr-apply-cms">
      <ApplyTabs
        tabs={tabs}
        active={tab}
        onChange={goTo}
        idPrefix="kr-apply"
        label="Application Builder sections"
      />

      {notice ? (
        <div
          className={`kr-apply-cms__banner kr-apply-cms__banner--${notice.tone}`}
          role="status"
        >
          {notice.text}
        </div>
      ) : null}

      {/* ONE line, and only when there is something true to say.
          This used to be two: a red "could not reach the save service" from a
          failed write, sitting above a grey "changes cannot be saved" — while
          the change the editor had just made was still on screen in front of
          them. Three statements, no two of which agreed. Now saving either
          works, and this says where it went, or it fails and the notice above
          reports that one failure. */}
      {storageNote ? (
        <p className="kr-apply-cms__note">
          <LuInfo size={15} className="kr-apply-cms__note-icon" aria-hidden="true" />
          <span>{storageNote}</span>
        </p>
      ) : null}

      <div
        role="tabpanel"
        id={`kr-apply-panel-${tab}`}
        aria-labelledby={`kr-apply-tab-${tab}`}
      >
        {tab === "builder" ? (
          <BuilderTab doc={doc} onChange={change} saving={saving} />
        ) : null}

        {tab === "trash" ? (
          <TrashTab doc={doc} onChange={change} saving={saving} now={now} />
        ) : null}

        {tab === "help" ? (
          <HelpTab
            unavailable={unavailable}
            onStartTutorial={(id) => {
              const chosen = findTutorial(id);
              if (chosen) setTutorial(start(chosen));
            }}
          />
        ) : null}
      </div>

      {/* Rendered last so it sits above the CMS, and only while running. */}
      {activeTutorial && tutorial ? (
        <TutorialOverlay
          tutorial={activeTutorial}
          state={tutorial}
          practice={!remote}
          onState={setTutorial}
          onExit={() => {
            /* Put the document back. Anything done during a walkthrough was
               practice, and leaving it on screen would look saved. */
            const restored = beforeTutorial.current;
            beforeTutorial.current = null;
            setTutorial(null);

            if (restored && restored !== doc) {
              setDoc(restored);
              setNotice({
                tone: "note",
                text: "Walkthrough finished. Your practice changes were not saved.",
              });
            } else {
              setNotice(null);
            }
          }}
          onNeedTab={(wanted) => {
            if (wanted !== tab) goTo(wanted as TabKey);
          }}
        />
      ) : null}
    </div>
  );
}
