// @ppm--version--1.0
// @ppm--dependency--config.profile--site-id
// @ppm--dependency--config.leads-repo
//
// The ONLY module that knows where lead submissions come from.
//
// Retrieval mirrors the working reader in src/ppm/plugins/GetTest.tsx:
//   1. GET <base>/batches/leads.json  -> string[] of "<epochMillis>.json"
//   2. GET <base>/gh-leads/<filename>    -> one encrypted submission each
// The repository name is the SHA-256 of the site slug, and the fetches are
// unauthenticated because the repo is public.
//
// TEMPORARY (MTC-CX2-003): this transport is expected to be swapped for the
// final mechanism later. Everything above it — leadsApi, LeadsView,
// LeadsPreview — consumes EncryptedSubmission[] and is unaffected by that
// change, so replacing this file's body is the whole migration.
//
// Decryption deliberately does NOT happen here; leadsApi applies it.


import { SITE_ID } from "../../config/profile--site-id";
import {
  LEADS_INDEX_PATH,
  LEADS_RECORD_DIR,
  LEADS_REPO_BRANCH,
  LEADS_REPO_HOST,
  LEADS_REPO_OWNER,
} from "../../config/gh-leads--repo";
import { hashFileName } from "../../utilities/crypto/gethash";


/**
 * One submission exactly as the repository stores it: a filename of
 * `<epochMillis>.json` and an object whose keys are plaintext and whose string
 * values are each a single base64 RSA-OAEP block.
 */
export type EncryptedSubmission = {
  filename: string;
  data: Record<string, unknown>;
};

const repoHash = hashFileName(SITE_ID);

export const LEADS_BASE_URL = `${LEADS_REPO_HOST}/${LEADS_REPO_OWNER}/${repoHash}/${LEADS_REPO_BRANCH}`;

export const LEADS_INDEX_URL = `${LEADS_BASE_URL}/${LEADS_INDEX_PATH}`;

/** raw.githubusercontent caches aggressively; new leads must not be masked. */
const bust = (url: string) => `${url}?v=${Date.now()}`;

async function getJson(url: string): Promise<unknown> {
  const response = await fetch(bust(url), {
    headers: { Accept: "application/json" },
  });

  if (!response.ok) {
    throw new Error(`${response.status} ${response.statusText}`);
  }

  return response.json();
}

/**
 * Returns every stored submission, still encrypted.
 *
 * A submission that individually fails to load is dropped rather than failing
 * the batch, so one bad file cannot empty the table. A failure to load the
 * index itself does throw — that means nothing can be shown.
 */
export async function pullLeadsFromGitHub(): Promise<EncryptedSubmission[]> {
  const index = await getJson(LEADS_INDEX_URL);

  if (!Array.isArray(index)) {
    throw new Error("Lead index is not an array");
  }

  const filenames = index.filter(
    (entry): entry is string => typeof entry === "string"
  );

  const submissions = await Promise.all(
    filenames.map(async (filename) => {
      try {
        const data = await getJson(`${LEADS_BASE_URL}/${LEADS_RECORD_DIR}/${filename}`);

        if (!data || typeof data !== "object" || Array.isArray(data)) {
          throw new Error("Submission is not an object");
        }

        return { filename, data: data as Record<string, unknown> };
      } catch (error) {
        // Filename only — never the ciphertext or the payload.
        console.error(`[leads] Could not load submission ${filename}`, error);

        return null;
      }
    })
  );

  return submissions.filter(
    (entry): entry is EncryptedSubmission => entry !== null
  );
}
