// @ppm--version--1.0

// Perception-engineered upload progress toasts.
//
// Data model
// ──────────
// Each in-flight upload lives in localStorage (via useImageSyncQueue). That
// means notifications survive a page reload — this component picks back up
// wherever the user left off.
//
// Step derivation
// ──────────────
// The displayed step is always derived from elapsed time since the upload
// started, so the progress bar can't go "backwards" after a reload. Each poll
// tick also writes the current step back to localStorage so Nate/the user can
// inspect it in DevTools (or debug a stuck upload).
//
// Truth of success
// ────────────────
// We never trust an elapsed-time timer to claim success. We HEAD the webpUrl
// every few seconds, and only call markSuccess() (removing the entry from
// localStorage) when that HEAD returns 200.

import React, { useEffect, useRef, useState } from "react";

import {
  runThreeStageImageFlow,
  checkImageUrl,
} from "./three-stage";

import {
  FaCheckCircle,
  FaCloudUploadAlt,
  FaExclamationTriangle,
} from "react-icons/fa";
import {
  useImageSyncQueue,
  type UploadEntry,
} from "./useImageSyncQueue";

// Progress now reflects real upload state instead of pretending elapsed time
// maps to backend work. The queue keeps the thumbnail while neither remote
// image is available; clearThumb() removes it when raw GitHub becomes live.
const POLL_INTERVAL_MS = 3000;
const SUCCESS_DISPLAY_MS = 2500;
const MAX_AGE_MS = 5 * 60 * 1000;

const progressFor = (entry: UploadEntry): number =>
  entry.stage === "thumbnail" ? 35 : 75;

const labelFor = (entry: UploadEntry): string =>
  entry.stage === "thumbnail"
    ? "Processing image…"
    : "Processed — publishing final image…";

type Toast = UploadEntry & {
  status: "working" | "done" | "timeout";
};

export const UploadNotifications: React.FC = () => {
const {
  getUploads,
  setUploadStage,
  markSuccess,
  clearEntry,
} = useImageSyncQueue();

  const [toasts, setToasts] = useState<Toast[]>([]);

  // Track which ids are in their brief "done"/"timeout" display window so we
  // don't re-mark-success / re-trigger / re-show them during that window.
  const completingRef = useRef<Set<string>>(
    new Set()
  );

  // Mirror of `toasts` so the polling interval (which closes over initial state
  // due to the empty-deps useEffect) can always see the latest toast list
  // for its age/timeout detection pass.
  const toastsRef = useRef<Toast[]>([]);

  useEffect(() => {
    toastsRef.current = toasts;
  }, [toasts]);

  // Snapshot localStorage → state (used to hydrate on mount + after changes).
  const refresh = () => {
    const entries = getUploads();

    setToasts((prev) => {
      const completing =
        completingRef.current;

      // Keep any toast currently in its "done" window, even if the entry
      // was already deleted from localStorage.
      const kept = prev.filter((t) =>
        completing.has(t.id)
      );

      const next: Toast[] = entries
        .filter(
          (e) => !completing.has(e.id)
        )
        .map((e) => ({
          ...e,
          status: "working" as const,
        }));

      return [...kept, ...next];
    });
  };

  useEffect(() => {
    refresh();

    const interval = setInterval(
      async () => {
        // ── Timeout sweep ───────────────────────────────────────────────────
        // Any still-"working" toast older than MAX_AGE_MS transitions to the
        // red "timed out" state for SUCCESS_DISPLAY_MS, then auto-removes.
        // Also clears the queue entry so a reload can't resurrect it.
        const now = Date.now();

        for (const t of toastsRef.current) {
          if (t.status !== "working") {
            continue;
          }

          if (
            completingRef.current.has(t.id)
          ) {
            continue;
          }

          if (
            now - t.time <= MAX_AGE_MS
          ) {
            continue;
          }

          completingRef.current.add(t.id);

          clearEntry(t.id);

          setToasts((prev) =>
            prev.map((x) =>
              x.id === t.id
                ? {
                    ...x,
                    status:
                      "timeout" as const,
                  }
                : x
            )
          );

          setTimeout(() => {
            completingRef.current.delete(
              t.id
            );

            setToasts((prev) =>
              prev.filter(
                (x) => x.id !== t.id
              )
            );
          }, SUCCESS_DISPLAY_MS);
        }

        const entries = getUploads();

        if (entries.length === 0) {
          refresh();
          return;
        }

        // For each pending upload: compute the current step, persist it,
        // then check raw GitHub for the temporary processed image and
        // GitHub Pages for permanent completion.
        await Promise.all(
          entries.map(async (e) => {
            if (
              completingRef.current.has(
                e.id
              )
            ) {
              return;
            }
await runThreeStageImageFlow({
  id: e.id,
  finalUrl: e.webpUrl,
  originalFileName: e.originalFileName,

  checkUrl: checkImageUrl,

  setStage: (id, stage, url) => {
    setUploadStage(id, stage, url);
  },

  complete: id => {
    completingRef.current.add(id);

    markSuccess(id);

    setToasts(prev =>
      prev.map(t =>
        t.id === id
          ? {
              ...t,
              status: "done",
            }
          : t
      )
    );

    setTimeout(() => {
      completingRef.current.delete(id);

      setToasts(prev =>
        prev.filter(t => t.id !== id)
      );
    }, SUCCESS_DISPLAY_MS);
  },
});

          })
        );

        refresh();
      },
      POLL_INTERVAL_MS
    );

    // Keep in sync if another tab writes to localStorage.
    const onStorage = () => refresh();

    window.addEventListener(
      "storage",
      onStorage
    );

    return () => {
      clearInterval(interval);

      window.removeEventListener(
        "storage",
        onStorage
      );
    };

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Belt-and-suspenders: also hide any stuck "working" toast that the interval
  // hasn't yet caught (e.g. between ticks, or if the tab was throttled). The
  // interval will catch up on the next fire and officially mark it "timeout".
  const visibleToasts = toasts.filter(
    (t) => {
      if (t.status !== "working") {
        return true;
      }

      return (
        Date.now() - t.time <=
        MAX_AGE_MS
      );
    }
  );

  if (visibleToasts.length === 0) {
    return null;
  }

  return (
    <>
      <style>{styles}</style>

      <div className="upload-toasts">
        {visibleToasts.map((t) => {
          const isDone =
            t.status === "done";

          const isTimeout =
            t.status === "timeout";

          const pct = isDone || isTimeout
            ? 100
            : progressFor(t);

          const label = isDone
            ? "Upload complete"
            : isTimeout
              ? "Upload timed out — please try again"
              : labelFor(t);

          const cls = isDone
            ? "upload-toast upload-toast--done"
            : isTimeout
              ? "upload-toast upload-toast--timeout"
              : "upload-toast";

          const fallbackIcon = isDone ? (
            <FaCheckCircle size={18} />
          ) : isTimeout ? (
            <FaExclamationTriangle
              size={18}
            />
          ) : (
            <FaCloudUploadAlt size={18} />
          );

          return (
            <div
              key={t.id}
              className={cls}
            >
              <div className="upload-toast__thumb">
                {t.thumb ? (
                  <img
                    src={t.thumb}
                    alt=""
                  />
                ) : (
                  <div className="upload-toast__thumb-fallback">
                    {fallbackIcon}
                  </div>
                )}

                {isDone && t.thumb && (
                  <div className="upload-toast__thumb-check">
                    <FaCheckCircle
                      size={20}
                    />
                  </div>
                )}

                {isTimeout &&
                  t.thumb && (
                    <div className="upload-toast__thumb-check upload-toast__thumb-check--error">
                      <FaExclamationTriangle
                        size={20}
                      />
                    </div>
                  )}
              </div>

              <div className="upload-toast__body">
                <div
                  className="upload-toast__name"
                  title={t.fileName}
                >
                  {t.fileName}
                </div>

                <div className="upload-toast__step">
                  {label}
                </div>

                <div className="upload-toast__bar">
                  <div
                    className="upload-toast__bar-fill"
                    style={{
                      width: `${pct}%`,
                    }}
                  />
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </>
  );
};

const styles = `
.upload-toasts {
  position: fixed;
  right: 20px;
  top: 20px;
  z-index: 9998;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: calc(100vw - 40px);
}

.upload-toast {
  display: flex;
  gap: 12px;
  align-items: center;
  width: 360px;
  max-width: 100%;
  padding: 12px 14px;
  background: #fff;
  border: 1px solid #e5e5e5;
  border-radius: 12px;
  box-shadow: 0 10px 32px rgba(0,0,0,0.14);
  animation: upload-toast-in 0.25s ease-out;
}

.upload-toast--done {
  border-color: rgba(34,197,94,0.45);
  background: rgba(34,197,94,0.04);
}

.upload-toast--timeout {
  border-color: rgba(239,68,68,0.45);
  background: rgba(239,68,68,0.04);
}

.upload-toast--timeout .upload-toast__thumb-fallback {
  background: rgba(239,68,68,0.14);
  color: #dc2626;
}

.upload-toast--timeout .upload-toast__bar-fill {
  background: #dc2626;
}

.upload-toast--timeout .upload-toast__step {
  color: #dc2626;
}

.upload-toast__thumb-check--error {
  background: rgba(220,38,38,0.55);
  color: #fff;
}

.upload-toast__thumb {
  flex-shrink: 0;
  position: relative;
  width: 52px;
  height: 52px;
  border-radius: 8px;
  overflow: hidden;
  background: #f1f1f1;
}

.upload-toast__thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.upload-toast__thumb-fallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(245,193,0,0.12);
  color: #F5C100;
}

.upload-toast--done .upload-toast__thumb-fallback {
  background: rgba(34,197,94,0.12);
  color: #16a34a;
}

.upload-toast__thumb-check {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(22,163,74,0.55);
  color: #fff;
  animation: upload-check-in 0.3s ease-out;
}

.upload-toast__body {
  flex: 1;
  min-width: 0;
}

.upload-toast__name {
  font-size: 13px;
  font-weight: 700;
  color: #1a1a1a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.upload-toast__step {
  font-size: 12px;
  color: #777;
  margin-top: 2px;
}

.upload-toast__bar {
  margin-top: 10px;
  height: 4px;
  background: #f0f0f0;
  border-radius: 2px;
  overflow: hidden;
}

.upload-toast__bar-fill {
  height: 100%;
  background: #F5C100;
  transition: width 0.4s ease;
}

.upload-toast--done .upload-toast__bar-fill {
  background: #16a34a;
}

@keyframes upload-toast-in {
  from {
    opacity: 0;
    transform: translateY(-8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes upload-check-in {
  from {
    opacity: 0;
    transform: scale(0.6);
  }

  to {
    opacity: 1;
    transform: scale(1);
  }
}

@media (max-width: 480px) {
  .upload-toasts {
    right: 10px;
    top: 10px;
    left: 10px;
  }

  .upload-toast {
    width: 100%;
  }
}
`;