import React, { useRef } from "react";

export type TabDefinition<K extends string> = {
  key: K;
  label: string;
  /** Shown as a small pill beside the label. Omit when there is nothing to count. */
  count?: number;
};

export type CmsTabsProps<K extends string> = {
  tabs: TabDefinition<K>[];
  active: K;
  onChange: (key: K) => void;
  /** Prefix for the generated tab and panel ids. */
  idPrefix: string;
  label: string;
  /**
   * BEM prefix for the strip's own classes, e.g. "kr-apply-cms" gives
   * `kr-apply-cms__tabs` and `kr-apply-cms__tab`.
   *
   * Parameterised rather than hard-coded because two CMS modules now use this
   * strip and each styles it from its own plugin stylesheet. The behaviour —
   * roving tabindex, arrow keys, Home/End, panel association — is the part
   * worth sharing; the paint is not.
   */
  classPrefix?: string;
};

/**
 * The CMS tab strip.
 *
 * Lifted out of gh-apply for MTC-KRP-036, which asked the Properties CMS to
 * carry the same Properties / Trash / Help navigation. Copying it would have
 * meant two copies of the keyboard handling, and the keyboard handling is the
 * only difficult part.
 *
 * One config array drives both the buttons and, at the call site, the panel
 * switch — the structural idea from the dialer's settings pages, which is the
 * pattern Nate pointed at. The dialer itself has no reusable component: the
 * same strip is hand-copied across four of its pages in three different styling
 * mechanisms, which is the outcome this avoids.
 *
 * The accessibility is not the dialer's, though. Its tabs stop at
 * `aria-selected` — no tabpanel association, no roving tabindex, no keyboard.
 * This follows the pattern already in Kelley Road's own floor-plan tabs, which
 * does all three, so the CMS does not ship something weaker than the public
 * site: arrow keys move, Home and End jump, and only the selected tab is in the
 * tab order so Tab moves out of the strip and into the panel.
 */
export default function CmsTabs<K extends string>({
  tabs,
  active,
  onChange,
  idPrefix,
  label,
  classPrefix = "kr-apply-cms",
}: CmsTabsProps<K>) {
  const refs = useRef<Record<string, HTMLButtonElement | null>>({});

  const focusTab = (key: K) => {
    onChange(key);
    // The newly selected tab takes the tab order with it, so move focus too.
    window.requestAnimationFrame(() => refs.current[key]?.focus());
  };

  const onKeyDown = (event: React.KeyboardEvent, index: number) => {
    const last = tabs.length - 1;
    let next: number | null = null;

    if (event.key === "ArrowRight") next = index === last ? 0 : index + 1;
    else if (event.key === "ArrowLeft") next = index === 0 ? last : index - 1;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = last;

    if (next === null) return;

    event.preventDefault();
    focusTab(tabs[next].key);
  };

  return (
    <div className={`${classPrefix}__tabs`} role="tablist" aria-label={label}>
      {tabs.map((tab, index) => {
        const selected = tab.key === active;

        return (
          <button
            key={tab.key}
            type="button"
            role="tab"
            id={`${idPrefix}-tab-${tab.key}`}
            aria-controls={`${idPrefix}-panel-${tab.key}`}
            aria-selected={selected}
            tabIndex={selected ? 0 : -1}
            className={`${classPrefix}__tab`}
            data-tutorial={`tab-${tab.key}`}
            ref={(node) => {
              refs.current[tab.key] = node;
            }}
            onClick={() => onChange(tab.key)}
            onKeyDown={(event) => onKeyDown(event, index)}
          >
            {tab.label}
            {typeof tab.count === "number" ? (
              <span className={`${classPrefix}__tab-count`}>{tab.count}</span>
            ) : null}
          </button>
        );
      })}
    </div>
  );
}
