import React, { useState } from "react";
import { LuInfo, LuPlus, LuX } from "react-icons/lu";

import {
  availabilityOf,
  bedroomSummary,
  startingPrice,
} from "../../../property/derive";
import { TextArea, TextField, errorFor } from "../Field";
import { paragraphsToText, textToParagraphs, toRecord } from "../draft";
import type { StepProps } from "./types";
import {
  PREDEFINED_AMENITIES,
  addAmenity,
  amenityKey,
  customAmenities,
  hasAmenity,
  removeAmenity,
} from "../vocabulary";

/**
 * Page 2 — the words.
 *
 * The one rule this page exists to demonstrate: the Property Details block on
 * the public overview has no inputs here. Every line of it — type, location,
 * bedrooms, size, availability, price — is already known from page 1, and the
 * page derives it. Reproducing those controls to mirror the public layout
 * would create a second copy of six facts and guarantee that one day the
 * overview and the hero disagree about the same building.
 */
export default function ContentStep({ draft, onChange, issues }: StepProps) {
  const amenities = draft.amenities ?? [];
  const [custom, setCustom] = useState("");
  const [duplicate, setDuplicate] = useState<string | null>(null);

  const setContent = (patch: Partial<NonNullable<typeof draft.content>>) =>
    onChange({ content: { ...(draft.content ?? {}), ...patch } });

  const toggle = (amenity: string) =>
    onChange({
      amenities: hasAmenity(amenities, amenity)
        ? removeAmenity(amenities, amenity)
        : addAmenity(amenities, amenity),
    });

  const addCustom = () => {
    const value = custom.trim();
    if (!value) return;

    const next = addAmenity(amenities, value);

    /* Unchanged means it was already there under some other casing. Said out
       loud rather than silently ignored — a control that appears to do nothing
       gets pressed again. */
    if (next === amenities) {
      setDuplicate(
        amenities.find((item) => amenityKey(item) === amenityKey(value)) ?? value
      );
      return;
    }

    onChange({ amenities: next });
    setCustom("");
    setDuplicate(null);
  };

  const mine = customAmenities(amenities);

  return (
    <div className="kr-wiz__fields">
      <TextField
        id="kr-wiz-content-title"
        label="Section title"
        optional
        value={draft.content?.title ?? ""}
        /* Proposed as a placeholder rather than written into the record. That
           is what makes "do not keep overwriting their text when the property
           name changes" true by construction: until somebody types something,
           there is nothing stored to overwrite, and the page uses this exact
           wording anyway. */
        placeholder={
          draft.title?.trim() ? `Welcome to ${draft.title.trim()}` : "Welcome to…"
        }
        onChange={(title) => setContent({ title })}
        help="The heading above the description on the property page. Leave it blank to use the suggestion."
      />

      <TextArea
        id="kr-wiz-summary"
        label="Short description"
        rows={3}
        value={draft.summary ?? ""}
        placeholder="A one-bedroom apartment on a quiet street, within easy reach of the shops."
        onChange={(summary) => onChange({ summary })}
        error={errorFor(issues, "kr-wiz-summary")}
        help="One or two sentences. This appears near the top of the property page, in search results and in the page's Google listing."
      />

      <TextArea
        id="kr-wiz-description"
        label="Description"
        optional
        rows={9}
        value={paragraphsToText(draft.content?.paragraphs)}
        placeholder={
          "Write as much as you like about the property.\n\nLeave a blank line between paragraphs — that is how the page knows where to break them. The first two are shown, and the rest sit behind Read More."
        }
        onChange={(text) => setContent({ paragraphs: textToParagraphs(text) })}
        help="Plain writing. Leave a blank line between paragraphs; no formatting codes needed."
      />

      <DerivedDetails draft={draft} />

      {/* ── amenities ───────────────────────────────────── */}
      <fieldset className="kr-wiz__group">
        <legend className="kr-props__label">Amenities</legend>
        <p className="kr-wiz__help kr-wiz__help--above">
          Tick everything this property has. These show on the property page and
          are what people filter by when searching.
        </p>

        <div className="kr-wiz__checks">
          {PREDEFINED_AMENITIES.map((amenity) => (
            <label key={amenity} className="kr-wiz__check">
              <input
                type="checkbox"
                checked={hasAmenity(amenities, amenity)}
                onChange={() => toggle(amenity)}
              />
              <span>{amenity}</span>
            </label>
          ))}
        </div>

        {mine.length > 0 ? (
          <ul className="kr-wiz__tags">
            {mine.map((amenity) => (
              <li key={amenity} className="kr-wiz__tag">
                <span>{amenity}</span>
                <button
                  type="button"
                  className="kr-wiz__tag-remove"
                  onClick={() => onChange({ amenities: removeAmenity(amenities, amenity) })}
                >
                  <LuX size={13} aria-hidden="true" />
                  <span className="kr-sr-only">Remove {amenity}</span>
                </button>
              </li>
            ))}
          </ul>
        ) : null}

        <div className="kr-wiz__inline">
          <label className="kr-sr-only" htmlFor="kr-wiz-custom-amenity">
            Add your own amenity
          </label>
          <input
            id="kr-wiz-custom-amenity"
            className="kr-props__input"
            value={custom}
            placeholder="Add your own — Rooftop Terrace"
            aria-describedby={duplicate ? "kr-wiz-custom-amenity-note" : undefined}
            onChange={(event) => {
              setCustom(event.target.value);
              setDuplicate(null);
            }}
            onKeyDown={(event) => {
              /* Enter adds the amenity rather than submitting anything, which
                 is what someone typing a list expects it to do. */
              if (event.key === "Enter") {
                event.preventDefault();
                addCustom();
              }
            }}
          />
          <button
            type="button"
            className="kr-props__btn"
            disabled={!custom.trim()}
            onClick={addCustom}
          >
            <LuPlus size={14} aria-hidden="true" /> Add
          </button>
        </div>

        {duplicate ? (
          <p className="kr-wiz__help" id="kr-wiz-custom-amenity-note" role="status">
            Already on the list as <strong>{duplicate}</strong>.
          </p>
        ) : null}
      </fieldset>
    </div>
  );
}

/**
 * The Property Details block, shown rather than asked for.
 *
 * Read-only on purpose, and visible on purpose: the manager should be able to
 * see what the public block will say without leaving the step, and should be
 * in no doubt about where it comes from.
 */
function DerivedDetails({ draft }: { draft: StepProps["draft"] }) {
  const record = toRecord(draft);
  const price = startingPrice(record);

  const availability = {
    available: "Available now",
    limited: "Available soon",
    contact: "Contact for availability",
    unavailable: "Not available",
  }[availabilityOf(record)];

  const rows: { label: string; value: string }[] = [
    { label: "Property type", value: record.type ?? "" },
    { label: "Location", value: record.location ?? "" },
    { label: "Size", value: bedroomSummary(record) },
    { label: "Availability", value: availability },
    {
      label: "Price",
      value:
        price.kind === "monthly"
          ? `$${price.amount.toLocaleString("en-US")} / month`
          : "Contact for pricing",
    },
  ].filter((row) => row.value);

  return (
    <div className="kr-wiz__derived">
      <p className="kr-wiz__derived-head">
        <LuInfo size={15} aria-hidden="true" />
        <span>
          <strong>Property Details</strong> — filled in from Property Basics.
          Nothing to type here; change it on step 1 and this follows.
        </span>
      </p>

      {rows.length > 0 ? (
        <dl className="kr-wiz__derived-list">
          {rows.map((row) => (
            <div key={row.label}>
              <dt>{row.label}</dt>
              <dd>{row.value}</dd>
            </div>
          ))}
        </dl>
      ) : (
        <p className="kr-wiz__help">Nothing yet — fill in Property Basics first.</p>
      )}
    </div>
  );
}
