import React, { useEffect, useRef, useState } from "react";

import TutorialArrow from "./TutorialArrow";
import { findTarget, useTargetRect, type Rect } from "./useTargetRect";
import {
  back,
  currentStep,
  isFirstStep,
  isLastStep,
  findResumeStep,
  next,
  stepLabel,
} from "./tutorialMachine";
import type { TutorialState } from "./tutorialMachine";
import type { Placement, Tutorial } from "./types";

export type TutorialOverlayProps = {
  tutorial: Tutorial;
  state: TutorialState;
  onState: (state: TutorialState) => void;
  onExit: () => void;
  /** Called when a step names a tab, so the view can navigate there. */
  onNeedTab: (tab: string) => void;
  /**
   * True when this site has no storage yet, so anything the reader does during
   * the walkthrough is applied on screen but not stored. Said in the callout
   * rather than left to a banner the overlay is covering.
   */
  practice?: boolean;
};

/** Breathing room around the spotlight, so the target is not touching the dark. */
const PAD = 8;
const CALLOUT_W = 320;
const CALLOUT_GAP = 18;
const ARROW = 76;

export default function TutorialOverlay({
  tutorial,
  state,
  onState,
  onExit,
  onNeedTab,
  practice = false,
}: TutorialOverlayProps) {
  const step = currentStep(tutorial, state);
  const [retry, setRetry] = useState(0);
  const panel = useRef<HTMLDivElement | null>(null);
  /* Its real size, so placement is not working from a hardcoded guess. */
  const [panelSize, setPanelSize] = useState({ width: 320, height: 200 });
  const restoreTo = useRef<HTMLElement | null>(null);

  const target = useTargetRect(step?.target ?? null, retry);

  /* Read through refs: the view passes inline arrows, so depending on them
     would tear this down and rebuild it on every render. */
  const onExitRef = useRef(onExit);
  const onStateRef = useRef(onState);
  const advanceRef = useRef<() => void>(() => undefined);

  const advance = () => {
    const moved = next(tutorial, state);
    if (moved) onState(moved);
    else onExit();
  };

  useEffect(() => {
    onExitRef.current = onExit;
    onStateRef.current = onState;
    advanceRef.current = advance;
  });

  /* A step may live on another tab. Ask for it before hunting for the target,
     or the search is guaranteed to time out. */
  useEffect(() => {
    if (step?.tab) onNeedTab(step.tab);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step?.id]);

  useEffect(() => {
    restoreTo.current = document.activeElement as HTMLElement | null;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onExitRef.current();
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      restoreTo.current?.focus();
    };
  }, []);

  /* Focus the callout as each step arrives, so a keyboard reader lands on the
     new instruction rather than staying wherever they were. */
  useEffect(() => {
    panel.current?.focus();
  }, [step?.id]);

  /* Remeasure whenever the content or the window changes: a longer body makes
     a taller panel, and a panel placed from a stale height lands on the target. */
  useEffect(() => {
    const element = panel.current;
    if (!element) return;

    const measure = () => {
      const box = element.getBoundingClientRect();
      setPanelSize((current) =>
        Math.abs(current.height - box.height) < 2 &&
        Math.abs(current.width - box.width) < 2
          ? current
          : { width: box.width, height: box.height }
      );
    };

    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    window.addEventListener("resize", measure);

    return () => {
      observer.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, [step?.id, target.status]);

  /* The reader has gone further than this step expects — catch up to them
     rather than telling them the screen moved on. See findResumeStep. */
  useEffect(() => {
    if (target.status !== "missing") return;

    const resume = findResumeStep(tutorial, state, (name) =>
      Boolean(findTarget(name))
    );
    if (resume !== null) {
      onState({ ...state, stepIndex: resume, missingTarget: false });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target.status, state.stepIndex]);

  /* Doing the thing is what moves the walkthrough on.
     
     Listeners go on the current step's control AND on every later step's
     control that happens to be on screen. That second part is the difference
     between a walkthrough and a slideshow: on the naming step the Create button
     is right there, and pressing it is the obvious next move, so pressing it
     should carry the reader forward rather than leaving them to press Next as
     well and then discover the dialog they were being shown has closed.
     
     Clicking a later control resumes just after it, because that action has
     already been performed. */
  useEffect(() => {
    if (!step || typeof document === "undefined") return;

    const cleanups: (() => void)[] = [];

    for (let index = state.stepIndex; index < tutorial.steps.length; index += 1) {
      const candidate = tutorial.steps[index];

      /* The current step only listens if it is asking for a click. A step
         pointing at a text field wants typing, and advancing the moment the
         field is focused would move the callout away mid-sentence. */
      if (index === state.stepIndex && candidate.advance !== "click-target") {
        continue;
      }

      const element = findTarget(candidate.target);
      if (!element) continue;

      const onClick = () => {
        /* After the click, so whatever it opens exists before the next step
           starts looking for its own target. */
        window.setTimeout(() => {
          if (index + 1 < tutorial.steps.length) {
            onStateRef.current({
              ...state,
              stepIndex: index + 1,
              missingTarget: false,
            });
          } else {
            onExitRef.current();
          }
        }, 60);
      };

      element.addEventListener("click", onClick);
      cleanups.push(() => element.removeEventListener("click", onClick));
    }

    return () => cleanups.forEach((cleanup) => cleanup());
  }, [state.stepIndex, step?.id, target.status, tutorial]);

  if (!step) return null;

  const rect = target.status === "found" ? target.rect : null;
  const placement = step.placement ?? "bottom";
  const callout = calloutPosition(rect, placement, panelSize);

  return (
    <div className="kr-tut" role="presentation">
      {/* Four panels around the target rather than one sheet over everything.
          The hole is real: the control keeps its own appearance and stays
          clickable, which is what makes an interactive step possible. */}
      {rect ? (
        <>
          <div className="kr-tut__mask" style={{ top: 0, left: 0, right: 0, height: Math.max(0, rect.top - PAD) }} />
          <div className="kr-tut__mask" style={{ top: rect.top + rect.height + PAD, left: 0, right: 0, bottom: 0 }} />
          <div className="kr-tut__mask" style={{ top: Math.max(0, rect.top - PAD), left: 0, width: Math.max(0, rect.left - PAD), height: rect.height + PAD * 2 }} />
          <div className="kr-tut__mask" style={{ top: Math.max(0, rect.top - PAD), left: rect.left + rect.width + PAD, right: 0, height: rect.height + PAD * 2 }} />

          <div
            className="kr-tut__ring"
            style={{
              top: rect.top - PAD,
              left: rect.left - PAD,
              width: rect.width + PAD * 2,
              height: rect.height + PAD * 2,
            }}
          />

          <div className="kr-tut__arrow-wrap" style={arrowPosition(rect, step.arrow ?? "up")}>
            <TutorialArrow direction={step.arrow ?? "up"} size={ARROW} />
          </div>
        </>
      ) : (
        /* Nothing located yet, so the whole screen dims — never a black screen
           with no explanation. */
        <div className="kr-tut__mask" style={{ inset: 0 }} />
      )}

      <div
        className="kr-tut__callout"
        style={callout}
        role="dialog"
        aria-modal="false"
        aria-labelledby="kr-tut-title"
        tabIndex={-1}
        ref={panel}
      >
        {target.status === "missing" ? (
          <>
            <p className="kr-tut__step">{stepLabel(tutorial, state)}</p>
            <h2 className="kr-tut__title" id="kr-tut-title">
              Cannot find that right now
            </h2>
            <p className="kr-tut__body">
              {isLastStep(tutorial, state)
                ? "The screen has moved on from this step. You can finish here."
                : "The screen has moved on from this step — you may have done it already. Carry on to the next one, or look again."}
            </p>
            {/* Retry alone was a dead end: once a dialog has closed, looking
                again can never succeed, and Exit was the only way out of an
                80% black screen. There is always a way forward now. */}
            <div className="kr-tut__actions">
              <button
                type="button"
                className="kr-tut__btn kr-tut__btn--quiet"
                onClick={onExit}
              >
                Exit
              </button>
              <span className="kr-tut__spacer" />
              <button
                type="button"
                className="kr-tut__btn"
                onClick={() => setRetry((value) => value + 1)}
              >
                Look Again
              </button>
              <button
                type="button"
                className="kr-tut__btn kr-tut__btn--primary"
                onClick={advance}
              >
                {isLastStep(tutorial, state) ? "Finish" : "Continue"}
              </button>
            </div>
          </>
        ) : (
          <>
            <p className="kr-tut__step">{stepLabel(tutorial, state)}</p>
            {/* Announced as it changes, so a screen reader follows along. */}
            <div aria-live="polite">
              <h2 className="kr-tut__title" id="kr-tut-title">
                {step.title}
              </h2>
              <p className="kr-tut__body">{step.body}</p>
            </div>

            {step.advance === "click-target" ? (
              <p className="kr-tut__prompt">
                Go ahead and use the highlighted control to continue.
              </p>
            ) : null}

            {practice ? (
              <span className="kr-tut__practice">
                Practice run — anything you do here is undone when the
                walkthrough ends, and nothing is saved.
              </span>
            ) : null}

            <div className="kr-tut__actions">
              <button type="button" className="kr-tut__btn kr-tut__btn--quiet" onClick={onExit}>
                Exit
              </button>
              <span className="kr-tut__spacer" />
              {!isFirstStep(state) ? (
                <button
                  type="button"
                  className="kr-tut__btn"
                  onClick={() => onState(back(state))}
                >
                  Back
                </button>
              ) : null}
              {/* Present even when the step wants a click. Using the real
                  control is the lesson, but being unable to move on if the
                  screen has already changed is a trap. */}
              <button
                type="button"
                className={
                  step.advance === "click-target"
                    ? "kr-tut__btn"
                    : "kr-tut__btn kr-tut__btn--primary"
                }
                onClick={advance}
              >
                {isLastStep(tutorial, state)
                  ? "Finish"
                  : step.advance === "click-target"
                    ? "Skip"
                    : "Next"}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

/**
 * Places the callout beside the target — never on top of it.
 *
 * The previous version assumed the callout was 190px tall and clamped to the
 * viewport afterwards, which on a mid-screen target pushed the panel straight
 * over the control it was pointing at: the step said "use the highlighted
 * control" while covering it. Telling somebody to press a button and then
 * hiding the button is the worst thing this component can do.
 *
 * So: measure the callout, try the preferred side, and if it does not fit,
 * take whichever side has the most room. Every candidate is rejected outright
 * if it would overlap the spotlight, and the last resort pins it to the far
 * edge of the longest free strip rather than letting it land on the target.
 */
function calloutPosition(
  rect: Rect | null,
  placement: Placement,
  size: { width: number; height: number }
): React.CSSProperties {
  if (typeof window === "undefined" || !rect) {
    return { left: "50%", top: "50%", transform: "translate(-50%, -50%)" };
  }

  const box = rect;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const margin = 16;
  const width = Math.min(CALLOUT_W, vw - margin * 2);
  const height = size.height || 200;

  /* Clearance from the spotlight: its own padding, the gap, and enough of the
     arrow that the two do not collide. */
  const clear = CALLOUT_GAP + ARROW * 0.6;

  const clamp = (value: number, min: number, max: number) =>
    Math.max(min, Math.min(value, max));

  const centreX = clamp(
    box.left + box.width / 2 - width / 2,
    margin,
    Math.max(margin, vw - width - margin)
  );
  const centreY = clamp(
    box.top + box.height / 2 - height / 2,
    margin,
    Math.max(margin, vh - height - margin)
  );

  const candidates: Record<Placement, { top: number; left: number }> = {
    bottom: { top: box.top + box.height + clear, left: centreX },
    top: { top: box.top - clear - height, left: centreX },
    right: { top: centreY, left: box.left + box.width + clear },
    left: { top: centreY, left: box.left - clear - width },
  };

  const fits = (spot: { top: number; left: number }) =>
    spot.top >= margin &&
    spot.left >= margin &&
    spot.top + height <= vh - margin &&
    spot.left + width <= vw - margin &&
    !overlaps(spot);

  /* The spotlight plus its padding. Anything intersecting this is rejected. */
  function overlaps(spot: { top: number; left: number }) {
    const pad = 10;
    return !(
      spot.left + width < box.left - pad ||
      spot.left > box.left + box.width + pad ||
      spot.top + height < box.top - pad ||
      spot.top > box.top + box.height + pad
    );
  }

  const order: Placement[] = [placement, "bottom", "top", "right", "left"];
  for (const side of order) {
    if (fits(candidates[side])) return { ...candidates[side], width };
  }

  /* Nothing fits cleanly — a target near the middle of a short window. Use the
     tallest free strip above or below and pin the callout to the far edge, so
     it is as far from the target as the screen allows and still fully visible. */
  const above = box.top - margin;
  const below = vh - (box.top + box.height) - margin;

  const top =
    below >= above
      ? clamp(vh - height - margin, margin, Math.max(margin, vh - height - margin))
      : margin;

  return { top, left: centreX, width };
}

/** Sits the arrow on the side the callout is coming from, pointing inward. */
function arrowPosition(rect: Rect, direction: string): React.CSSProperties {
  const cx = rect.left + rect.width / 2 - ARROW / 2;
  const cy = rect.top + rect.height / 2 - ARROW / 2;

  if (direction === "up") return { top: rect.top + rect.height + 2, left: cx };
  if (direction === "down") return { top: rect.top - ARROW - 2, left: cx };
  if (direction === "right") return { top: cy, left: rect.left - ARROW - 2 };
  return { top: cy, left: rect.left + rect.width + 2 };
}
