import React from "react";
import { getCmsSlot } from "./plugins";

export default function PluginSlot({ name }: { name: string }) {
  const contributions = getCmsSlot(name);

  if (!contributions.length) return null;

  return (
    <>
      {contributions.map(({ id, component: Component }) => (
        <Component key={id} />
      ))}
    </>
  );
}
