// The property being edited, while it is being edited.
//
// A draft is the canonical property record with everything optional, plus a
// small number of fields that exist only while editing. That is deliberate: a
// half-filled property IS a property record that is not finished yet, and
// giving the wizard its own parallel shape would mean mapping between two
// models on every step and, eventually, the two drifting.
//
// The editing-only fields are named and stripped in one place, `toRecord`
// below, so nothing outside this file has to know they exist and none of them
// can reach the website.
//
// ── on saving ────────────────────────────────────────────────────────────
// Nothing here persists yet. The draft lives in the wizard's own state for the
// duration of the session, which is enough to prove the workflow and honest
// about what it is. The site's content worker is not deployed (see
// applicationsApi and worker/save-json.patch.js), so there is nowhere to save
// to, and the CMS says so rather than showing a tick it cannot back up.
//
// localStorage is deliberately NOT used. It looks like saving and is not: it
// is one browser on one machine, invisible to a colleague, and gone with the
// site data. The adapter boundary below is the real one, so connecting it
// later is a change to this file and nothing else.

import { buildSavePayload } from "./contract.ts";
import demoLocalStorage from "../../../toggles/demo-local-storage.ts";
import { usingSupabase } from "../../supabase/enabled.ts";
import { writeProperty } from "./propertiesRepo.ts";
import {
  clearDraft,
  editDraftKey,
  newDraftKey,
  saveProperty,
} from "./propertiesStore.ts";
import type { FloorPlan } from "../../floor-plans/types";
import type { GalleryImage } from "../../gallery/types";
import type {
  PropertyContent,
  PropertyRecord,
  SimilarPropertyRefs,
} from "../../property/types";

/**
 * Whether the property advertises a figure or asks people to get in touch.
 *
 * Editing-only, because the record already says this: `rentFrom: null` has
 * meant "contact for pricing" since MTC-KRP-024. Keeping the choice separate
 * while editing is what lets someone switch to Ask for Pricing, change their
 * mind, and get their number back — without the number being able to reach the
 * public page in the meantime. `toRecord` is where the choice is applied.
 */
export type PriceDisplay = "show" | "ask";

export type PropertyDraft = Partial<
  Omit<PropertyRecord, "content" | "similar">
> & {
  content?: PropertyContent;
  similar?: SimilarPropertyRefs;
  images?: GalleryImage[];
  floorPlans?: FloorPlan[];

  /* ── editing only, never written to the record ───────────── */
  priceDisplay?: PriceDisplay;
  /**
   * Set when the draft came from a property that already exists.
   *
   * An address that has been shared, linked or indexed should not change
   * because somebody corrected a typo in the display name, so the slug of an
   * existing property is fixed. A new property has no address yet, so its slug
   * follows the name until it is first saved.
   */
  slugLocked?: boolean;
};

/** The keys above that exist only while editing. */
const EDITOR_ONLY = ["priceDisplay", "slugLocked"] as const;

export function emptyDraft(): PropertyDraft {
  return { publication: "draft", priceDisplay: "show" };
}

/** Opens an existing property in the wizard. Edit and create share everything. */
export function draftFromProperty(property: PropertyRecord): PropertyDraft {
  return {
    ...property,
    /* Read from the record rather than stored twice: null has always been the
       canonical way to say "contact for pricing". */
    priceDisplay: property.rentFrom === null ? "ask" : "show",
    slugLocked: true,
  };
}

/* ── slugs ───────────────────────────────────────────────── */

/**
 * The address a property gets from its name.
 *
 * Matches the twelve existing records exactly — "Oakwood Apartments" is
 * `oakwood-apartments` — so a property created here is indistinguishable from
 * one that shipped with the site.
 */
export function proposeSlug(title: string): string {
  return (title ?? "")
    .normalize("NFKD")
    /* Accents stripped after NFKD so a name with them still yields a clean address. */
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/**
 * The draft with its slug brought up to date.
 *
 * Only ever moves for a property that does not exist yet; see `slugLocked`.
 */
export function withProposedSlug(draft: PropertyDraft): PropertyDraft {
  if (draft.slugLocked) return draft;

  const slug = proposeSlug(draft.title ?? "");
  return slug === draft.slug ? draft : { ...draft, slug };
}

/* ── paragraphs ──────────────────────────────────────────── */

/**
 * The description, as the overview needs it.
 *
 * Stored as an array because the renderer shows the first two paragraphs and
 * hides the rest behind Read More — it has to know where they divide. A blank
 * line is the division, which is how people already type, so nobody has to
 * learn a format and nobody has to type HTML.
 */
export function textToParagraphs(text: string): string[] {
  return (text ?? "")
    .split(/\n\s*\n/)
    .map((part) => part.trim().replace(/\s*\n\s*/g, " "))
    .filter(Boolean);
}

/** The inverse, for putting a stored description back in the box. */
export function paragraphsToText(paragraphs: string[] | undefined): string {
  return (paragraphs ?? []).join("\n\n");
}

/* ── the canonical record ────────────────────────────────── */

/**
 * What would actually be saved.
 *
 * Everything the wizard promises about pricing, photograph counts and editing
 * state is enforced here rather than in a component, so the review screen can
 * be built from this and show precisely what publishing would put on the
 * website — not an approximation of it.
 */
export function toRecord(draft: PropertyDraft): PropertyDraft {
  const record: PropertyDraft = { ...draft };

  for (const key of EDITOR_ONLY) delete record[key];

  /* Ask for Pricing means the page must not show a figure, so the figure does
     not travel — however recently it was typed, and whatever else changes. */
  if (draft.priceDisplay === "ask") {
    record.rentFrom = null;
    record.rent = 0;
  } else if (typeof draft.rent === "number" && draft.rent > 0) {
    record.rentFrom = draft.rent;
  }

  /* Counted from the photographs by derive.photoCount, never typed. Several
     bundled listings claimed eighteen while the gallery had eight, so the
     hero's "View 18 Photos" broke on the next click. Nothing this CMS writes
     can reintroduce that. */
  delete record.photoCount;

  return record;
}

/**
 * A stable, deterministic serializer for property data comparison.
 *
 * Plain JSON.stringify is key-order sensitive: two objects with the same
 * fields in different orders stringify differently, which produces false
 * dirty states when the wizard loads a localStorage recovery draft (whose
 * key order may differ from the original built by draftFromProperty).
 *
 * Rules:
 *   - Object keys are sorted alphabetically before serialization so the same
 *     data always produces the same string regardless of insertion order.
 *   - Arrays retain their order — arrays where order is meaningful (images,
 *     floorPlans, amenities) must stay order-sensitive.
 *   - null, undefined, numbers, strings and booleans serialize as JSON.
 *   - undefined object values are omitted (same semantics as JSON.stringify).
 */
function stableSerialize(value: unknown): string {
  if (value === null || value === undefined) return String(value);
  if (typeof value !== "object") return JSON.stringify(value);

  if (Array.isArray(value)) {
    return "[" + value.map(stableSerialize).join(",") + "]";
  }

  const keys = Object.keys(value as object).sort();
  const pairs = keys
    .filter((k) => (value as Record<string, unknown>)[k] !== undefined)
    .map((k) => JSON.stringify(k) + ":" + stableSerialize((value as Record<string, unknown>)[k]));

  return "{" + pairs.join(",") + "}";
}

/**
 * Whether anything has been typed that would be lost.
 *
 * Compared against the starting point rather than against emptiness, so
 * opening a property to look at it and leaving again does not warn about
 * changes nobody made.
 *
 * Uses stableSerialize rather than JSON.stringify so that key-order differences
 * between the in-memory draft (built by draftFromProperty / emptyDraft) and a
 * recovered localStorage draft never produce a false dirty state.
 */
export function hasUnsavedChanges(
  draft: PropertyDraft,
  original: PropertyDraft
): boolean {
  return stableSerialize(draft) !== stableSerialize(original);
}

/**
 * A stable hash of the persisted property fields.
 *
 * Useful for comparing baseline vs current state without holding full object
 * references, and for tests that want a single value to assert against.
 *
 * Not a cryptographic hash — just a fast deterministic fingerprint based on
 * the stable serialization above.
 */
export function draftHash(draft: PropertyDraft): string {
  return stableSerialize(draft);
}

/* ── the save boundary ───────────────────────────────────── */

/**
 * What the user asked the save to do.
 *
 * "draft"     — keep as unpublished
 * "publish"   — make publicly visible
 * "unpublish" — retract a previously published property back to draft
 *
 * The API layer only distinguishes "draft" vs "publish"; unpublish is handled
 * by the wizard's save() function by forcing publication:"draft" and then
 * calling the API with intent "draft".
 */
export type SaveIntent = "draft" | "publish" | "unpublish";

export type SaveOutcome =
  | { ok: true; record: PropertyDraft }
  | { ok: false; reason: string; notConnected: boolean };

export type PropertyDraftApi = {
  save: (record: PropertyDraft, intent: SaveIntent) => Promise<SaveOutcome>;
};

const NOT_CONNECTED =
  "Property storage isn't connected for this site yet, so this can't be saved. Your work is still here while you stay on this page.";

/**
 * The adapter the wizard saves through.
 *
 * Real, and currently refusing — which is the truthful state. Both Save Draft
 * and Publish come through here, which is why publishing cannot accidentally
 * become a thing the interface does on its own: the only way `publication`
 * becomes "published" is a save that actually succeeded.
 *
 * When the content worker is deployed this becomes the same authenticated POST
 * the Application Builder uses, and the wizard needs no changes.
 */
/**
 * The real adapter, for when the content worker exists.
 *
 * Still refuses, truthfully. The payload is built on every attempt rather than
 * only being described in a document, so the shape in contract.ts is exercised
 * rather than drifting.
 */
export const remotePropertyDraftApi: PropertyDraftApi = {
  async save(record, intent): Promise<SaveOutcome> {
    const payload = buildSavePayload(record, intent);
    void payload;

    return { ok: false, notConnected: true, reason: NOT_CONNECTED };
  },
};

/**
 * Demo persistence: the same interface, saving to this browser.
 *
 * The wizard is unchanged. It still builds the canonical record, still applies
 * the pricing rule, still strips the editing-only fields — the only difference
 * is where the result goes. Publishing sets `publication` here rather than
 * being taken on trust from the caller, so a save that failed cannot leave a
 * property looking published.
 */
export const localPropertyDraftApi: PropertyDraftApi = {
  async save(record, intent): Promise<SaveOutcome> {
    const stored: PropertyDraft = {
      ...record,
      publication: intent === "publish" ? "published" : (record.publication ?? "draft"),
    };

    const result = saveProperty(stored);

    if (!result.ok) {
      return { ok: false, notConnected: false, reason: result.reason };
    }

    /* The half-finished copy is dropped now the finished one exists, or a
       later visit would reopen the draft instead of the property. */
    clearDraft(stored.slug ? editDraftKey(stored.slug) : newDraftKey());
    clearDraft(newDraftKey());

    return { ok: true, record: stored };
  },
};

/**
 * Supabase: the same interface again, saving to the property catalogue.
 *
 * Deliberately a near-copy of the demo adapter rather than a refactor of it.
 * The two differ in exactly one line — which store they call — and the
 * publication rule below has to hold identically in both. Folding them
 * together behind a parameter would save four lines and make it possible to
 * change that rule for one backend and not the other.
 */
export const supabasePropertyDraftApi: PropertyDraftApi = {
  async save(record, intent): Promise<SaveOutcome> {
    const stored: PropertyDraft = {
      ...record,
      publication: intent === "publish" ? "published" : (record.publication ?? "draft"),
    };

    const result = await writeProperty(stored);

    if (!result.ok) {
      return { ok: false, notConnected: false, reason: result.reason };
    }

    /* The half-finished copy is dropped now the finished one exists, or a
       later visit would reopen the draft instead of the property. */
    clearDraft(stored.slug ? editDraftKey(stored.slug) : newDraftKey());
    clearDraft(newDraftKey());

    return { ok: true, record: stored };
  },
};

/**
 * The one the wizard uses.
 *
 * Supabase first, because a real backend beats a demo of one. It only wins
 * when the project is actually configured — see modules/supabase/enabled —
 * so a site with the toggle on and no keys still falls back to demo storage
 * rather than failing every save.
 */
export const propertyDraftApi: PropertyDraftApi = usingSupabase()
  ? supabasePropertyDraftApi
  : demoLocalStorage
    ? localPropertyDraftApi
    : remotePropertyDraftApi;

export const STORAGE_NOT_CONNECTED = NOT_CONNECTED;
