// The walkthrough's logic, with no DOM in it.
//
// Everything that decides what happens next — which step, whether Back is
// available, whether the last step says Finish, whether a tutorial can run at
// all — lives here as pure functions over a small state object. The overlay
// renders this; it does not decide anything.
//
// The state is deliberately ephemeral. It is never written to the applications
// document: a walkthrough is something a person is doing right now, not a
// property of the form they are editing.

import type { Prerequisite, Tutorial, TutorialStep } from "./types";

export type TutorialState = {
  tutorialId: string;
  stepIndex: number;
  /** Set when the target could not be found, so the UI can offer Retry. */
  missingTarget: boolean;
};

export type TutorialContext = {
  /** How many applications are in the trash right now. */
  trashCount: number;
  /** How many live applications exist. */
  applicationCount: number;
};

export function start(tutorial: Tutorial): TutorialState {
  return { tutorialId: tutorial.id, stepIndex: 0, missingTarget: false };
}

export function currentStep(
  tutorial: Tutorial,
  state: TutorialState
): TutorialStep | null {
  return tutorial.steps[state.stepIndex] ?? null;
}

export const isFirstStep = (state: TutorialState) => state.stepIndex === 0;

export const isLastStep = (tutorial: Tutorial, state: TutorialState) =>
  state.stepIndex >= tutorial.steps.length - 1;

/** "Step 2 of 5", for people who want to know how much is left. */
export function stepLabel(tutorial: Tutorial, state: TutorialState): string {
  return `Step ${state.stepIndex + 1} of ${tutorial.steps.length}`;
}

/** Advancing past the last step ends the walkthrough, hence the null. */
export function next(
  tutorial: Tutorial,
  state: TutorialState
): TutorialState | null {
  if (isLastStep(tutorial, state)) return null;
  return { ...state, stepIndex: state.stepIndex + 1, missingTarget: false };
}

export function back(state: TutorialState): TutorialState {
  return {
    ...state,
    stepIndex: Math.max(0, state.stepIndex - 1),
    missingTarget: false,
  };
}

export function markMissing(state: TutorialState, missing: boolean): TutorialState {
  return state.missingTarget === missing
    ? state
    : { ...state, missingTarget: missing };
}

/**
 * Finds a later step whose target is already on screen.
 *
 * A walkthrough describes one route through the interface, but the reader is
 * using the real thing and will not always take it. Typing a name and pressing
 * Create — rather than pressing Next and then Create — is the obvious example,
 * and it is what a sensible person does: the dialog is in front of them and
 * they have finished with it.
 *
 * When that happens the current step's target is gone, and so is every step
 * between here and where the interface has actually got to. Rather than telling
 * the reader the screen has moved on, look ahead: if a later step's target is
 * present, that is where they are, so go there.
 *
 * Only ever forwards. Jumping backwards would fight the reader for control of
 * their own screen.
 */
export function findResumeStep(
  tutorial: Tutorial,
  state: TutorialState,
  exists: (target: string) => boolean
): number | null {
  for (let index = state.stepIndex + 1; index < tutorial.steps.length; index += 1) {
    if (exists(tutorial.steps[index].target)) return index;
  }
  return null;
}

/**
 * Whether a walkthrough has anything to show.
 *
 * Checked before starting rather than discovered three steps in, so the reader
 * gets an explanation instead of a spotlight over nothing.
 */
export function checkPrerequisite(
  requires: Prerequisite | undefined,
  context: TutorialContext
): boolean {
  if (!requires || requires === "none") return true;
  if (requires === "hasTrash") return context.trashCount > 0;
  if (requires === "hasTwoApplications") return context.applicationCount > 1;
  return true;
}

export function canRun(tutorial: Tutorial, context: TutorialContext): boolean {
  return checkPrerequisite(tutorial.requires, context);
}
