import React, { useCallback, useEffect, useMemo, useState } from "react";
import { Link, navigate } from "gatsby";
import {
  LuBuilding2,
  LuCheck,
  LuExternalLink,
  LuImageOff,
  LuInfo,
  LuPencil,
  LuPlus,
  LuTrash2,
} from "react-icons/lu";

import CmsTabs from "../shared/CmsTabs";
import PropertiesHelpTab from "./PropertiesHelpTab";
import PropertiesTrashTab from "./PropertiesTrashTab";
import SelectionToast from "./SelectionToast";
import WizardDialog from "./wizard/WizardDialog";
import {
  TRASH_DAYS,
  deleteProperties,
  liveProperties,
  restoreProperty,
  trashedProperties,
} from "./propertyRules";
import {
  hydrateProperties,
  savedProperties,
  writeProperties,
} from "./wizard/propertiesRepo";

import { properties as records } from "../../primitives/property/property-data";
import { resolveProperties } from "../../primitives/property/property-images";
import { toCardModel } from "./propertyCard";
import {
  editDraftKey,
  mergeProperties,
  newDraftKey,
  withOwnImage,
} from "./wizard/propertiesStore";
import demoLocalStorage from "../../toggles/demo-local-storage";
import { usingSupabase } from "../supabase/enabled";
import type { PropertyCardModel } from "./propertyCard";
import PropertyWizard from "./wizard/PropertyWizard";
import { draftFromProperty } from "./wizard/draft";
import { PROPERTIES_ROUTE } from "./types";

export type PropertiesViewProps = {
  /** The full browser pathname; the view resolves its own tail. */
  pathname: string;
};

/**
 * My Properties.
 *
 * The card language is the Application Builder's, adapted rather than copied:
 * the same status band across the top, the same header, the same preview-then-
 * actions rhythm, the same restrained palette. What differs is what the preview
 * shows. An application is recognised by its first few questions; a property is
 * recognised by its photograph, its name and where it is. Rendering form fields
 * inside a property card would be reuse of the wrong half.
 *
 * The screen also owns two sub-routes, add and edit, both of which open the
 * same property workflow. They differ only in where the draft starts.
 */
export default function PropertiesView({ pathname }: PropertiesViewProps) {
  /* Keyed on the path, not on nothing. This component does not unmount when
     the wizard closes — the same instance re-renders with a new pathname — so
     an empty dependency list would have shown the catalogue as it was when the
     CMS first opened, and a property the user had just saved would not appear
     until they refreshed. The samples are never written to; a saved record
     with the same slug replaces one for display only. */
  /* Bumped by anything that writes a property, so the merged catalogue is
     re-read. Deleting and restoring change stored data without changing the
     URL, and the memo below would otherwise keep showing the list as it was
     when the tab opened. */
  const [revision, setRevision] = useState(0);

  const catalogue = useMemo(
    /* Through the repo, so this is the bundled samples in demo mode and the
       fetched catalogue on Supabase — and this component cannot tell which.
       `revision` is what re-reads it after a save, a delete or the fetch
       below completing. */
    () => mergeProperties(records, savedProperties()),
    [pathname, revision]
  );

  /* ── delete mode ──────────────────────────────────────
     Selection is ordinary component state and stays that way. What is selected
     is a thing the user is doing right now, not a fact about the property, so
     it is not persisted and a refresh clears it — which is the behaviour you
     want if you walk away mid-selection. `deletedAt` IS property data, and
     that goes through the storage adapter like everything else. */
  const [selecting, setSelecting] = useState(false);
  const [selected, setSelected] = useState<string[]>([]);
  const [confirming, setConfirming] = useState(false);
  const [busy, setBusy] = useState(false);
  const [problem, setProblem] = useState<string | null>(null);

  /* Fetches the catalogue once, on mount.
     Until it resolves the merged list is the BUNDLED samples, which may
     include properties the client deleted months ago — so the list waits
     rather than showing something untrue for a moment. */
  const [loading, setLoading] = useState(true);

  /* The slugs that actually have a public page.
     Written by gatsby-node at build time. Without it this screen has to guess,
     and it guessed wrong in one direction forever: a property added in the CMS
     had its View button disabled even after the site was rebuilt and its page
     existed. `null` means "not known yet", which falls back to the bundled
     list — the cautious answer, never a link to a 404. */
  const [builtSlugs, setBuiltSlugs] = useState<string[] | null>(null);

  useEffect(() => {
    let mounted = true;

    fetch("/built-properties.json", { headers: { Accept: "application/json" } })
      .then((res) => (res.ok ? res.json() : null))
      .then((data) => {
        if (mounted && Array.isArray(data?.slugs)) setBuiltSlugs(data.slugs);
      })
      .catch(() => {
        /* No such file — a dev server, or a build from before this existed.
           The fallback below covers it. */
      });

    return () => {
      mounted = false;
    };
  }, []);

  useEffect(() => {
    let mounted = true;

    hydrateProperties()
      .then((outcome) => {
        if (!mounted) return;
        /* A failed fetch is said out loud. The CMS still opens, on the
           bundled samples, but nobody should edit for an hour believing they
           are looking at live data. */
        if (!outcome.ok) setProblem(outcome.reason);
        setRevision((value) => value + 1);
      })
      .finally(() => {
        if (mounted) setLoading(false);
      });

    return () => {
      mounted = false;
    };
  }, []);

  /* One clock for the whole view, so the Trash list and its countdowns cannot
     disagree part-way through a render. */
  const now = useMemo(() => Date.now(), [revision, pathname]);

  const leaveSelection = useCallback(() => {
    setSelecting(false);
    setSelected([]);
    setConfirming(false);
  }, []);

  const toggle = useCallback((slug: string) => {
    setSelected((current) =>
      current.includes(slug)
        ? current.filter((item) => item !== slug)
        : [...current, slug]
    );
  }, []);

  /**
   * Writes the change, then reports whether it actually happened.
   *
   * Every record goes through the same adapter a wizard save uses, so demo
   * storage and a future backend both work without this screen knowing which
   * it is talking to. A failure is surfaced rather than swallowed: a delete
   * that silently did nothing is the kind of thing somebody discovers a week
   * later.
   */
  const persist = useCallback(async (next: typeof catalogue): Promise<boolean> => {
    /* ONE write for the whole batch. Deleting four properties used to be four
       sequential writes of the same catalogue, which is slower and gives the
       third a chance to fail after the second has already landed. */
    const outcome = await writeProperties(next);

    if (!outcome.ok) {
      setProblem(outcome.reason);
      return false;
    }

    setProblem(null);
    setRevision((value) => value + 1);
    return true;
  }, []);

  const listings = useMemo(() => {
    /* Gatsby builds one static page per property at BUILD time, so a property
       saved a minute ago has no page to open yet — however "published" the
       CMS considers it. Linking to it would 404, which is a worse lie than
       saying so. The card's View is disabled instead and explains why.

       The build now writes the list of pages it created, so once the site is
       rebuilt a CMS-created property's View starts working on its own. Until
       that file is read, the bundled properties are the only ones assumed to
       have pages. */
    const built = new Set(builtSlugs ?? records.map((record) => record.slug));

    return resolveProperties(catalogue)
      .map(withOwnImage)
      .map(toCardModel)
      .map((card) =>
        built.has(card.slug) ? card : { ...card, href: null, localOnly: true }
      )
      /* Carried onto the card so the Trash tab can show its countdown without
         going back to the record for it. */
      .map((card) => ({
        ...card,
        deletedAt:
          catalogue.find((record) => record.slug === card.slug)?.deletedAt ?? null,
      }));
  }, [catalogue, builtSlugs]);

  /* The two halves of the catalogue. Everything below reads one or the other,
     never the unfiltered list — a deleted property must not appear anywhere it
     could be mistaken for an active one. */
  const active = useMemo(() => liveProperties(listings), [listings]);
  const trashed = useMemo(() => trashedProperties(listings, now), [listings, now]);

  /* Resolve the tail this view was handed by the segment-aware router. */
  const tail = pathname
    .replace(/[?#].*$/, "")
    .replace(/^\/+|\/+$/g, "")
    .replace(/^dashboard\/properties\/?/, "");

  const segments = tail ? tail.split("/") : [];

  /* Create and edit are the same workflow. The only difference is where the
     draft starts, so there is one shell rather than two screens to keep in
     step. The step lives in the URL, so a refresh returns to the step the
     user was on rather than the beginning. */
  if (segments[0] === "new") {
    return (
      <PropertyWizard
        mode="create"
        stepId={segments[1]}
        draftKey={newDraftKey()}
        onNavigateStep={(step) => navigate(`${PROPERTIES_ROUTE}/new/${step}`)}
        onExit={() => navigate(PROPERTIES_ROUTE)}
      />
    );
  }

  if (segments[0] === "edit" && segments[1]) {
    const slug = decodeURIComponent(segments[1]);
    /* From the merged catalogue, so editing a property twice continues from
       the first edit rather than reverting to the bundled sample. */
    const record = catalogue.find((item) => item.slug === slug);

    if (!record) {
      return (
        <div className="kr-props">
          <div className="kr-props__empty">
            <span className="kr-props__empty-icon" aria-hidden="true">
              <LuBuilding2 size={21} />
            </span>
            <h2 className="kr-props__empty-title">Property not found</h2>
            <p className="kr-props__empty-text">
              That property may have been removed. Choose one from the list.
            </p>
            <Link to={PROPERTIES_ROUTE} className="kr-props__btn">
              My Properties
            </Link>
          </div>
        </div>
      );
    }

    return (
      <PropertyWizard
        mode="edit"
        stepId={segments[2]}
        draftKey={editDraftKey(slug)}
        subjectName={record.title}
        initialDraft={draftFromProperty(record)}
        onNavigateStep={(step) =>
          navigate(`${PROPERTIES_ROUTE}/edit/${encodeURIComponent(slug)}/${step}`)
        }
        onExit={() => navigate(PROPERTIES_ROUTE)}
      />
    );
  }

  const published = active.filter(
    (listing) => listing.publication === "published"
  ).length;

  /* The tab lives in the URL, like the Application Builder's, so a refresh
     comes back to the tab you were on and a colleague can be sent to the
     Trash directly. "new" and "edit" are handled above, so there is no
     collision with a slug. */
  const tab: "properties" | "trash" | "help" =
    segments[0] === "trash" ? "trash" : segments[0] === "help" ? "help" : "properties";

  const goToTab = (key: "properties" | "trash" | "help") => {
    leaveSelection();
    navigate(key === "properties" ? PROPERTIES_ROUTE : `${PROPERTIES_ROUTE}/${key}`);
  };

  const confirmDelete = async () => {
    setBusy(true);
    const next = deleteProperties(catalogue, selected, Date.now());
    const changed = next.filter((record) =>
      selected.includes(record.slug as string)
    );

    const saved = await persist(changed);
    setBusy(false);

    /* Selection is only cleared on a write that actually happened. A failed
       delete leaves the cards still selected, so the user can try again
       rather than watching their selection vanish and wondering whether it
       worked. */
    if (saved) leaveSelection();
    else setConfirming(false);
  };

  const restore = async (slug: string) => {
    setBusy(true);
    const next = restoreProperty(catalogue, slug);
    const changed = next.filter((record) => record.slug === slug);
    await persist(changed);
    setBusy(false);
  };

  return (
    <div className="kr-props">
      <CmsTabs
        classPrefix="kr-props"
        idPrefix="kr-props"
        label="Properties sections"
        active={tab}
        onChange={goToTab}
        tabs={[
          { key: "properties" as const, label: "Properties" },
          { key: "trash" as const, label: "Trash", count: trashed.length },
          { key: "help" as const, label: "Help" },
        ]}
      />

      <div
        role="tabpanel"
        id={`kr-props-panel-${tab}`}
        aria-labelledby={`kr-props-tab-${tab}`}
      >
        {problem ? (
          <p className="kr-props__problem" role="alert">
            {problem}
          </p>
        ) : null}

        {tab === "help" ? <PropertiesHelpTab /> : null}

        {tab === "trash" ? (
          <PropertiesTrashTab
            properties={trashed}
            onRestore={restore}
            busy={busy}
            now={now}
          />
        ) : null}

        {tab === "properties" ? (
          /* Until the catalogue has been fetched, what is on screen is the
             bundled sample list — which may include properties the client
             deleted months ago. Showing one line for the fraction of a second
             that takes is better than showing something untrue. */
          loading ? (
            <p className="kr-props__hint" role="status">
              Loading your properties…
            </p>
          ) : active.length === 0 ? (
            <div className="kr-props__empty">
              <span className="kr-props__empty-icon" aria-hidden="true">
                <LuBuilding2 size={21} />
              </span>
              <h2 className="kr-props__empty-title">No properties yet</h2>
              <p className="kr-props__empty-text">
                Add your first property to start building your listings.
              </p>
              <Link
                to={`${PROPERTIES_ROUTE}/new`}
                className="kr-props__btn kr-props__btn--primary"
              >
                <LuPlus size={15} aria-hidden="true" /> Add New Property
              </Link>
            </div>
          ) : (
            <>
              <div className="kr-props__head">
                <div>
                  <h2 className="kr-props__title">My Properties</h2>
                  <p className="kr-props__hint">
                    {selecting
                      ? "Choose the properties you want to delete."
                      : <>
                          {active.length}{" "}
                          {active.length === 1 ? "property" : "properties"}
                          {published === active.length
                            ? " on your website."
                            : ` · ${published} on your website.`}
                        </>}
                  </p>
                </div>

                <div className="kr-props__actions-bar">
                  {/* Cancel appears to the LEFT of Delete, as asked. */}
                  {selecting ? (
                    <button
                      type="button"
                      className="kr-props__btn"
                      onClick={leaveSelection}
                    >
                      Cancel
                    </button>
                  ) : null}

                  <button
                    type="button"
                    className="kr-props__btn kr-props__btn--danger"
                    /* Out of selection mode this ARMS the mode; in it, this is
                       the delete itself and needs something selected. */
                    disabled={selecting && selected.length === 0}
                    onClick={() =>
                      selecting ? setConfirming(true) : setSelecting(true)
                    }
                  >
                    <LuTrash2 size={15} aria-hidden="true" /> Delete
                  </button>

                  {selecting ? null : (
                    <Link
                      to={`${PROPERTIES_ROUTE}/new`}
                      className="kr-props__btn kr-props__btn--primary"
                    >
                      <LuPlus size={15} aria-hidden="true" /> Add New Property
                    </Link>
                  )}
                </div>
              </div>

              {/* One line, and it has to keep pace with what is actually
                  true. It used to say changes could not be saved, which
                  stopped being true the moment they could; it then said they
                  were saved on this device, which stopped being true the
                  moment Supabase answered. With a real backend there is
                  nothing unusual to report, so it says nothing. */}
              {usingSupabase() ? null : (
                <p className="kr-props__note">
                  <LuInfo size={15} className="kr-props__note-icon" aria-hidden="true" />
                  <span>
                    {demoLocalStorage
                      ? "Demo mode · Changes are saved on this device until permanent storage is connected."
                      : "Property storage isn't connected yet, so changes cannot be saved."}
                  </span>
                </p>
              )}

              <div className="kr-props__grid">
                {active.map((listing) => (
                  <PropertyCard
                    key={listing.id}
                    property={listing}
                    selecting={selecting}
                    selected={selected.includes(listing.slug)}
                    onToggle={() => toggle(listing.slug)}
                  />
                ))}
              </div>
            </>
          )
        ) : null}
      </div>

      <SelectionToast count={selecting ? selected.length : 0} />

      {confirming ? (
        <WizardDialog
          title={
            selected.length === 1
              ? "Delete this property?"
              : `Delete ${selected.length} properties?`
          }
          text={
            selected.length === 1
              ? "It will be removed from your website and from this list."
              : "They will be removed from your website and from this list."
          }
          note={`Deletions are final, but you can put ${
            selected.length === 1 ? "it" : "them"
          } back from the Trash for ${TRASH_DAYS} days.`}
          confirmLabel={selected.length === 1 ? "Delete property" : "Delete properties"}
          cancelLabel="Cancel"
          danger
          onConfirm={confirmDelete}
          onClose={() => setConfirming(false)}
        />
      ) : null}
    </div>
  );
}

/* ── one property ────────────────────────────────────────── */

function PropertyCard({
  property,
  selecting = false,
  selected = false,
  onToggle,
}: {
  property: PropertyCardModel & { localOnly?: boolean };
  selecting?: boolean;
  selected?: boolean;
  onToggle?: () => void;
}) {
  const draft = property.publication === "draft";

  const classes = [
    "kr-props__card",
    selecting ? "kr-props__card--selectable" : "",
    selected ? "kr-props__card--selected" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const body = (
    <>
      <p
        className={`kr-props__flag kr-props__flag--${draft ? "draft" : "published"}`}
        style={{ margin: 0 }}
      >
        {draft ? null : <LuCheck size={13} aria-hidden="true" />}
        {draft ? "Draft" : "Published"}
      </p>

      <div className="kr-props__body">
        <h3 className="kr-props__name">{property.title}</h3>
        <p className="kr-props__place">{property.location}</p>

        <div className="kr-props__media">
          {property.image ? (
            <img
              className="kr-props__image"
              src={property.image}
              srcSet={property.imageSrcSet}
              sizes="(max-width: 640px) 100vw, 300px"
              alt={property.imageAlt}
              loading="lazy"
              decoding="async"
            />
          ) : (
            <span className="kr-props__placeholder" aria-hidden="true">
              <LuImageOff size={19} />
              <span>No photo yet</span>
            </span>
          )}
        </div>

        {property.meta.length > 0 ? (
          <ul className="kr-props__meta">
            {property.meta.map((part) => (
              <li key={part}>{part}</li>
            ))}
          </ul>
        ) : null}

        {property.availability ? (
          <p className={`kr-props__pill kr-props__pill--${property.availabilityTone}`}>
            {property.availability}
          </p>
        ) : null}
      </div>
    </>
  );

  /* In selection mode the whole card IS the control, so it is a real button
     rather than a div with a click handler — that is what gives it Enter,
     Space, the tab order and an announced pressed state for free. Edit and
     View are not rendered at all while selecting, so a click cannot navigate
     away by accident and there is no nested-button markup. */
  if (selecting) {
    return (
      <button
        type="button"
        className={classes}
        aria-pressed={selected}
        onClick={onToggle}
      >
        {body}
        <span className="kr-props__select-mark" aria-hidden="true">
          {selected ? <LuCheck size={14} /> : null}
        </span>
        <span className="kr-sr-only">
          {selected ? "Selected for deletion" : "Select for deletion"}
        </span>
      </button>
    );
  }

  return (
    <article className={classes}>
      {body}

      <div className="kr-props__actions">
        <Link
          to={`${PROPERTIES_ROUTE}/edit/${encodeURIComponent(property.slug)}`}
          className="kr-props__btn"
        >
          <LuPencil size={13} aria-hidden="true" /> Edit
        </Link>

        <span className="kr-props__spacer" />

        {property.href ? (
          <a
            className="kr-props__btn"
            href={property.href}
            target="_blank"
            rel="noreferrer"
          >
            View
            <LuExternalLink size={13} aria-hidden="true" />
            <span className="kr-sr-only">
              {property.title} on the website, opens in a new tab
            </span>
          </a>
        ) : (
          <button
            type="button"
            className="kr-props__btn"
            disabled
            title={
              property.localOnly
                ? "Saved. Its public page is created the next time the site is published."
                : "Not published yet"
            }
          >
            View
          </button>
        )}
      </div>
    </article>
  );
}
