import React from "react";
import { LuClipboardList } from "react-icons/lu";

import template from "../../config/gh-apply--template";
import applyEnabled from "../../toggles/apply-builder";
import applyPreviewEnabled from "../../toggles/apply-builder--preview";
import applyViewEnabled from "../../toggles/apply-builder--view";
import ApplyPreview from "./ApplyPreview";
import ApplyView from "./ApplyView";
import { APPLY_VIEW_PATH } from "./types";
import type { CmsPlugin, CmsViewProps } from "../opencms/core/plugin-types";

/**
 * The page the CMS mounts.
 *
 * Thin on purpose — it emits the plugin's stylesheet and hands the pathname
 * on. Everything else belongs to the view, which is the same division gh-leads
 * uses.
 */
function ApplicationBuilderPage({ pathname }: CmsViewProps) {
  return (
    <>
      <style>{template.css}</style>
      <ApplyView pathname={pathname} />
    </>
  );
}

/**
 * Application Builder — MTC-KRP-017.
 *
 * Registered by nothing: plugins.ts finds this file with require.context, so
 * the folder existing is the whole installation step. Both contributions are
 * toggle-gated, the same way gh-leads gates its own.
 *
 * PVST, concretely:
 *   View     ApplyView, at /dashboard/applications, plus its own sub-routes
 *   Preview  ApplyPreview, in the dashboard slot
 *   Slot     the `dashboard` slot below, which PluginSlot renders
 *   Template templates/gh-apply, reached through config/gh-apply--template
 */
const plugin: CmsPlugin = {
  id: "apply-builder",

  views:
    applyEnabled && applyViewEnabled
      ? [
          {
            id: "apply-builder",
            path: APPLY_VIEW_PATH,
            label: template.labels.navLabel,
            component: ApplicationBuilderPage,
            nav: true,
            /* After Images (100) and Leads (200): an editor reaches for
               submissions more often than for the form behind them. */
            order: 300,
            icon: LuClipboardList,
          },
        ]
      : [],

  slots: {
    dashboard:
      applyEnabled && applyPreviewEnabled
        ? [{ id: "apply-builder-dashboard", component: ApplyPreview, order: 300 }]
        : [],
  },
};

export default plugin;
