import { useEffect, useState } from "react";

/**
 * Current epoch ms, or `null` until the component has mounted on the client.
 *
 * Relative timestamps ("12 min ago") are derived from the clock, so rendering
 * them during the Gatsby SSR build would produce markup the browser disagrees
 * with. Callers render an absolute stamp while this is null and swap to
 * relative once it resolves. Ticks every minute so ages stay honest on a
 * dashboard left open.
 */
export function useNow(intervalMs = 60_000): number | null {
  const [now, setNow] = useState<number | null>(null);

  useEffect(() => {
    setNow(Date.now());

    const timer = setInterval(() => setNow(Date.now()), intervalMs);

    return () => clearInterval(timer);
  }, [intervalMs]);

  return now;
}
