// Where properties live during the client demo.
//
// Two separate things are kept, and the difference matters:
//
//   SAVED PROPERTIES  kr:properties:v1
//     Finished records, by slug. What Save Draft and Publish write, and what
//     My Properties lists alongside the twelve bundled samples.
//
//   THE OPEN DRAFT    kr:property-draft:v1
//     The half-filled wizard, by route. What makes a refresh in the middle of
//     step three land back on step three with everything still typed. Cleared
//     the moment the property is actually saved, so a finished property is
//     never shadowed by a stale copy of itself.
//
// The twelve bundled properties are never written to and never overwritten.
// Editing one stores an OVERRIDE under its slug; the source file on disk is
// untouched, which is what keeps the demo reversible — clear the key and the
// site is exactly as it shipped.

import { featuredImage } from "../../property/derive.ts";
import type { Property, PropertyRecord } from "../../property/types";
import { STORAGE_KEYS, readJson, writeJson } from "../../shared/localStore.ts";
import type { WriteResult } from "../../shared/localStore";
import type { PropertyDraft } from "./draft";

/* ── saved properties ────────────────────────────────────── */

/** Slug to record. Keyed by slug because that is what the site routes on. */
export type SavedProperties = Record<string, PropertyDraft>;

function parseSaved(value: unknown): SavedProperties | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;

  const out: SavedProperties = {};

  for (const [slug, record] of Object.entries(value as Record<string, unknown>)) {
    /* A record with no slug and no title is not a property, whatever else it
       has. Skipped rather than rejecting the whole file, so one bad entry
       cannot cost somebody every other property they made. */
    if (!record || typeof record !== "object") continue;
    const draft = record as PropertyDraft;
    if (typeof draft.slug !== "string" || !draft.slug) continue;
    out[slug] = draft;
  }

  return out;
}

export function loadSavedProperties(): SavedProperties {
  return readJson(STORAGE_KEYS.properties, parseSaved) ?? {};
}

export function saveProperty(record: PropertyDraft): WriteResult {
  if (!record.slug) {
    return { ok: false, reason: "This property has no web address yet." };
  }

  const all = loadSavedProperties();
  return writeJson(STORAGE_KEYS.properties, { ...all, [record.slug]: record });
}

export function deleteSavedProperty(slug: string): WriteResult {
  const all = loadSavedProperties();
  delete all[slug];
  return writeJson(STORAGE_KEYS.properties, all);
}

/* ── merging with the bundled samples ────────────────────── */

/**
 * Fills in the fields a bundled record always has but a new one may not.
 *
 * A property created in the CMS has no `imageKey`, no `id` and no `imageAlt`,
 * because nothing has asked for them. The renderers expect a whole record, so
 * the gaps are filled here rather than by making every consumer defensive.
 */
function asRecord(draft: PropertyDraft): PropertyRecord {
  return {
    id: draft.id ?? `local-${draft.slug}`,
    slug: draft.slug ?? "",
    title: draft.title ?? "Untitled property",
    type: draft.type ?? "",
    location: draft.location ?? "",
    imageKey: draft.imageKey ?? "",
    imageAlt: draft.imageAlt ?? "",
    bedrooms: draft.bedrooms ?? 0,
    bathrooms: draft.bathrooms ?? 0,
    area: draft.area ?? 0,
    rent: draft.rent ?? 0,
    ...draft,
  } as PropertyRecord;
}

/**
 * The catalogue the CMS should show: the samples, plus anything saved here.
 *
 * A saved record with an existing slug REPLACES the sample rather than
 * appearing beside it — editing Rosewood House should give you one Rosewood
 * House. Anything new is appended, newest last, so the list does not reorder
 * itself under the user between visits.
 */
export function mergeProperties(
  samples: PropertyRecord[],
  saved: SavedProperties = loadSavedProperties()
): PropertyRecord[] {
  const overrides = new Map(
    Object.values(saved).map((draft) => [draft.slug as string, asRecord(draft)])
  );

  const merged = samples.map((sample) => overrides.get(sample.slug) ?? sample);

  const known = new Set(samples.map((sample) => sample.slug));
  const added = Object.values(saved)
    .filter((draft) => draft.slug && !known.has(draft.slug))
    .map(asRecord);

  return [...merged, ...added];
}

/**
 * The photograph a resolved property should actually show.
 *
 * A bundled record names a key in the image map. A CMS-made one carries its
 * own `images`, and its featured photograph is already a URL — so the map has
 * nothing to offer and the record answers for itself. Without this a property
 * created in the demo shows the "no photo yet" placeholder even though the
 * editor chose a picture.
 */
export function withOwnImage(property: Property): Property {
  if (property.image) return property;

  const featured = featuredImage(property);
  if (!featured?.src) return property;

  return { ...property, image: featured.src, imageSrcSet: featured.srcSet };
}

/* ── the open draft ──────────────────────────────────────── */

/**
 * Which draft this is.
 *
 * "new" is a single stable key on purpose: refreshing the Add New Property
 * wizard has to come back to the SAME half-finished property, not start a
 * thirteenth one. Editing keys by slug, so two properties can be part-edited
 * without colliding.
 */
export type DraftKey = string;

export const newDraftKey = (): DraftKey => "new";
export const editDraftKey = (slug: string): DraftKey => `edit:${slug}`;

type DraftStore = Record<DraftKey, PropertyDraft>;

function parseDrafts(value: unknown): DraftStore | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;

  const out: DraftStore = {};
  for (const [key, draft] of Object.entries(value as Record<string, unknown>)) {
    if (draft && typeof draft === "object") out[key] = draft as PropertyDraft;
  }
  return out;
}

const loadDrafts = (): DraftStore =>
  readJson(STORAGE_KEYS.propertyDraft, parseDrafts) ?? {};

export function loadDraft(key: DraftKey): PropertyDraft | null {
  return loadDrafts()[key] ?? null;
}

export function saveDraft(key: DraftKey, draft: PropertyDraft): WriteResult {
  return writeJson(STORAGE_KEYS.propertyDraft, { ...loadDrafts(), [key]: draft });
}

/** Called once the property is really saved, so nothing stale shadows it. */
export function clearDraft(key: DraftKey): WriteResult {
  const drafts = loadDrafts();
  delete drafts[key];
  return writeJson(STORAGE_KEYS.propertyDraft, drafts);
}
