// The image library, on Supabase Storage.
//
// Implements the SAME ImageApiAdapter the GitHub/Cloudflare version does, so
// the picker, the upload notifications and the property wizard's image step
// are all unchanged.
//
// Two things about the existing pipeline stop being true here, both of them
// improvements rather than compromises:
//
//   The upload IS the upload. The old flow posted an original to a worker,
//   which committed it, which triggered a GitHub Action to convert it to webp,
//   which eventually appeared on a Pages URL — hence the three-stage poller
//   and the "Processing image…" toast. Storage returns a live public URL the
//   moment the PUT completes, so the poller finds the final image on its first
//   check and finishes. Nothing to remove: it just resolves immediately.
//
//   Nothing is converted. The file is stored as uploaded. That is the honest
//   trade for having this working today — a 6MB phone photograph stays 6MB,
//   where the old pipeline would have produced a webp a fraction of the size.
//   The upload limit in toggles/gh-image--upload-limits.ts is what keeps that
//   from hurting; if the client starts uploading full-resolution photography,
//   a Storage image-transform or a resize before upload is the fix.

import { SUPABASE_ANON_KEY } from "../../config/supabase--anon-key.ts";
import { SUPABASE_URL } from "../../config/supabase--url.ts";
import { STATIC_IMAGES } from "../../config/profile--static-images.ts";
import { accessToken, supabaseRequest } from "./client.ts";
import type {
  ImageApiAdapter,
  ImageChange,
  ImageRecord,
  UploadResult,
} from "../gh-image/imageApi";

/** Created by supabase/schema.sql, public-read and authenticated-write. */
export const BUCKET = "images";

const TABLE = "/rest/v1/cms_images";

type ImageRow = {
  id: string;
  path: string;
  name: string;
  meta: Record<string, unknown> | null;
};

/** Where a stored object is readable from, for anybody, signed in or not. */
export const publicUrl = (objectPath: string): string =>
  `${SUPABASE_URL}/storage/v1/object/public/${BUCKET}/${objectPath}`;

/**
 * A filename safe to put in a URL and in an object key.
 *
 * Spaces and apostrophes in "Nate's front door.JPG" are the everyday case, not
 * the exotic one — a property manager uploads what their phone named the file.
 */
function safeName(name: string): string {
  return (
    name
      .replace(/[^\w.\-]+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "") || "image"
  );
}

export const supabaseImageApi: ImageApiAdapter = {
  async fetchFiles(): Promise<ImageRecord[]> {
    const result = await supabaseRequest<ImageRow[]>(
      `${TABLE}?select=*&order=created_at.desc`,
      /* Public: the website renders these photographs for visitors. */
      { method: "GET", authenticated: false }
    );

    const rows = result.ok && Array.isArray(result.data) ? result.data : [];

    const stored: ImageRecord[] = rows.map((row) => ({
      id: row.id,
      path: row.path,
      name: row.name,
      isStatic: false,
      meta: row.meta ?? {},
    }));

    /* The bundled photographs stay in the list. They are part of the site and
       are not in Storage, so they are appended rather than replaced. */
    return [...stored, ...STATIC_IMAGES];
  },

  async uploadImage(
    file: File,
    onProgress: (msg: string) => void
  ): Promise<UploadResult> {
    onProgress(`Uploading ${file.name}…`);

    const token = await accessToken();
    if (!token) {
      throw new Error("You are signed out. Sign in again to upload images.");
    }

    const now = Date.now();
    const storedName = `${now}-${safeName(file.name)}`;
    const objectPath = `library/${storedName}`;

    let res: Response;

    try {
      res = await fetch(
        `${SUPABASE_URL}/storage/v1/object/${BUCKET}/${objectPath}`,
        {
          method: "POST",
          headers: {
            apikey: SUPABASE_ANON_KEY,
            Authorization: `Bearer ${token}`,
            /* The browser's own idea of the type, falling back to something
               valid rather than letting Storage guess from an empty header. */
            "Content-Type": file.type || "application/octet-stream",
            "Cache-Control": "3600",
          },
          body: file,
        }
      );
    } catch {
      throw new Error(
        "Could not reach the image store. Check your connection and try again — nothing was uploaded."
      );
    }

    if (!res.ok) {
      const text = await res.text();
      throw new Error(
        res.status === 404
          ? "The site's image store has not been set up yet, so there is nowhere to upload to."
          : `That image could not be uploaded${text ? `: ${text}` : ` (error ${res.status})`}.`
      );
    }

    const url = publicUrl(objectPath);

    /* The row is what makes the image appear in the library. A stored object
       with no row would be invisible in the CMS while still occupying space,
       so a failed insert is reported rather than swallowed. */
    const row = await supabaseRequest<unknown>(TABLE, {
      method: "POST",
      headers: { Prefer: "return=minimal" },
      body: [
        {
          id: storedName,
          path: url,
          name: storedName,
          object_path: objectPath,
          meta: {},
        },
      ],
    });

    if (!row.ok) throw new Error(row.error.message);

    return {
      /* The one the picker and the poller use. There is no separate converted
         image here, so all three URLs are the same object — stated rather than
         faked with a URL that would 404. */
      webpUrl: url,
      downloadUrl: url,
      pagesUrl: url,
      originalPath: objectPath,
      originalFileName: storedName,
    };
  },

  async applyChanges(changes: ImageChange[]): Promise<void> {
    for (const change of changes) {
      if (change.action === "delete") {
        await supabaseImageApi.deleteImage(change.id);
      } else if (change.action === "rename") {
        await supabaseImageApi.renameImage(change.id, change.value);
      } else {
        await supabaseImageApi.updateMeta(change.id, {
          [change.attribute]: change.value,
        });
      }
    }
  },

  async deleteImage(id: string): Promise<void> {
    /* The object path is read back rather than rebuilt from the id, so an
       image uploaded under an older naming scheme still deletes. */
    const lookup = await supabaseRequest<{ object_path: string }[]>(
      `${TABLE}?id=eq.${encodeURIComponent(id)}&select=object_path`
    );

    if (!lookup.ok) throw new Error(lookup.error.message);

    const objectPath = lookup.data?.[0]?.object_path;

    const removed = await supabaseRequest<unknown>(
      `${TABLE}?id=eq.${encodeURIComponent(id)}`,
      { method: "DELETE", headers: { Prefer: "return=minimal" } }
    );

    if (!removed.ok) throw new Error(removed.error.message);

    /* The row goes first, because that is what the CMS lists. If the object
       delete then fails the image is gone from the library and the file is
       orphaned in Storage — which costs a little space and shows nobody a
       broken picture. The other order would leave a listed image with no
       file behind it. */
    if (objectPath) {
      const token = await accessToken();

      try {
        await fetch(`${SUPABASE_URL}/storage/v1/object/${BUCKET}/${objectPath}`, {
          method: "DELETE",
          headers: {
            apikey: SUPABASE_ANON_KEY,
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
          },
        });
      } catch {
        /* Orphaned file, as described above. Not worth failing the delete the
           user asked for and already saw succeed. */
      }
    }
  },

  async renameImage(id: string, newName: string): Promise<void> {
    /* The display name only. The stored object keeps its key, so every
       property already pointing at that URL keeps its photograph — renaming a
       picture in the library must not blank it on the website. */
    const result = await supabaseRequest<unknown>(
      `${TABLE}?id=eq.${encodeURIComponent(id)}`,
      {
        method: "PATCH",
        headers: { Prefer: "return=minimal" },
        body: { name: newName },
      }
    );

    if (!result.ok) throw new Error(result.error.message);
  },

  async updateMeta(id: string, meta: Record<string, unknown>): Promise<void> {
    /* Merged with what is stored, so setting alt text does not wipe a caption
       somebody set last week. */
    const current = await supabaseRequest<{ meta: Record<string, unknown> }[]>(
      `${TABLE}?id=eq.${encodeURIComponent(id)}&select=meta`
    );

    if (!current.ok) throw new Error(current.error.message);

    const merged = { ...(current.data?.[0]?.meta ?? {}), ...meta };

    const result = await supabaseRequest<unknown>(
      `${TABLE}?id=eq.${encodeURIComponent(id)}`,
      {
        method: "PATCH",
        headers: { Prefer: "return=minimal" },
        body: { meta: merged },
      }
    );

    if (!result.ok) throw new Error(result.error.message);
  },
};
