import type { CmsPlugin, CmsPluginSlot, CmsPluginView } from "./plugin-types";

const context = (require as any).context(
  "../../",
  true,
  /^\.\/[^/]+\/plugin\.(ts|tsx|js|jsx)$/
);

function discoverPlugins(): CmsPlugin[] {
  const plugins = context.keys().flatMap((key: string) => {
    const loaded = context(key) as { default?: CmsPlugin } | CmsPlugin;
    const plugin : any =
      loaded && typeof loaded === "object" && "default" in loaded
        ? loaded.default
        : loaded;

    return plugin && plugin.id ? [plugin] : [];
  });

  const ids = new Set<string>();

  for (const plugin of plugins) {
    if (ids.has(plugin.id)) {
      throw new Error(`[OpenCMS] Duplicate plugin id: ${plugin.id}`);
    }
    ids.add(plugin.id);
  }

  return plugins;
}

export const cmsPlugins = discoverPlugins();

export const cmsPluginViews: CmsPluginView[] = cmsPlugins
  .flatMap((plugin) => plugin.views || [])
  .sort((a, b) => (a.order || 0) - (b.order || 0));

export function getCmsSlot(slot: string): CmsPluginSlot[] {
  return cmsPlugins
    .flatMap((plugin) => plugin.slots?.[slot] || [])
    .sort((a, b) => (a.order || 0) - (b.order || 0));
}
