import React from "react";

import type { ApplicationQuestion } from "./types";

export type ApplicationMiniatureProps = {
  questions: ApplicationQuestion[];
  /** How many questions to draw before summarising the rest. */
  limit?: number;
};

/**
 * The small picture of an application on its card.
 *
 * Drawn from the application's own questions — their real labels, in their real
 * order, with a control shaped like the type each one actually is. That is the
 * point Nate made about the reference screenshots: an editor recognises their
 * application by seeing the top of it, not by reading a name in a list.
 *
 * It is not the GForm renderer. GForm builds live inputs with state, names and
 * validation, and a page of twelve cards would mean twelve live forms competing
 * for the same field names. This draws inert shapes instead — no inputs, no
 * names, nothing focusable. The real renderer is used for the real preview,
 * which is a different job on a different screen.
 */
export default function ApplicationMiniature({
  questions,
  limit = 4,
}: ApplicationMiniatureProps) {
  const shown = questions.slice(0, limit);
  const remaining = questions.length - shown.length;

  if (shown.length === 0) {
    return (
      <div className="kr-apply-cms__mini">
        <p className="kr-apply-cms__mini-more" style={{ margin: 0 }}>
          No questions yet.
        </p>
      </div>
    );
  }

  return (
    <div className="kr-apply-cms__mini" aria-hidden="true">
      {shown.map((question) => {
        const type = String(question.type ?? "text");
        const isChoice = type === "radio" || type === "checkbox";
        const options = (question.options ?? []).slice(0, 2);

        return (
          <div className="kr-apply-cms__mini-field" key={question.id}>
            <span className="kr-apply-cms__mini-label">
              {question.label ?? question.name}
            </span>

            {isChoice && options.length > 0 ? (
              <span className="kr-apply-cms__mini-choices">
                {options.map((option) => (
                  <span className="kr-apply-cms__mini-choice" key={option.value}>
                    <span
                      className={`kr-apply-cms__mini-dot kr-apply-cms__mini-dot--${
                        type === "radio" ? "round" : "square"
                      }`}
                    />
                    {option.label}
                  </span>
                ))}
              </span>
            ) : (
              <span className="kr-apply-cms__mini-input" style={{ display: "block" }} />
            )}
          </div>
        );
      })}

      {remaining > 0 ? (
        <p className="kr-apply-cms__mini-more">
          + {remaining} more {remaining === 1 ? "question" : "questions"}
        </p>
      ) : null}
    </div>
  );
}
