import React, { useEffect, useRef, useState } from "react";

import type { ArrowDirection } from "./types";

/** How far to rotate the right-pointing artwork to face each way. */
const ROTATION: Record<ArrowDirection, number> = {
  right: 0,
  down: 90,
  left: 180,
  up: 270,
};

export type TutorialArrowProps = {
  direction: ArrowDirection;
  size?: number;
  /** Draws the arrow without motion. */
  still?: boolean;
};

/**
 * The walkthrough's pointer.
 *
 * ── why this is SVG and not Lottie ───────────────────────────────────────
 * Nate asked for a Lottie arrow and pointed at a specific LottieFiles asset.
 * That file cannot be downloaded here — the page answers 403 to anything but a
 * browser — so the choice was between hand-writing Lottie JSON I had no way to
 * run, or drawing the arrow directly. I tried the first and shipped something I
 * could not verify, which was the wrong call: an animation format is a poor
 * thing to guess at, and a walkthrough whose pointer might silently fail to
 * render is worse than one with no animation at all.
 *
 * So the arrow is drawn and animated here, where every part of it is legible
 * and certain to work. It costs nothing at runtime, scales cleanly, takes its
 * colour from the CMS, and rotates to all four directions from one drawing.
 *
 * If Nate's actual Lottie file turns up, swapping it in is a contained change:
 * this component owns the whole arrow, so it becomes a lottie-web mount and
 * nothing outside it moves. That is deliberately not stubbed out here — an
 * unused code path pointing at a file that does not exist is just a comment
 * that will go stale.
 *
 * The motion is deliberately quiet — the shaft draws on, the head arrives, the
 * whole thing drifts toward the target and settles. It is a pointer, not a
 * decoration competing with the control it is pointing at.
 */
export default function TutorialArrow({
  direction,
  size = 96,
  still = false,
}: TutorialArrowProps) {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const query = window.matchMedia?.("(prefers-reduced-motion: reduce)");
    if (!query) return;

    setReduced(query.matches);
    const onChange = (event: MediaQueryListEvent) => setReduced(event.matches);
    query.addEventListener?.("change", onChange);
    return () => query.removeEventListener?.("change", onChange);
  }, []);

  const motionless = still || reduced;

  return (
    <div
      className={`kr-tut__arrow${motionless ? " kr-tut__arrow--still" : ""}`}
      style={{
        width: size,
        height: size,
        transform: `rotate(${ROTATION[direction]}deg)`,
      }}
      aria-hidden="true"
    >
      <svg viewBox="0 0 120 120" width={size} height={size}>
        {/* A soft halo so the arrow reads against both the dark overlay and
            whatever the spotlit control happens to be sitting on. */}
        <defs>
          <filter id="kr-tut-glow" x="-40%" y="-40%" width="180%" height="180%">
            <feDropShadow
              dx="0"
              dy="1"
              stdDeviation="2.5"
              floodColor="#000"
              floodOpacity="0.45"
            />
          </filter>
        </defs>

        <g
          className="kr-tut__arrow-group"
          fill="none"
          stroke="#C89F5B"
          strokeWidth={9}
          strokeLinecap="round"
          strokeLinejoin="round"
          filter="url(#kr-tut-glow)"
        >
          {/* Slightly bowed rather than ruler-straight: it reads as a gesture
              toward something instead of a diagram. */}
          <path className="kr-tut__arrow-shaft" d="M18 60 Q 56 50 92 60" />
          <path className="kr-tut__arrow-head" d="M76 43 L99 60 L76 77" />
        </g>
      </svg>
    </div>
  );
}
