import React, { useCallback, useEffect, useState } from "react";
import { Link, navigate } from "gatsby";
import {
  FaBars,
  FaCheckCircle,
  FaCog,
  FaHome,
  FaSignOutAlt,
} from "react-icons/fa";

import { useAuth } from "../../../config/opencms--useAuth";

import theme from "../../../config/opencms--theme";

import { BRANDING } from "../../../config/opencms--branding";
import { cmsPluginViews, getCmsSlot } from "../../../modules/opencms/core/plugins";


export type CmsLayoutProps = {
  title: string;
  pathname: string;
  children: React.ReactNode;
};

const normalizePath = (value: string) => {
  const clean = (value || "/dashboard").replace(/\/+$/, "");
  return clean || "/";
};

export default function CmsLayout({ title, pathname, children }: CmsLayoutProps) {
  const currentPath = normalizePath(pathname);
  const { loading, authenticated } = useAuth();

  /* The sidebar is a drawer below 900px. Kept in state rather than CSS because
     it also locks scrolling and closes on Escape and on navigation. */
  const [navOpen, setNavOpen] = useState(false);
  const closeNav = useCallback(() => setNavOpen(false), []);

  useEffect(() => {
    if (!loading && !authenticated) {
      navigate("/login", { replace: true });
    }
  }, [loading, authenticated]);

  /* Locked while the drawer is open, restored on close. Without this the page
     behind scrolls under the drawer on a phone, which reads as broken. */
  useEffect(() => {
    if (!navOpen) return;

    const previous = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setNavOpen(false);
    };
    document.addEventListener("keydown", onKeyDown);

    return () => {
      document.body.style.overflow = previous;
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [navOpen]);

  /* A wider window means the drawer is irrelevant; leaving it open would hold
     the scroll lock on a layout that no longer has a drawer. */
  useEffect(() => {
    const query = window.matchMedia("(min-width: 900px)");
    const onChange = () => {
      if (query.matches) setNavOpen(false);
    };
    query.addEventListener?.("change", onChange);
    return () => query.removeEventListener?.("change", onChange);
  }, []);

  if (loading || !authenticated) {
    return (
      <div style={s.loadingPage}>
        <span className="opencms-dashboard-spinner" style={s.spinner} />
        <style>{css}</style>
      </div>
    );
  }

  const pluginNav = cmsPluginViews.filter((view) => view.nav !== false);
  const hasSettings = getCmsSlot("settings").length > 0;

  const navItems = [
    {
      id: "dashboard",
      label: "Dashboard",
      to: "/dashboard",
      icon: FaHome,
      order: -1000,
    },
    ...pluginNav.map((view) => ({
      id: view.id,
      label: view.label,
      to: (() => {
        const path = view.path.replace(/^\/+|\/+$/g, "");
        return path === "dashboard" || path.startsWith("dashboard/")
          ? `/${path}`
          : `/dashboard/${path}`;
      })(),
      icon: view.icon,
      order: view.order || 0,
    })),
    ...(hasSettings
      ? [{ id: "settings", label: "Settings", to: "/dashboard/settings", icon: FaCog, order: 1000 }]
      : []),
  ].sort((a, b) => a.order - b.order);

  /* Exactly one nav item is highlighted: the longest one whose path the current
     page sits under.

     A plain prefix test lit two at once — "/dashboard" is a prefix of
     "/dashboard/applications", so Dashboard stayed dark alongside whichever
     view you were actually in. Longest match means a parent yields to its
     child, the same rule the router uses to decide which view owns a route. */
  const activeTarget = navItems.reduce((best, item) => {
    const target = normalizePath(item.to);
    const matches =
      currentPath === target || currentPath.startsWith(`${target}/`);
    return matches && target.length > best.length ? target : best;
  }, "");

  return (
    <div style={s.page} className={navOpen ? "opencms--nav-open" : undefined}>
      <style>{css}</style>

      {/* Only rendered as a backdrop below 900px; CSS hides it above. */}
      <button
        type="button"
        className="opencms-scrim"
        aria-label="Close menu"
        tabIndex={navOpen ? 0 : -1}
        onClick={closeNav}
      />

      <aside style={s.sidebar} className="opencms-sidebar">
        <div>
          <div style={s.brand}>
            {BRANDING.logo ? (
              <img src={BRANDING.logo} alt={BRANDING.name} style={s.logo} />
            ) : (
              <div style={s.logoFallback}>{BRANDING.shortName || "CMS"}</div>
            )}

            <div style={s.brandText}>
              <div style={s.brandName}>{BRANDING.name}</div>
              <div style={s.brandSub}>{BRANDING.tagline}</div>
            </div>
          </div>

          <nav style={s.nav}>
            {navItems.map(({ id, label, to, icon: Icon }) => {
              const active = normalizePath(to) === activeTarget;
              return (
                <Link
                  key={id}
                  to={to}
                  style={active ? s.navActive : s.navItem}
                  aria-current={active ? "page" : undefined}
                  onClick={closeNav}
                >
                  {Icon ? <Icon size={15} /> : null}
                  <span>{label}</span>
                </Link>
              );
            })}
          </nav>
        </div>

        <Link to="/logout" style={s.logout}>
          <FaSignOutAlt size={14} />
          <span>Logout</span>
        </Link>
      </aside>

      <main style={s.main}>
        <header style={s.header} className="opencms-header">
          <div style={s.headerLeft}>
            {/* Was decoration: it had no handler at all, so on a phone the
                sidebar simply squeezed the content and there was no way to get
                it out of the way. */}
            <button
              type="button"
              className="opencms-menu-button"
              style={s.menuButton}
              aria-label={navOpen ? "Close menu" : "Open menu"}
              aria-expanded={navOpen}
              onClick={() => setNavOpen((open) => !open)}
            >
              <FaBars size={15} />
            </button>

            <div>
              <div style={s.kicker}>CONTENT MANAGEMENT SYSTEM</div>
              <h1 style={s.title} className="opencms-title">{title}</h1>
            </div>
          </div>

          <div style={s.authBadge} className="opencms-auth-badge">
            <FaCheckCircle size={13} />
            Authenticated
          </div>
        </header>

        <section style={s.content} className="opencms-content">{children}</section>
      </main>
    </div>
  );
}

const s: Record<string, React.CSSProperties> = {
  page: { minHeight: "100vh", display: "flex", background: theme.background, color: theme.text, fontFamily: "'Inter', 'Segoe UI', system-ui, sans-serif" },
  loadingPage: { minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: theme.background },
  spinner: { width: 28, height: 28, borderRadius: "50%", border: `3px solid ${theme.border}`, borderTopColor: theme.primary },
  sidebar: { width: theme.sidebarWidth || 240, minHeight: "100vh", boxSizing: "border-box", background: theme.sidebar, borderRight: `1px solid ${theme.border}`, padding: "22px 16px", display: "flex", flexDirection: "column", justifyContent: "space-between", flexShrink: 0 },
  brand: { display: "flex", alignItems: "center", gap: 11, padding: "2px 8px 22px", borderBottom: `1px solid ${theme.border}` },
  logo: { width: 38, height: 38, objectFit: "contain", borderRadius: 8 },
  logoFallback: { width: 38, height: 38, borderRadius: 8, background: theme.primary, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 800, flexShrink: 0 },
  brandText: { minWidth: 0 },
  brandName: { fontSize: 13, fontWeight: 800, lineHeight: 1.2, color: theme.text, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" },
  brandSub: { marginTop: 3, fontSize: 10, color: theme.textMuted, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" },
  nav: { paddingTop: 18, display: "flex", flexDirection: "column", gap: 5 },
  navItem: { display: "flex", alignItems: "center", gap: 10, padding: "11px 12px", borderRadius: 9, textDecoration: "none", color: theme.textMuted, fontSize: 13, fontWeight: 700 },
  navActive: { display: "flex", alignItems: "center", gap: 10, padding: "11px 12px", borderRadius: 9, textDecoration: "none", background: theme.primary, color: "#fff", fontSize: 13, fontWeight: 700 },
  logout: { display: "flex", alignItems: "center", gap: 10, padding: "11px 12px", borderRadius: 9, textDecoration: "none", color: theme.danger, fontSize: 13, fontWeight: 700 },
  main: { minWidth: 0, flex: 1 },
  header: { minHeight: 84, boxSizing: "border-box", padding: "16px 30px", background: "#fff", borderBottom: `1px solid ${theme.border}`, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 20 },
  headerLeft: { display: "flex", alignItems: "center", gap: 14 },
  menuButton: { width: 34, height: 34, border: `1px solid ${theme.border}`, borderRadius: 8, background: "#fff", color: theme.textMuted, display: "flex", alignItems: "center", justifyContent: "center" },
  kicker: { color: theme.primary, fontSize: 9, fontWeight: 800, letterSpacing: "1.3px" },
  title: { margin: "3px 0 0", color: theme.text, fontSize: 23, lineHeight: 1.15, fontWeight: 800 },
  authBadge: { display: "flex", alignItems: "center", gap: 7, border: `1px solid ${theme.border}`, borderRadius: 999, padding: "7px 10px", color: "#15803d", background: "#f0fdf4", fontSize: 11, fontWeight: 700 },
  content: { padding: theme.contentPadding || 36 },
};

const css = `
@keyframes opencmsDashboardSpin { to { transform: rotate(360deg); } }
.opencms-dashboard-spinner { animation: opencmsDashboardSpin .7s linear infinite; }

/* Above the breakpoint the sidebar is a column and the hamburger is pointless. */
.opencms-menu-button { display: none !important; }
.opencms-scrim { display: none; }

/* ── below 900px ──────────────────────────────────────────
   The sidebar was simply narrowed to 190px and left in place, which on a 320px
   phone left 130px for the content - unusable. It becomes a drawer instead:
   off-canvas by default, over the content when opened, and the hamburger in
   the header - which until now had no click handler at all - opens it. */
@media (max-width: 899px) {
  .opencms-menu-button {
    display: inline-flex !important;
    /* A comfortable touch target rather than the 34px it was. */
    width: 42px !important;
    height: 42px !important;
    flex-shrink: 0;
  }

  .opencms-sidebar {
    position: fixed !important;
    top: 0;
    left: 0;
    bottom: 0;
    z-index: 60;
    width: min(280px, 84vw) !important;
    /* dvh, not vh: mobile browser chrome makes vh taller than the visible
       area, which would push Logout below the fold. */
    min-height: 100dvh !important;
    transform: translateX(-100%);
    transition: transform 240ms cubic-bezier(.22, 1, .36, 1);
    box-shadow: 0 0 40px rgba(15, 23, 42, .18);
    overflow-y: auto;
    overscroll-behavior: contain;
    padding-left: max(16px, env(safe-area-inset-left));
    padding-bottom: max(22px, env(safe-area-inset-bottom));
  }
  .opencms--nav-open .opencms-sidebar { transform: translateX(0); }

  .opencms-scrim {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 55;
    border: 0;
    padding: 0;
    background: rgba(15, 23, 42, .45);
    opacity: 0;
    pointer-events: none;
    transition: opacity 240ms ease;
  }
  .opencms--nav-open .opencms-scrim { opacity: 1; pointer-events: auto; }

  /* The nav rows become proper touch targets. */
  .opencms-sidebar a { min-height: 46px; }

  .opencms-header { padding: 12px 16px !important; min-height: 0 !important; }
  .opencms-title { font-size: 19px !important; }
  .opencms-content { padding: 20px 16px !important; }

  /* The badge is reassurance, not information, and it is the first thing that
     should give up room on a narrow header. */
  .opencms-auth-badge { display: none !important; }
}

@media (max-width: 380px) {
  .opencms-header { padding: 10px 12px !important; }
  .opencms-content { padding: 16px 12px !important; }
  .opencms-title { font-size: 17px !important; }
}

@media (prefers-reduced-motion: reduce) {
  .opencms-sidebar,
  .opencms-scrim { transition: none; }
}
`;
