
import { IMAGE_SYNC_QUEUE } from "../../config/gh-image--image-sync-worker-key";

const STORAGE_KEY = IMAGE_SYNC_QUEUE;
const STALE_THRESHOLD_MS = 10 * 60 * 1000;
const UPLOAD_STALE_MS = 5 * 60 * 1000;

export type UploadStage = "thumbnail" | "raw" | "final";

// ── Types ─────────────────────────────────────────
type QueueItem = {
  time: number;
  action: "delete" | "upload";
  fileName?: string;
  originalFileName?: string;
  webpUrl?: string;
  step?: number;
  thumb?: string;

  // Persisted three-stage display state.
  stage?: UploadStage;
  currentUrl?: string;
};

type Queue = Record<string, QueueItem>;

export type SyncQueueState = {
  id: string;
  action: string;
  ageMs: number;
  status: "uploading" | "success" | "stale";
};

export type UploadEntry = {
  id: string;
  time: number;
  fileName: string;
  originalFileName: string;
  webpUrl: string;
  step: number;
  thumb?: string;
  stage: UploadStage;
  currentUrl?: string;
};

export type SyncQueueOptions = {
  addToErrorLog?: (error: any) => void;
};

// ── Storage ───────────────────────────────────────
const readQueue = (): Queue => {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "{}");
  } catch {
    return {};
  }
};

const queueListeners = new Set<() => void>();

const notifyQueueListeners = (): void => {
  for (const listener of queueListeners) {
    listener();
  }
};

const subscribeQueue = (
  listener: () => void
): (() => void) => {
  queueListeners.add(listener);

  return () => {
    queueListeners.delete(listener);
  };
};

const writeQueue = (data: Queue): void => {
  const next = JSON.stringify(data);
  const current =
    localStorage.getItem(STORAGE_KEY);

  // Nothing actually changed.
  // Do not trigger subscribers again.
  if (current === next) {
    return;
  }

  localStorage.setItem(
    STORAGE_KEY,
    next
  );

  notifyQueueListeners();
};

// ── Hook ──────────────────────────────────────────
export const useImageSyncQueue = (options: SyncQueueOptions = {}) => {
  const { addToErrorLog = console.error } = options;

  // ── Upload tracking ─────────────────────────────
  const queueUpload = (
    id: string,
    meta?: {
      fileName?: string;
      originalFileName?: string;
      webpUrl?: string;
      thumb?: string;
    }
  ): void => {
    const data = readQueue();

    data[id] = {
      time: Date.now(),
      action: "upload",
      step: 0,
      ...meta,
      stage: "thumbnail",
      currentUrl: meta?.thumb,
    };

    writeQueue(data);
  };

  const updateStep = (id: string, step: number): void => {
    const data = readQueue();

    if (data[id]) {
      data[id] = {
        ...data[id],
        step,
      };

      writeQueue(data);
    }
  };

  const setUploadStage = (
    id: string,
    stage: UploadStage,
    currentUrl: string
  ): void => {
    const data = readQueue();

    if (data[id]?.action !== "upload") {
      return;
    }

    data[id] = {
      ...data[id],
      stage,
      currentUrl,
    };

    if (stage !== "thumbnail") {
      delete data[id].thumb;
    }

    writeQueue(data);
  };

  // Compatibility helper. Stage transitions should use setUploadStage().
  const clearThumb = (id: string): void => {
    const data = readQueue();

    if (data[id]?.action === "upload") {
      delete data[id].thumb;
      writeQueue(data);
    }
  };

  // Permanent Pages image is available. Upload tracking is finished.
  const markSuccess = (id: string): void => {
    const data = readQueue();

    delete data[id];

    writeQueue(data);
  };

  const getUploads = (): UploadEntry[] => {
    const data = readQueue();
    const now = Date.now();
    const cleaned: Queue = {};
    let changed = false;

    for (const [id, item] of Object.entries(data)) {
      if (
        item.action === "upload" &&
        now - item.time > UPLOAD_STALE_MS
      ) {
        addToErrorLog({
          id,
          ...item,
          ageMs: now - item.time,
          reason: "upload_stale_5min",
        });

        changed = true;
        continue;
      }

      cleaned[id] = item;
    }

    if (changed) {
      writeQueue(cleaned);
    }

    return Object.entries(cleaned)
      .filter(
        ([, item]) =>
          item.action === "upload" &&
          !!item.webpUrl
      )
      .map(([id, item]) => ({
        id,
        time: item.time,
        fileName: item.fileName ?? "image",
        originalFileName: item.originalFileName ?? item.fileName ?? "image",
        webpUrl: item.webpUrl!,
        step: item.step ?? 0,
        thumb: item.thumb,
        stage:
          item.stage ??
          (item.thumb ? "thumbnail" : "raw"),
        currentUrl:
          item.currentUrl ??
          item.thumb,
      }));
  };

  const isUploading = (): boolean => {
    const data = readQueue();
    const now = Date.now();

    return Object.values(data).some(
      (item) =>
        item.action === "upload" &&
        now - item.time <= UPLOAD_STALE_MS
    );
  };

  // ── Delete tracking ─────────────────────────────
  const queueDelete = (id: string): void => {
    const data = readQueue();

    data[id] = {
      time: Date.now(),
      action: "delete",
    };

    writeQueue(data);
  };

  const clearEntry = (id: string): void => {
    const data = readQueue();

    delete data[id];

    writeQueue(data);
  };

  // ── Reconcile ───────────────────────────────────
  const reconcile = <T extends { id: string }>(
    rows: T[]
  ): {
    filteredRows: T[];
    states: SyncQueueState[];
  } => {
    const queue = readQueue();
    const rowIds = new Set(rows.map((r) => r.id));
    const now = Date.now();
    const updatedQueue: Queue = {};
    const states: SyncQueueState[] = [];

    for (const [id, item] of Object.entries(queue)) {
      const ageMs = now - item.time;
      let status: SyncQueueState["status"] = "uploading";

      if (ageMs > STALE_THRESHOLD_MS) {
        status = "stale";

        addToErrorLog({
          id,
          ...item,
          ageMs,
        });

        states.push({
          id,
          action: item.action,
          ageMs,
          status,
        });

        continue;
      }

      if (item.action === "delete") {
        if (rowIds.has(id)) {
          updatedQueue[id] = item;
        }
      } else if (item.action === "upload") {
        updatedQueue[id] = item;
      }

      states.push({
        id,
        action: item.action,
        ageMs,
        status,
      });
    }

    writeQueue(updatedQueue);

    const filteredRows = rows.filter((row) => {
      const q = updatedQueue[row.id];

      return !q || q.action !== "delete";
    });

    return {
      filteredRows,
      states,
    };
  };

  const debug = (): void => {
    console.log("[ImageSyncQueue RAW]", readQueue());
  };

  return {
    queueUpload,
    updateStep,
    setUploadStage,
    clearThumb,
    markSuccess,
    getUploads,
    isUploading,
    subscribeQueue,

    queueDelete,
    clearEntry,

    reconcile,
    check: reconcile,
    debug,
  };
};
