import React from "react";
import { Link } from "gatsby";
import { LuArrowRight, LuBuilding2 } from "react-icons/lu";

import { dashCard } from "../gh-apply/dashboardCardStyles";
import { properties } from "../../primitives/property/property-data";
import { PROPERTIES_ROUTE } from "./types";

/**
 * The PVST Preview — the Properties card on the CMS dashboard.
 *
 * Same shared card rules as the other previews, so the row reads as one set.
 * Counts come from the records the view lists; nothing here is invented.
 */
export default function PropertiesPreview() {
  const total = properties.length;
  const available = properties.filter((property) =>
    /now/i.test(property.availability ?? "")
  ).length;

  return (
    <div style={dashCard.card}>
      <div style={dashCard.header}>
        <div style={dashCard.headingWrap}>
          <span style={dashCard.icon}>
            <LuBuilding2 size={19} />
          </span>
          <div style={{ minWidth: 0 }}>
            <h2 style={dashCard.title}>Properties</h2>
            <p style={dashCard.subtitle}>Listings shown on your website.</p>
          </div>
        </div>

        <Link to={PROPERTIES_ROUTE} style={dashCard.action}>
          Open
          <LuArrowRight size={14} aria-hidden="true" />
        </Link>
      </div>

      <div style={dashCard.body}>
        <p style={dashCard.figure}>{total}</p>
        <p style={dashCard.meta}>
          {total === 1 ? "listing on the website" : "listings on the website"}
          {available > 0 ? ` · ${available} available now` : ""}
        </p>
      </div>
    </div>
  );
}
