import type { GFormField } from "../gh-leads/GForm";

/** Where the view lives. Kept beside the plugin so route and link cannot drift. */
export const APPLY_VIEW_PATH = "applications";
export const APPLY_ROUTE = `/dashboard/${APPLY_VIEW_PATH}`;

/**
 * A question is a GForm field plus an id.
 *
 * Deliberately built ON the site's existing field type rather than beside it:
 * the public application form is already `GFormField[]`, and GForm already
 * renders it. A second model would mean a second renderer and two things to
 * keep in step. The id exists because reordering and editing need to address a
 * question independently of its position or its name.
 */
export type ApplicationQuestion = GFormField & {
  id: string;
};

/** The five types the CMS offers. Anything else is not selectable in the UI. */
export type QuestionType =
  | "text"
  | "radio"
  | "checkbox"
  | "select"
  | "date";

export type Application = {
  id: string;
  name: string;
  questions: ApplicationQuestion[];
  /** ISO timestamps. */
  createdAt: string;
  updatedAt: string;
  /** Null while live. Set on soft delete; the trash countdown derives from it. */
  deletedAt: string | null;
};

/**
 * The whole stored document — one JSON file.
 *
 * `activeId` lives here rather than as a flag on each application so "exactly
 * one is active" is a property of the data shape and not an invariant several
 * writers have to remember.
 */
export type ApplicationsDocument = {
  version: number;
  activeId: string;
  applications: Application[];
};

