import React, { useEffect, useState } from "react";
import { Link } from "gatsby";
import { FaArrowRight, FaImages } from "react-icons/fa";

import Image from "../../primitives/gh-image/Image";
import theme from "../../config/opencms--theme";
import { ImagesView, ghImageStyles } from "./CmsShell";
import { imageApi } from "./imageApi";
import type { ImageRecord } from "./imageApi";
import { UploadNotifications } from "./UploadNotifications";
import { useImageSyncQueue } from "./useImageSyncQueue";
import { CmsPlugin, CmsViewProps } from "../opencms/core/plugin-types";

function GhImageView(_props: CmsViewProps) {
  return (
    <>
      <style>{ghImageStyles}</style>
      <ImagesView api={imageApi} />
      <UploadNotifications />
    </>
  );
}

function GhImageDashboardSlot() {
  const [recent, setRecent] = useState<ImageRecord[]>([]);

  const {
    reconcile,
    getUploads,
    subscribeQueue,
  } = useImageSyncQueue();

  const sortById = (a: ImageRecord, b: ImageRecord) => {
    const aTime = Number(String(a.id).split("-")[0]);
    const bTime = Number(String(b.id).split("-")[0]);

    if (isNaN(aTime)) return 1;
    if (isNaN(bTime)) return -1;

    return bTime - aTime;
  };

  const loadRecent = async () => {
    const records = await imageApi.fetchFiles();

    // This is intentionally the same reconciliation sequence used by
    // ImagesView.loadImages().
    const { filteredRows } = reconcile(records);
    const existingIds = new Set(
      filteredRows.map((img) => img.id)
    );

    const restoredUploads: ImageRecord[] = getUploads()
      .filter(
        (upload) => !existingIds.has(upload.id)
      )
      .map((upload) => ({
        id: upload.id,
        path:
          upload.currentUrl ||
          upload.thumb ||
          "",
        name: upload.fileName,
        isStatic: false,
        meta: {
          ghImageStage: upload.stage,
        },
      }))
      .filter((upload) => !!upload.path);

    setRecent(
      [...restoredUploads, ...filteredRows]
        .sort(sortById)
        .slice(0, 8)
    );
  };

  useEffect(() => {
    let cancelled = false;

    const refresh = async () => {
      if (cancelled) return;

      try {
        await loadRecent();
      } catch {
        if (!cancelled) {
          setRecent([]);
        }
      }
    };

    refresh();

    const unsubscribe =
      subscribeQueue(refresh);

    return () => {
      cancelled = true;
      unsubscribe();
    };
  }, []);

  const removeFailedImage = (id: string) => {
    setRecent((prev) =>
      prev.filter((img) => img.id !== id)
    );
  };

  return (
    <section style={dashboardStyles.card}>
      <div style={dashboardStyles.header}>
        <div style={dashboardStyles.headingWrap}>
          <div style={dashboardStyles.icon}>
            <FaImages size={18} />
          </div>
          <div>
            <h2 style={dashboardStyles.title}>Images</h2>
            <p style={dashboardStyles.sub}>Manage your project gallery and uploads.</p>
          </div>
        </div>

        <Link to="/dashboard/images" style={dashboardStyles.link}>
          Open Images <FaArrowRight size={11} />
        </Link>
      </div>

      {recent.length > 0 && (
        <div style={dashboardStyles.grid}>
          {recent.map((img) => (
            <Link
              key={img.id}
              to="/dashboard/images"
              title={img.name}
              style={dashboardStyles.thumb}
            >
              <Image
                src={img.path}
                alt={img.name}
                className="gh-image-dashboard-thumb"
                onError={() =>
                  removeFailedImage(img.id)
                }
              />
            </Link>
          ))}
        </div>
      )}

      <style>{`
        .gh-image-dashboard-thumb {
          width: 100%;
          height: 100%;
          object-fit: cover;
          display: block;
        }
      `}</style>
    </section>
  );
}

const plugin: CmsPlugin = {
  id: "gh-image",
  views: [
    {
      id: "gh-image",
      path: "images",
      label: "Images",
      component: GhImageView,
      nav: true,
      order: 100,
      icon: FaImages,
    },
  ],
  slots: {
    dashboard: [
      {
        id: "gh-image-dashboard",
        component: GhImageDashboardSlot,
        order: 100,
      },
    ],
  },
};

export default plugin;

