// @ppm--version--1.0

import React, { useEffect, useRef, useState } from "react";
import { FaCheck, FaEllipsisH, FaEnvelope, FaPhone, FaRegCopy } from "react-icons/fa";
import type { Lead } from "./types";
import { contactSummary, telHref } from "./format";

type Props = { lead: Lead, toggle ?: any };

/**
 * Small circular actions on each row. Every control stops propagation so it
 * never triggers the row click (which will open LeadPopout in a later task).
 */
export default function LeadQuickActions({ lead, toggle }: Props) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    []
  );

  const stop = (event: React.MouseEvent) => {
    event.stopPropagation();
  };

  const handleCopy = async (event: React.MouseEvent) => {
    event.stopPropagation();

    const text = contactSummary(lead);

    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);

      if (timer.current) clearTimeout(timer.current);
      timer.current = setTimeout(() => setCopied(false), 1600);
    } catch {
      // Clipboard blocked (insecure origin or denied permission). Leave the
      // button unchanged rather than claiming a copy that did not happen.
    }
  };

  return (
    <div className="leads-actions" onClick={stop}>
      { toggle?.phone === false ? <></> : 
        <a
          className="leads-action"
          href={telHref(lead.phone)}
          onClick={stop}
          title={`Call ${lead.name} on ${lead.phone}`}
          aria-label={`Call ${lead.name} on ${lead.phone}`}
        >
          <FaPhone size={10} />
        </a>
      }

      { toggle?.email === false ? <></> : 
        <a
          className="leads-action"
          href={`mailto:${lead.email}`}
          onClick={stop}
          title={`Email ${lead.name} at ${lead.email}`}
          aria-label={`Email ${lead.name} at ${lead.email}`}
        >
          <FaEnvelope size={10} />
        </a>
      }

      <button
        type="button"
        className={copied ? "leads-action leads-action--done" : "leads-action"}
        onClick={handleCopy}
        title={copied ? "Contact details copied" : `Copy contact details for ${lead.name}`}
        aria-label={copied ? "Contact details copied" : `Copy contact details for ${lead.name}`}
      >
        {copied ? <FaCheck size={10} /> : <FaRegCopy size={10} />}
      </button>

      { toggle?.submenu === false ? <></> : 
        <button
          type="button"
          className="leads-action"
          onClick={stop}
          title="More options — available in a later update"
          aria-label="More options — available in a later update"
        >
          <FaEllipsisH size={10} />
        </button>
      }
    </div>
  );
}
