// Generated by CMS / PPM template loader
// Styling for the OpenCMS Leads plugin. Swap this module (via
// config/template--leads.ts) to restyle Leads without touching a component.
//
// Layering mirrors the gh-image plugin: a class-based stylesheet string for the
// full view (like `ghImageStyles`) and inline style objects for the dashboard
// card (like `dashboardStyles`), both derived from the shared CMS theme.

import type React from "react";
import theme from "../../config/opencms--theme";

export type LeadsTint = { bg: string; fg: string };

/**
 * Presentation copy. Swappable per customer — a client who calls these
 * "Enquiries" changes this block, not a component.
 *
 * Status names are NOT here: they are the domain vocabulary of the LeadStatus
 * union and live beside it in the plugin's types.ts.
 */
export type LeadsLabels = {
  /** Sidebar/nav entry and page heading for the full view. */
  navLabel: string;

  columns: {
    name: string;
    actions: string;
    phone: string;
    email: string;
    received: string;
    status: string;
  };

  searchPlaceholder: string;
  allStatuses: string;

  loading: string;
  emptyTitle: string;
  emptyText: string;
  noMatchTitle: string;
  noMatchText: string;
  errorTitle: string;
  errorText: string;

  previewTitle: string;
  previewSubtitle: string;
  previewLink: string;
  previewLoading: string;
  previewEmpty: string;
  previewError: string;

  /** Detail popout. */
  popoutMessage: string;
  popoutNoMessage: string;
  popoutDetails: string;
  popoutClose: string;
  popoutFields: {
    name: string;
    email: string;
    phone: string;
    form: string;
    site: string;
    tag: string;
    submissionId: string;
    received: string;
  };
};

export type LeadsTemplate = {
  /** Class-based stylesheet for LeadsView. Injected via <style>. */
  css: string;
  /** Inline styles for the dashboard preview card. */
  preview: Record<string, React.CSSProperties>;
  /**
   * Inline styles for the initials avatar. Inline rather than class-based
   * because LeadAvatar also renders inside the dashboard preview, where the
   * `css` stylesheet above is not mounted.
   */
  avatar: Record<"base" | "lg", React.CSSProperties>;
  /** Avatar tints, picked deterministically from the lead name. */
  avatarPalette: LeadsTint[];
  /** Status badge colours, keyed by Lead["status"]. */
  status: Record<string, LeadsTint & { border: string }>;
  /** How many leads the dashboard preview lists. */
  previewRows: number;
  /** All user-facing copy. */
  labels: LeadsLabels;
};

const labels: LeadsLabels = {
  navLabel: "Leads",

  columns: {
    name: "Lead Name",
    actions: "Quick Actions",
    phone: "Phone",
    email: "Email",
    received: "Received",
    status: "Status",
  },

  searchPlaceholder: "Search name, email or phone",
  allStatuses: "All statuses",

  loading: "Loading leads...",
  emptyTitle: "No leads yet.",
  emptyText: "Leads submitted through your website will appear here.",
  noMatchTitle: "No matching leads",
  noMatchText: "Try a different search term or clear the status filter.",
  errorTitle: "Unable to load leads.",
  errorText: "Please try again shortly.",

  previewTitle: "Recent Leads",
  previewSubtitle: "Enquiries submitted through your website.",
  previewLink: "View All",
  previewLoading: "Loading leads...",
  previewEmpty: "No leads yet.",
  previewError: "Unable to load leads.",

  popoutMessage: "Lead Message",
  popoutNoMessage: "This submission did not include a message.",
  popoutDetails: "Lead Details",
  popoutClose: "Close lead details",
  popoutFields: {
    name: "Name",
    email: "Email",
    phone: "Phone",
    form: "Form",
    site: "Site",
    tag: "Tag",
    submissionId: "Submission ID",
    received: "Received",
  },
};

/* ── status badges ──────────────────────────────────────────────
   Deliberately restrained. "qualified" reuses the exact green of the
   "Authenticated" badge in CmsLayout so the two read as one system. */
const status: LeadsTemplate["status"] = {
  new:       { bg: `${theme.primary}14`, fg: theme.primary, border: `${theme.primary}33` },
  contacted: { bg: "#fffbeb",            fg: "#b45309",     border: "#fde68a" },
  qualified: { bg: "#f0fdf4",            fg: "#15803d",     border: "#bbf7d0" },
};

/* ── avatar tints ───────────────────────────────────────────────
   Low-saturation only: enough variation to scan a column of rows,
   not enough to turn the table into a colour chart. */
const avatarPalette: LeadsTint[] = [
  { bg: "#eff6ff", fg: "#1d4ed8" },
  { bg: "#f1f5f9", fg: "#475569" },
  { bg: "#f0fdfa", fg: "#0f766e" },
  { bg: "#faf5ff", fg: "#7e22ce" },
  { bg: "#fff7ed", fg: "#c2410c" },
  { bg: "#f7fee7", fg: "#4d7c0f" },
];

const css = `
.leads-card {
  border: 1px solid ${theme.border};
  border-radius: ${theme.cardRadius || 14}px;
  background: #fff;
  box-shadow: 0 1px 3px rgba(15,23,42,.04);
  overflow: hidden;
}

/* ── toolbar ─────────────────────────────────────────── */
.leads-toolbar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 14px; flex-wrap: wrap;
  padding: 16px 18px;
  border-bottom: 1px solid ${theme.border};
}
.leads-toolbar__left  { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.leads-toolbar__right { display: flex; align-items: center; gap: 12px; }

.leads-search { position: relative; display: flex; align-items: center; }
.leads-search__icon {
  position: absolute; left: 11px; display: flex;
  color: ${theme.textMuted}; pointer-events: none;
}
.leads-search__input {
  width: 260px; max-width: 100%;
  box-sizing: border-box;
  padding: 9px 12px 9px 32px;
  border: 1px solid ${theme.border};
  border-radius: 9px;
  background: #fff;
  color: ${theme.text};
  font-size: 13px; font-family: inherit;
  outline: none;
  transition: border-color .15s, box-shadow .15s;
}
.leads-search__input::placeholder { color: ${theme.textMuted}; }
.leads-search__input:focus {
  border-color: ${theme.primary};
  box-shadow: 0 0 0 3px ${theme.primary}1f;
}

.leads-filter { position: relative; display: flex; align-items: center; }
.leads-filter__icon {
  position: absolute; left: 11px; display: flex;
  color: ${theme.textMuted}; pointer-events: none;
}
.leads-filter__select {
  appearance: none; -webkit-appearance: none;
  box-sizing: border-box;
  padding: 9px 30px 9px 32px;
  border: 1px solid ${theme.border};
  border-radius: 9px;
  background: #fff;
  color: ${theme.text};
  font-size: 13px; font-weight: 600; font-family: inherit;
  cursor: pointer; outline: none;
  transition: border-color .15s, box-shadow .15s;
}
.leads-filter__select:focus {
  border-color: ${theme.primary};
  box-shadow: 0 0 0 3px ${theme.primary}1f;
}
.leads-filter__caret {
  position: absolute; right: 11px; display: flex;
  color: ${theme.textMuted}; pointer-events: none;
}

.leads-count { color: ${theme.textMuted}; font-size: 12px; white-space: nowrap; }
.leads-count strong { color: ${theme.text}; font-weight: 700; }
.leads-selected {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 10px; border-radius: 999px;
  background: ${theme.primary}14; color: ${theme.primary};
  font-size: 12px; font-weight: 700; white-space: nowrap;
}

/* ── table ───────────────────────────────────────────── */
.leads-table-wrap { width: 100%; overflow-x: auto; }
.leads-table {
  width: 100%; min-width: 760px;
  border-collapse: collapse; table-layout: fixed;
}
.leads-table th {
  padding: 11px 14px;
  text-align: left;
  background: ${theme.background};
  border-bottom: 1px solid ${theme.border};
  color: ${theme.textMuted};
  font-size: 10px; font-weight: 800;
  letter-spacing: .07em; text-transform: uppercase;
  white-space: nowrap;
}
.leads-table td {
  padding: 11px 14px;
  border-bottom: 1px solid ${theme.border};
  color: ${theme.text};
  font-size: 13px;
  vertical-align: middle;
}
.leads-table tbody tr:last-child td { border-bottom: none; }

.leads-row { cursor: pointer; transition: background .12s; }
.leads-row:hover { background: ${theme.background}; }
.leads-row:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: -2px;
}
.leads-row--selected { background: ${theme.primary}0d; }
.leads-row--selected:hover { background: ${theme.primary}14; }

.leads-truncate {
  display: block;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.leads-muted { color: ${theme.textMuted}; }
.leads-tabular { font-variant-numeric: tabular-nums; }

/* Column sizing. One class per column, set on both the th and the td, so a
   responsive rule can drop a whole column with a single selector. Widths are
   read off the header row under table-layout: fixed. */
.leads-c-check    { width: 42px; }
.leads-c-name     { width: 23%; }
.leads-c-actions  { width: 132px; }
.leads-c-phone    { width: 16%; }
.leads-c-email    { width: 21%; }
.leads-c-received { width: 15%; }
.leads-c-status   { width: 112px; }

/* ── name cell ───────────────────────────────────────── */
.leads-name { display: flex; align-items: center; gap: 10px; min-width: 0; }
.leads-name__text { min-width: 0; }
.leads-name__label { font-weight: 700; color: ${theme.text}; }

/* ── checkbox ────────────────────────────────────────── */
.leads-check {
  width: 15px; height: 15px;
  accent-color: ${theme.primary};
  cursor: pointer;
  display: block;
}

/* ── quick actions ───────────────────────────────────── */
.leads-actions { display: flex; align-items: center; gap: 6px; }
.leads-action {
  width: 27px; height: 27px;
  flex: 0 0 27px;
  padding: 0;
  display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid ${theme.border};
  border-radius: 50%;
  background: #fff;
  color: ${theme.textMuted};
  cursor: pointer;
  text-decoration: none;
  transition: color .12s, border-color .12s, background .12s;
}
.leads-action:hover {
  color: ${theme.primary};
  border-color: ${theme.primary}66;
  background: ${theme.primary}0d;
}
.leads-action:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: 1px;
}
.leads-action--done {
  color: #15803d;
  border-color: #bbf7d0;
  background: #f0fdf4;
}

/* ── status badge ────────────────────────────────────── */
.leads-badge {
  display: inline-flex; align-items: center;
  padding: 3px 9px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 11px; font-weight: 700;
  white-space: nowrap;
}

/* ── empty / loading ─────────────────────────────────── */
.leads-empty {
  display: flex; flex-direction: column; align-items: center;
  gap: 8px; padding: 56px 20px;
  text-align: center;
}
.leads-empty__icon { color: ${theme.border}; }
.leads-empty__title { color: ${theme.text}; font-size: 14px; font-weight: 700; }
.leads-empty__text  { color: ${theme.textMuted}; font-size: 13px; margin: 0; }

.leads-skeleton {
  height: 11px; border-radius: 6px;
  background: ${theme.background};
  animation: leads-pulse 1.3s ease-in-out infinite;
}
@keyframes leads-pulse { 0%,100% { opacity: 1; } 50% { opacity: .45; } }

/* ── detail popout ───────────────────────────────────── */
.leads-popout-overlay {
  position: fixed; inset: 0;
  background: rgba(15,23,42,.55);
  z-index: 10000;
  display: flex; align-items: center; justify-content: center;
  padding: 24px;
  animation: leads-fade .18s ease-out;
}
.leads-popout {
  background: #fff;
  border-radius: ${theme.cardRadius || 14}px;
  width: 100%; max-width: 940px;
  max-height: calc(100vh - 48px);
  display: flex; flex-direction: column;
  overflow: hidden;
  box-shadow: 0 24px 64px rgba(15,23,42,.28);
  animation: leads-pop .2s ease-out;
}
@keyframes leads-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes leads-pop {
  from { opacity: 0; transform: translateY(8px) scale(.99); }
  to   { opacity: 1; transform: none; }
}

.leads-popout__header {
  display: flex; align-items: center; gap: 14px;
  padding: 16px 20px;
  border-bottom: 1px solid ${theme.border};
  flex-shrink: 0;
}
.leads-popout__heading { min-width: 0; flex: 1; }
.leads-popout__title {
  margin: 0; color: ${theme.text};
  font-size: 16px; font-weight: 800; line-height: 1.25;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.leads-popout__sub {
  margin: 3px 0 0; color: ${theme.textMuted};
  font-size: 12px;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.leads-popout__close {
  width: 32px; height: 32px; flex: 0 0 32px;
  display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid ${theme.border}; border-radius: 8px;
  background: #fff; color: ${theme.textMuted};
  cursor: pointer;
  transition: color .12s, border-color .12s, background .12s;
}
.leads-popout__close:hover {
  color: ${theme.text}; background: ${theme.background};
}
.leads-popout__close:focus-visible {
  outline: 2px solid ${theme.primary}; outline-offset: 1px;
}

.leads-popout__body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  min-height: 0;
  overflow: hidden;
}
.leads-popout__pane {
  padding: 20px;
  overflow-y: auto;
  min-width: 0;
}
.leads-popout__pane--details {
  border-left: 1px solid ${theme.border};
  background: ${theme.background};
}
.leads-popout__section {
  margin: 0 0 12px;
  color: ${theme.textMuted};
  font-size: 10px; font-weight: 800;
  letter-spacing: .07em; text-transform: uppercase;
}
.leads-popout__message {
  margin: 0;
  color: ${theme.text};
  font-size: 14px; line-height: 1.65;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.leads-popout__message--empty { color: ${theme.textMuted}; font-style: italic; }

.leads-field { padding: 11px 0; border-top: 1px solid ${theme.border}; }
.leads-field:first-of-type { border-top: none; padding-top: 0; }
.leads-field__label {
  display: block; margin-bottom: 3px;
  color: ${theme.textMuted};
  font-size: 10px; font-weight: 800;
  letter-spacing: .06em; text-transform: uppercase;
}
.leads-field__value {
  display: block; color: ${theme.text};
  font-size: 13px; line-height: 1.5;
  overflow-wrap: anywhere;
}
.leads-field__value a { color: ${theme.primary}; text-decoration: none; }
.leads-field__value a:hover { text-decoration: underline; }
.leads-field__value--muted { color: ${theme.textMuted}; }
.leads-field__value--id { font-size: 12px; font-variant-numeric: tabular-nums; }

@media (max-width: 820px) {
  .leads-popout__body { grid-template-columns: minmax(0, 1fr); }
  .leads-popout__pane--details { border-left: none; border-top: 1px solid ${theme.border}; }
}

/* ── responsive ──────────────────────────────────────── */
@media (max-width: 1180px) {
  .leads-c-phone { display: none; }
  .leads-table { min-width: 620px; }
}
@media (max-width: 900px) {
  .leads-c-received { display: none; }
  .leads-table { min-width: 520px; }
  .leads-search__input { width: 200px; }
}
@media (max-width: 720px) {
  .leads-toolbar { padding: 14px; }
  .leads-toolbar__right { width: 100%; justify-content: space-between; }
}

/* The table keeps a min-width so its remaining columns stay readable, which
   means something has to scroll. Containing it here keeps that scroll inside
   the table rather than making the whole CMS page slide sideways. */
@media (max-width: 900px) {
  .leads-table-wrap,
  .leads-card { overflow-x: auto; -webkit-overflow-scrolling: touch; }
  .leads-search__input { width: 100%; min-height: 44px; }
  .leads-toolbar__right { flex-wrap: wrap; gap: 10px; }
}

@media (max-width: 640px) {
  /* Touch targets, and a dialog measured against the visible viewport rather
     than 100vh, which mobile browser chrome makes taller than the screen. */
  .leads-popout { max-height: 88dvh; }
  .leads-row td { padding-top: 14px; padding-bottom: 14px; }
  .leads-popout__close { min-width: 44px; min-height: 44px; }
}
`;

