import React from "react";
import { navigate } from "gatsby";
import { FaClipboardList } from "react-icons/fa";

import template from "../../config/gh-leads--template";
import leadsEnabled from "../../toggles/leads";
import leadsViewEnabled from "../../toggles/leads--view";
import leadsPreviewEnabled from "../../toggles/leads--preview";
import LeadsView from "./LeadsView";
import LeadsPreview from "./LeadsPreview";
import { LEADS_ROUTE, LEADS_VIEW_PATH } from "./types";
import { leadsApi } from "./leadsApi";
import type { CmsPlugin, CmsViewProps } from "../opencms/core/plugin-types";

/**
 * Leads.
 *
 * Since MTC-KRP-030 this is the CMS home of every form submission, including
 * rental applications — the Application Builder next door configures the form,
 * this shows who filled it in. The pathname is handed down so one submission
 * can be linked to and refreshed.
 *
 * The stylesheet is raw rather than a text child: React escapes a text child,
 * and a style element is raw text in HTML, so a child combinator would reach
 * the CSS parser as an entity and its rule would be dropped.
 */
function LeadsPage({ pathname }: CmsViewProps) {
  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: template.css }} />
      <LeadsView
        api={leadsApi}
        pathname={pathname}
        onOpenLead={(id) =>
          navigate(id ? `${LEADS_ROUTE}/${encodeURIComponent(id)}` : LEADS_ROUTE)
        }
      />
    </>
  );
}

const plugin: CmsPlugin = {
  id: "leads",

  views:
    leadsEnabled && leadsViewEnabled
      ? [
          {
            id: "leads",
            path: LEADS_VIEW_PATH,
            label: template.labels.navLabel,
            component: LeadsPage,
            nav: true,
            order: 200,
            icon: FaClipboardList,
          },
        ]
      : [],

  slots: {
    dashboard:
      leadsEnabled && leadsPreviewEnabled
        ? [{ id: "leads-dashboard", component: LeadsPreview, order: 200 }]
        : [],
  },
};

export default plugin;
