import React from "react";
import { LuCircleCheck } from "react-icons/lu";

export type SelectionToastProps = {
  /** How many things are selected. Zero renders nothing. */
  count: number;
  /** What is being counted, singular. "property", "application". */
  noun?: string;
  /** Plural, when it is not simply noun + "s". */
  plural?: string;
  /**
   * BEM prefix for the toast's classes, so each CMS module paints it from its
   * own stylesheet. Same arrangement as CmsTabs: the behaviour is shared, the
   * paint is not.
   */
  classPrefix?: string;
};

/**
 * "3 properties selected." — or applications, or whatever is being counted.
 *
 * Shared between the Properties CMS and the Application Builder since
 * MTC-KRP-038, which asked for the same selection mode in both. One component
 * so the two cannot drift into different wording or different placement.
 *
 * Follows the site's existing toast, gh-image/UploadNotifications: fixed to a
 * corner, white surface, thin border, soft shadow, above the page. The same
 * shape so the CMS has one idea of what a transient message looks like, rather
 * than the upload toasts in one corner and a differently-shaped one here.
 *
 * Two differences, both deliberate:
 *
 *   It is DERIVED, not queued. The upload toasts are a list with a lifecycle
 *   because an upload starts, progresses and finishes on its own schedule. A
 *   selection count has no lifecycle — it is a function of what is selected
 *   right now, so it is rendered from that and nothing has to remember to
 *   dismiss it.
 *
 *   It sits bottom-centre rather than top-right. The upload toasts live at the
 *   top right; a count that follows the cards being clicked belongs near them
 *   and out of the way of the action buttons at the top.
 *
 * `aria-live="polite"` rather than a role="alert": this accompanies something
 * the user just did, so it should be announced without interrupting them.
 */
export default function SelectionToast({
  count,
  noun = "property",
  plural,
  classPrefix = "kr-props",
}: SelectionToastProps) {
  if (count < 1) return null;

  const many = plural ?? `${noun}s`;

  return (
    <div className={`${classPrefix}__toast`} role="status" aria-live="polite">
      <span className={`${classPrefix}__toast-icon`} aria-hidden="true">
        <LuCircleCheck size={16} />
      </span>
      <span className={`${classPrefix}__toast-text`}>
        {count === 1 ? `1 ${noun} selected` : `${count} ${many} selected`}
      </span>
    </div>
  );
}
