import React from "react";

import {
  NumberField,
  RadioGroup,
  SelectField,
  TextField,
  errorFor,
} from "../Field";
import { proposeSlug } from "../draft";
import type { PriceDisplay } from "../draft";
import type { StepProps } from "./types";
import { AVAILABILITY_CHOICES, PROPERTY_TYPES } from "../vocabulary";

/**
 * Page 1 — the facts.
 *
 * Every value here is entered once and once only. The overview's Property
 * Details, the search filters, the card, the hero's summary line and the
 * similar-property scoring all read these; none of them asks again. That is
 * why page 2 has no "property details" inputs and why the floor-plan step
 * seeds its first unit from these rather than making the manager retype them.
 */

/* Studio through six, which covers the catalogue with room to spare. A select
   rather than a number box because "0" is not how anybody says studio, and
   because it makes an unusable entry impossible rather than merely reportable. */
const BEDROOM_CHOICES = [0, 1, 2, 3, 4, 5, 6];

export default function BasicsStep({ draft, onChange, issues }: StepProps) {
  const slug = draft.slug ?? proposeSlug(draft.title ?? "");

  /* An existing record could hold a bedroom count outside the list above. It
     keeps its own option rather than being silently rounded into range. */
  const bedroomOptions = BEDROOM_CHOICES.includes(draft.bedrooms ?? -1)
    ? BEDROOM_CHOICES
    : typeof draft.bedrooms === "number"
      ? [...BEDROOM_CHOICES, draft.bedrooms].sort((a, b) => a - b)
      : BEDROOM_CHOICES;

  const priceDisplay: PriceDisplay = draft.priceDisplay ?? "show";

  return (
    <div className="kr-wiz__fields">
      {/* Name, location and type are one thought — what this property IS — so
          they share a card. One card per field would be seven cards on this
          step, which is chunking taken past the point where it helps. */}
      <div className="kr-wiz__stack">
      <TextField
        id="kr-wiz-title"
        label="Property name"
        value={draft.title ?? ""}
        placeholder="Cedar Line Apartments"
        onChange={(title) => onChange({ title })}
        error={errorFor(issues, "kr-wiz-title")}
        help={
          slug ? (
            <>
              The name people will see. Its web address will be{" "}
              <code className="kr-wiz__code">/property/{slug}</code>
              {draft.slugLocked
                ? " — this stays the same even if you change the name, so existing links keep working."
                : "."}
            </>
          ) : (
            "The name people will see on the website."
          )
        }
      />

      <TextField
        id="kr-wiz-location"
        label="Location"
        value={draft.location ?? ""}
        placeholder="Framingham, Massachusetts"
        onChange={(location) => onChange({ location })}
        error={errorFor(issues, "kr-wiz-location")}
        help="Town or city, and state. This is what people search by."
      />

      <SelectField
        id="kr-wiz-type"
        label="Property type"
        value={draft.type ?? ""}
        onChange={(type) => onChange({ type })}
        options={PROPERTY_TYPES.map((type) => ({ value: type, label: type }))}
        placeholder="Choose a type"
        error={errorFor(issues, "kr-wiz-type")}
      />
      </div>

      {/* Three short numbers, side by side on a wide screen and stacked on a
          phone — they are one thought, not three. */}
      <div className="kr-wiz__row">
        <SelectField
          id="kr-wiz-bedrooms"
          label="Bedrooms"
          value={draft.bedrooms === undefined ? "" : String(draft.bedrooms)}
          onChange={(value) =>
            onChange({ bedrooms: value === "" ? undefined : Number(value) })
          }
          options={bedroomOptions.map((count) => ({
            value: String(count),
            label: count === 0 ? "Studio" : String(count),
          }))}
          placeholder="Choose"
          error={errorFor(issues, "kr-wiz-bedrooms")}
        />

        <NumberField
          id="kr-wiz-bathrooms"
          label="Bathrooms"
          value={draft.bathrooms}
          min={0}
          step={0.5}
          placeholder="1"
          onChange={(bathrooms) => onChange({ bathrooms })}
          error={errorFor(issues, "kr-wiz-bathrooms")}
          help="Halves are fine — 1.5."
        />

        <NumberField
          id="kr-wiz-area"
          label="Square feet"
          value={draft.area}
          min={1}
          step={1}
          placeholder="1050"
          onChange={(area) => onChange({ area })}
          error={errorFor(issues, "kr-wiz-area")}
          help="Just the number."
        />
      </div>

      <SelectField
        id="kr-wiz-availability"
        label="Availability"
        value={draft.availability ?? ""}
        onChange={(availability) => onChange({ availability })}
        options={AVAILABILITY_CHOICES.map((choice) => ({
          value: choice.value,
          label: choice.value,
        }))}
        placeholder="Choose availability"
        error={errorFor(issues, "kr-wiz-availability")}
        help={
          AVAILABILITY_CHOICES.find((choice) => choice.value === draft.availability)
            ?.help ??
          "Asked once here. If you add floor plans with their own availability, the property follows the best of them."
        }
      />

      {/* ── pricing ─────────────────────────────────────────
          The choice first, then only what that choice needs. Showing an empty
          price box beside an "ask for pricing" option asks the manager to work
          out which one the page will believe. */}
      <div className="kr-wiz__stack">
      <RadioGroup<PriceDisplay>
        name="kr-wiz-price-display"
        legend="Price display"
        value={priceDisplay}
        onChange={(value) => onChange({ priceDisplay: value })}
        options={[
          { value: "show", label: "Show price", help: "The monthly rent appears on the page." },
          {
            value: "ask",
            label: "Ask for pricing",
            help: "The page invites people to get in touch instead.",
          },
        ]}
      />

      {priceDisplay === "show" ? (
        <NumberField
          id="kr-wiz-rent"
          label="Monthly price"
          value={draft.rent}
          min={1}
          step={1}
          prefix="$"
          suffix="/ month"
          placeholder="1995"
          onChange={(rent) => onChange({ rent })}
          error={errorFor(issues, "kr-wiz-rent")}
          help="If you add floor plans later, the page shows the cheapest one you can actually rent."
        />
      ) : (
        <p className="kr-wiz__note kr-wiz__note--tight">
          <span>
            The page will show <strong>Contact for pricing</strong>. Any price you
            entered stays here in case you change your mind, but it will not
            appear on the website.
          </span>
        </p>
      )}
      </div>
    </div>
  );
}
