// Structure, style and colour for the Application Builder.
//
// One sheet, emitted once by the view. Every value comes from the CMS theme, so
// the plugin follows the admin's design rather than carrying its own: nothing
// below hardcodes a brand colour.
//
// The reference screenshots Nate supplied are structure only. The composition
// is taken from them — an application shown as a real card with its own first
// questions rendered small, a clear active marker, a prominent create action —
// and none of the colour is: no gradients, no theme gallery, no aqua.

import theme from "../../config/opencms--theme";

export type ApplyTemplate = {
  css: string;
  rootClass: string;
  labels: {
    navLabel: string;
    previewTitle: string;
  };
};

const radius = theme.cardRadius ?? 14;

/* Decelerating, so movement arrives rather than stopping dead. Same curve the
   public site uses. */
const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-apply-cms { color: ${theme.text}; }

.kr-apply-cms *,
.kr-apply-cms *::before,
.kr-apply-cms *::after { box-sizing: border-box; }

/* ── tabs ─────────────────────────────────────────────────
   The dialer's settings pages gave the shape - a quiet underline strip driven
   by one config array. The semantics are Kelley Road's own, from the property
   page's floor-plan tabs, which already do roving tabindex and arrow keys
   properly; the dialer's stop at aria-selected. */
.kr-apply-cms__tabs {
  display: flex;
  gap: 26px;
  border-bottom: 1px solid ${theme.border};
  margin-bottom: 26px;
  overflow-x: auto;
  scrollbar-width: none;
}
.kr-apply-cms__tabs::-webkit-scrollbar { display: none; }
.kr-apply-cms__tab {
  appearance: none;
  background: none;
  border: 0;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  padding: 0 0 12px;
  color: ${theme.textMuted};
  font: inherit;
  font-size: 13.5px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: color 160ms ease, border-color 160ms ease;
}
.kr-apply-cms__tab:hover { color: ${theme.text}; }
.kr-apply-cms__tab[aria-selected="true"] {
  color: ${theme.text};
  border-bottom-color: ${theme.primary};
}
.kr-apply-cms__tab:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: 3px;
  border-radius: 2px;
}
.kr-apply-cms__tab-count {
  display: inline-block;
  margin-left: 7px;
  padding: 1px 7px;
  border-radius: 999px;
  background: ${theme.primary}14;
  color: ${theme.textMuted};
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

/* ── shared surfaces ──────────────────────────────────── */
.kr-apply-cms__card {
  background: ${theme.sidebar};
  border: 1px solid ${theme.border};
  border-radius: ${radius}px;
  box-shadow: 0 1px 3px rgba(15, 23, 42, .04);
}

.kr-apply-cms__section-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin: 0 0 16px;
}
.kr-apply-cms__section-title {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.kr-apply-cms__hint {
  margin: 4px 0 0;
  color: ${theme.textMuted};
  font-size: 13px;
  line-height: 1.6;
}
.kr-apply-cms__eyebrow {
  margin: 0 0 6px;
  color: ${theme.textMuted};
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

/* ── buttons ──────────────────────────────────────────── */
.kr-apply-cms__btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 15px;
  border-radius: 8px;
  border: 1px solid ${theme.border};
  background: ${theme.sidebar};
  color: ${theme.text};
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: border-color 160ms ease, background 160ms ease, color 160ms ease;
}
.kr-apply-cms__btn:hover:not(:disabled) { border-color: ${theme.primary}; }
.kr-apply-cms__btn:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: 2px;
}
.kr-apply-cms__btn:disabled { opacity: .45; cursor: not-allowed; }
.kr-apply-cms__btn--primary {
  background: ${theme.primary};
  border-color: ${theme.primary};
  color: #fff;
}
.kr-apply-cms__btn--primary:hover:not(:disabled) {
  background: ${theme.primaryHover};
  border-color: ${theme.primaryHover};
}
/* Filled red with white text. It used to set the text colour only, so when it
   was combined with --primary (which paints the button charcoal) the result
   was red text on a dark button — the "Move to Trash" control in Nate's
   screenshot. Setting all three properties means the modifier reads the same
   whether or not it is stacked on --primary. */
.kr-apply-cms__btn--danger {
  background: ${theme.danger};
  border-color: ${theme.danger};
  color: #fff;
}
.kr-apply-cms__btn--danger:hover:not(:disabled) {
  background: #B91C1C;
  border-color: #B91C1C;
  color: #fff;
}
.kr-apply-cms__btn--danger:focus-visible { outline-color: ${theme.danger}; }
.kr-apply-cms__btn--icon { padding: 8px 10px; }

/* ── selection mode ───────────────────────────────────────
   MTC-KRP-038. The same interaction the Properties CMS has: arm the mode, pick
   cards, confirm. Only active while the selectable modifier is on, so ordinary use of
   the Builder is untouched. */
.kr-apply-cms__head-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}
.kr-apply-cms__head-actions .kr-apply-cms__btn { white-space: nowrap; }

.kr-apply-cms__app--selectable {
  position: relative;
  cursor: pointer;
  transition: border-color 160ms ${ease}, box-shadow 160ms ${ease};
}
/* Light enough that the application under the pointer is still readable —
   the point is to see WHICH card you are choosing. */
.kr-apply-cms__app--selectable:hover { border-color: ${theme.danger}80; }
.kr-apply-cms__app--selectable:hover::after,
.kr-apply-cms__app--selected::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: ${theme.danger};
  opacity: .07;
  pointer-events: none;
}
.kr-apply-cms__app--selectable:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: 2px;
}
.kr-apply-cms__app--selected {
  border-color: ${theme.danger};
  box-shadow: 0 0 0 1px ${theme.danger};
}

/* The tick, so selection is not carried by a border colour alone. */
.kr-apply-cms__app-mark {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 1px solid ${theme.border};
  background: ${theme.sidebar};
  color: transparent;
}
.kr-apply-cms__app--selected .kr-apply-cms__app-mark {
  background: ${theme.danger};
  border-color: ${theme.danger};
  color: #fff;
}

/* ── the selection toast ───────────────────────────────── */
.kr-apply-cms__toast {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 18px;
  border-radius: 999px;
  background: ${theme.primary};
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  box-shadow: 0 10px 32px rgba(15, 23, 42, .24);
}
.kr-apply-cms__toast-icon { display: inline-flex; flex-shrink: 0; }
.kr-apply-cms__toast-text { white-space: nowrap; }

/* The quieter second line in a confirmation. */
.kr-apply-cms__dialog-note {
  margin: 0 0 4px;
  padding: 10px 12px;
  border-radius: 8px;
  background: ${theme.background};
  color: ${theme.textMuted};
  font-size: 13px;
  line-height: 1.6;
}

@media (max-width: 640px) {
  .kr-apply-cms__head-actions { width: 100%; }
  .kr-apply-cms__head-actions .kr-apply-cms__btn {
    flex: 1;
    justify-content: center;
    min-height: 44px;
  }
  .kr-apply-cms__toast { left: 16px; right: 16px; transform: none; justify-content: center; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-apply-cms__app--selectable { transition: none; }
}

/* ── active application banner ────────────────────────── */
.kr-apply-cms__active {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 22px;
  margin-bottom: 26px;
}
.kr-apply-cms__active-name {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

/* ── application cards ────────────────────────────────── */
.kr-apply-cms__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 18px;
}
.kr-apply-cms__app {
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
/* The active card is marked by a band and a tick rather than a bare checkbox:
   an unexplained checkbox makes the reader reverse-engineer the business rule. */
.kr-apply-cms__app--active { border-color: ${theme.primary}; }
.kr-apply-cms__app-flag {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  background: ${theme.primary};
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.kr-apply-cms__app-body { padding: 16px 18px 0; }
.kr-apply-cms__app-name {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.kr-apply-cms__app-meta {
  margin: 0 0 14px;
  color: ${theme.textMuted};
  font-size: 12px;
}

/* The miniature is built from the application's real questions, at reduced
   scale and inert. Not a screenshot, and not a second renderer. It is meant to
   look like a form at a glance - that recognition is the whole point of the
   card - while the muted fills and absent cursor keep it plainly non-live. */
.kr-apply-cms__mini {
  padding: 15px 14px;
  border: 1px solid ${theme.border};
  border-radius: 9px;
  background: ${theme.sidebar};
  pointer-events: none;
  user-select: none;
}
.kr-apply-cms__mini-field + .kr-apply-cms__mini-field { margin-top: 12px; }
.kr-apply-cms__mini-label {
  display: block;
  margin-bottom: 6px;
  color: ${theme.text};
  font-size: 11.5px;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kr-apply-cms__mini-input {
  height: 26px;
  border: 1px solid ${theme.border};
  border-radius: 6px;
  background: ${theme.background};
}
.kr-apply-cms__mini-choices { display: flex; flex-wrap: wrap; gap: 6px 16px; }
.kr-apply-cms__mini-choice {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: ${theme.textMuted};
  font-size: 11.5px;
}
.kr-apply-cms__mini-dot {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  border: 1px solid ${theme.textMuted}66;
  background: ${theme.sidebar};
}
.kr-apply-cms__mini-dot--round { border-radius: 50%; }
.kr-apply-cms__mini-dot--square { border-radius: 3px; }
.kr-apply-cms__mini-more {
  margin: 12px 0 0;
  padding-top: 10px;
  border-top: 1px solid ${theme.border};
  color: ${theme.textMuted};
  font-size: 11px;
}
.kr-apply-cms__app-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: auto;
  padding: 14px 18px;
}
.kr-apply-cms__app-actions .kr-apply-cms__btn {
  font-size: 12px;
  padding: 7px 12px;
  /* "Use This" was breaking across two lines and making its button twice the
     height of the three beside it. A button label is one line; if the row
     runs out of space the ROW should wrap, not the words inside a button. */
  white-space: nowrap;
  flex: 0 0 auto;
}
.kr-apply-cms__app-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.kr-apply-cms__app-spacer { flex: 1; }

/* ── question list ────────────────────────────────────────
   The label is the content and the buttons are the plumbing, so the label is
   the only thing at full weight. Every row previously carried four equally
   loud buttons, which made a list of questions read as a list of controls. */
.kr-apply-cms__question {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 20px;
  min-height: 64px;
}
.kr-apply-cms__question + .kr-apply-cms__question { border-top: 1px solid ${theme.border}; }
.kr-apply-cms__question:hover { background: rgba(0, 0, 0, 0.025); }
.kr-apply-cms__question-index {
  flex-shrink: 0;
  width: 22px;
  color: ${theme.textMuted};
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
}
.kr-apply-cms__question-main { flex: 1; min-width: 0; }
.kr-apply-cms__question-label {
  margin: 0 0 2px;
  font-size: 14.5px;
  font-weight: 600;
  line-height: 1.35;
  word-break: break-word;
}
.kr-apply-cms__question-meta {
  margin: 0;
  color: ${theme.textMuted};
  font-size: 12px;
}
.kr-apply-cms__question-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}
/* Quiet until the row is approached, but never hidden: a control that only
   exists on hover is a control a touch user does not have. */
.kr-apply-cms__qbtn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 34px;
  height: 34px;
  padding: 0 9px;
  border: 1px solid transparent;
  border-radius: 7px;
  background: none;
  color: ${theme.textMuted};
  font: inherit;
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background 140ms ease, color 140ms ease, border-color 140ms ease;
}
.kr-apply-cms__qbtn:hover:not(:disabled) {
  background: ${theme.sidebar};
  border-color: ${theme.border};
  color: ${theme.text};
}
.kr-apply-cms__qbtn:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: 1px;
}
.kr-apply-cms__qbtn:disabled { opacity: .3; cursor: not-allowed; }
.kr-apply-cms__qbtn--danger:hover:not(:disabled) {
  color: ${theme.danger};
  border-color: ${theme.danger}55;
}

/* The one action that continues the job, so it is the one that looks like it. */
.kr-apply-cms__add-question {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  width: 100%;
  padding: 15px;
  border: 1px dashed ${theme.border};
  border-radius: ${radius}px;
  background: ${theme.sidebar};
  color: ${theme.text};
  font: inherit;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  transition: border-color 160ms ease, background 160ms ease;
}
.kr-apply-cms__add-question:hover {
  border-color: ${theme.primary};
  border-style: solid;
}
.kr-apply-cms__add-question:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: 2px;
}

/* ── table ────────────────────────────────────────────── */
.kr-apply-cms__table { width: 100%; border-collapse: collapse; font-size: 13.5px; }
.kr-apply-cms__table th {
  padding: 12px 16px;
  border-bottom: 1px solid ${theme.border};
  color: ${theme.textMuted};
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-align: left;
  text-transform: uppercase;
}
.kr-apply-cms__table td {
  padding: 14px 16px;
  border-bottom: 1px solid ${theme.border};
  vertical-align: top;
}
.kr-apply-cms__table tr:last-child td { border-bottom: 0; }
.kr-apply-cms__row { cursor: pointer; }
.kr-apply-cms__row:hover td { background: ${theme.background}; }
.kr-apply-cms__row:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: -2px;
}

/* ── empty states ─────────────────────────────────────────
   Sized to their message rather than to the viewport. These used to be a line
   of text adrift in a very large white box, which read as something failing to
   load rather than as nothing being there yet. */
.kr-apply-cms__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 220px;
  padding: 36px 24px;
  text-align: center;
}
.kr-apply-cms__empty-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  margin-bottom: 14px;
  border-radius: 50%;
  background: ${theme.primary}0f;
  color: ${theme.textMuted};
}
.kr-apply-cms__empty-title {
  margin: 0 0 6px;
  font-size: 15px;
  font-weight: 700;
}
.kr-apply-cms__empty-text {
  margin: 0 auto;
  max-width: 34ch;
  color: ${theme.textMuted};
  font-size: 13.5px;
  line-height: 1.65;
}

/* ── dialog ───────────────────────────────────────────── */
.kr-apply-cms__veil {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(15, 23, 42, .45);
}
.kr-apply-cms__dialog {
  width: 100%;
  max-width: 460px;
  max-height: calc(100vh - 40px);
  max-height: calc(100dvh - 40px);
  overflow-y: auto;
  padding: 24px;
  background: ${theme.sidebar};
  border-radius: ${radius}px;
}
.kr-apply-cms__dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.kr-apply-cms__dialog-text {
  margin: 0 0 18px;
  color: ${theme.textMuted};
  font-size: 13.5px;
  line-height: 1.7;
}
.kr-apply-cms__dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 22px;
}

/* ── fields ───────────────────────────────────────────── */
.kr-apply-cms__label {
  display: block;
  margin-bottom: 7px;
  font-size: 12px;
  font-weight: 600;
}
.kr-apply-cms__input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid ${theme.border};
  border-radius: 8px;
  background: ${theme.sidebar};
  color: ${theme.text};
  font: inherit;
  font-size: 14px;
}
.kr-apply-cms__input:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: 1px;
}
.kr-apply-cms__field + .kr-apply-cms__field { margin-top: 16px; }
.kr-apply-cms__option-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}
.kr-apply-cms__switch {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 13.5px;
  cursor: pointer;
}

/* ── feedback ─────────────────────────────────────────── */
.kr-apply-cms__banner {
  padding: 12px 16px;
  margin-bottom: 18px;
  border: 1px solid ${theme.border};
  border-radius: 8px;
  font-size: 13.5px;
  line-height: 1.6;
}
.kr-apply-cms__banner--ok {
  border-color: ${theme.primary}55;
  background: ${theme.primary}0d;
}
.kr-apply-cms__banner--bad {
  border-color: ${theme.danger}55;
  background: ${theme.danger}0d;
  color: ${theme.danger};
}
/* Neither success nor failure: something happened on screen but was not
   stored. Used for walkthrough practice changes. */
.kr-apply-cms__banner--note {
  background: ${theme.background};
  color: ${theme.textMuted};
}
/* A temporary infrastructure condition, so it is stated once and quietly. As
   a full-width block it outweighed the feature it was describing on every tab. */
.kr-apply-cms__note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 18px;
  padding: 9px 12px;
  border: 1px solid ${theme.border};
  border-radius: 8px;
  background: ${theme.background};
  color: ${theme.textMuted};
  font-size: 12.5px;
  line-height: 1.5;
}
.kr-apply-cms__note-icon { flex-shrink: 0; margin-top: 1px; }
.kr-apply-cms__note strong { color: ${theme.text}; font-weight: 600; }

/* ── preview ──────────────────────────────────────────── */
.kr-apply-cms__preview-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 20px;
}
.kr-apply-cms__preview-body { padding: 26px; }
.kr-apply-cms__preview-body form { pointer-events: none; }

/* ── detail ───────────────────────────────────────────── */
.kr-apply-cms__answers { margin: 0; }
.kr-apply-cms__answer + .kr-apply-cms__answer { margin-top: 16px; }
.kr-apply-cms__answer-label {
  margin: 0 0 3px;
  color: ${theme.textMuted};
  font-size: 12px;
  font-weight: 600;
}
.kr-apply-cms__answer-value {
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  word-break: break-word;
}

/* ── help ─────────────────────────────────────────────────
   A chooser, not a manual. Seven topics expanded at once was more reading than
   the whole feature needs, and buried whichever one the reader wanted. */
.kr-apply-cms__topics { overflow: hidden; }
.kr-apply-cms__topic {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 15px 20px;
  border: 0;
  border-radius: 0;
  background: none;
  color: ${theme.text};
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 140ms ease;
}
.kr-apply-cms__topic + .kr-apply-cms__topic { border-top: 1px solid ${theme.border}; }
.kr-apply-cms__topic:hover { background: ${theme.background}; }
.kr-apply-cms__topic:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: -2px;
}
.kr-apply-cms__topic-main { flex: 1; min-width: 0; }
.kr-apply-cms__topic-title {
  margin: 0 0 2px;
  font-size: 14px;
  font-weight: 600;
}
.kr-apply-cms__topic-summary {
  margin: 0;
  color: ${theme.textMuted};
  font-size: 12.5px;
  line-height: 1.5;
}
.kr-apply-cms__topic-arrow { flex-shrink: 0; color: ${theme.textMuted}; }
.kr-apply-cms__steps {
  margin: 0;
  padding-left: 20px;
  display: grid;
  gap: 10px;
  font-size: 14px;
  line-height: 1.6;
}
.kr-apply-cms__steps li { padding-left: 4px; }


/* ── guided walkthrough ───────────────────────────────────
   The dark is four panels around the target, not one sheet over it, so the
   spotlit control keeps its real appearance and stays clickable. Only the
   callout and the arrow sit above everything. */
.kr-tut { position: fixed; inset: 0; z-index: 2000; pointer-events: none; }
.kr-tut__mask {
  position: fixed;
  background: rgba(15, 18, 21, .8);
  pointer-events: auto;
}
.kr-tut__ring {
  position: fixed;
  border: 2px solid ${theme.primaryHover};
  border-radius: 10px;
  pointer-events: none;
  animation: kr-tut-ring 2100ms ${ease} infinite;
}
/* A breath rather than a flash. The control underneath is the thing being
   looked at; the ring only has to say where it ends. */
@keyframes kr-tut-ring {
  0%, 100% { box-shadow: 0 0 0 3px ${theme.primaryHover}33; }
  50% { box-shadow: 0 0 0 7px ${theme.primaryHover}1a; }
}

/* The spotlight arriving, so a step change is a movement rather than a jump. */
.kr-tut__mask { transition: all 220ms ${ease}; }
.kr-tut__arrow-wrap { position: fixed; pointer-events: none; }
.kr-tut__arrow { display: block; }
.kr-tut__arrow svg { display: block; overflow: visible; }

/* The arrow's motion, in three parts that run once and then settle into a
   drift. Timed so the shaft draws before the head arrives, which reads as
   pointing rather than blinking. */
.kr-tut__arrow-shaft {
  stroke-dasharray: 90;
  stroke-dashoffset: 90;
  animation: kr-tut-draw 620ms ${ease} forwards;
}
.kr-tut__arrow-head {
  opacity: 0;
  transform: translateX(-8px);
  transform-origin: center;
  animation: kr-tut-head 380ms ${ease} 430ms forwards;
}
/* The whole arrow eases toward the target and back, indefinitely. Small
   amplitude on purpose: it should catch the eye once, not pulse for attention
   while somebody is trying to read the callout beside it. */
.kr-tut__arrow-group {
  animation: kr-tut-nudge 2100ms ${ease} 900ms infinite;
}

@keyframes kr-tut-draw {
  to { stroke-dashoffset: 0; }
}
@keyframes kr-tut-head {
  to { opacity: 1; transform: translateX(0); }
}
@keyframes kr-tut-nudge {
  0%, 100% { transform: translateX(0); }
  45% { transform: translateX(9px); }
}

/* Reduced motion, or an explicit still arrow: fully drawn, no movement. The
   arrow still has a job to do standing still. */
.kr-tut__arrow--still .kr-tut__arrow-shaft {
  stroke-dashoffset: 0;
  animation: none;
}
.kr-tut__arrow--still .kr-tut__arrow-head {
  opacity: 1;
  transform: none;
  animation: none;
}
.kr-tut__arrow--still .kr-tut__arrow-group { animation: none; }

.kr-tut__callout {
  position: fixed;
  padding: 18px 20px;
  border-radius: ${radius}px;
  background: ${theme.sidebar};
  color: ${theme.text};
  box-shadow: 0 18px 44px rgba(0, 0, 0, .34);
  pointer-events: auto;
}
.kr-tut__callout:focus { outline: none; }
.kr-tut__callout:focus-visible { outline: 2px solid ${theme.primaryHover}; outline-offset: 2px; }
.kr-tut__step {
  margin: 0 0 8px;
  color: ${theme.textMuted};
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.kr-tut__title {
  margin: 0 0 6px;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.kr-tut__body {
  margin: 0;
  color: ${theme.textMuted};
  font-size: 13.5px;
  line-height: 1.6;
}
.kr-tut__practice {
  display: block;
  margin-top: 10px;
  color: ${theme.textMuted};
  font-size: 12px;
  line-height: 1.5;
}
.kr-tut__prompt {
  margin: 12px 0 0;
  padding: 8px 10px;
  border-radius: 7px;
  background: ${theme.primaryHover}14;
  color: ${theme.text};
  font-size: 12.5px;
  line-height: 1.5;
}
.kr-tut__actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 18px;
}
.kr-tut__spacer { flex: 1; }
.kr-tut__btn {
  appearance: none;
  padding: 8px 14px;
  border: 1px solid ${theme.border};
  border-radius: 8px;
  background: ${theme.sidebar};
  color: ${theme.text};
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
.kr-tut__btn:hover { border-color: ${theme.primary}; }
.kr-tut__btn:focus-visible { outline: 2px solid ${theme.primaryHover}; outline-offset: 2px; }
.kr-tut__btn--primary {
  background: ${theme.primary};
  border-color: ${theme.primary};
  color: #fff;
}
.kr-tut__btn--primary:hover {
  background: ${theme.primaryHover};
  border-color: ${theme.primaryHover};
}
.kr-tut__btn--quiet { border-color: transparent; color: ${theme.textMuted}; }

/* The start action on a Help topic. */
.kr-tut__start { margin-top: 18px; }

@media (max-width: 640px) {
  /* Anchoring to the target would leave no room beside it on a phone, so the
     callout docks to the bottom and the spotlight keeps its position. */
  .kr-tut__callout {
    top: auto !important;
    left: 12px !important;
    right: 12px;
    bottom: 12px;
    width: auto !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .kr-tut__ring { animation: none; box-shadow: 0 0 0 3px ${theme.primaryHover}33; }
  .kr-tut__mask { transition: none; }
  .kr-tut__arrow-shaft,
  .kr-tut__arrow-head,
  .kr-tut__arrow-group { animation: none; }
  .kr-tut__arrow-shaft { stroke-dashoffset: 0; }
  .kr-tut__arrow-head { opacity: 1; transform: none; }
}

/* ── narrow screens ─────────────────────────────────────────
   The CMS is one set of components with responsive rules, not a second mobile
   build. Two places need a genuinely different presentation rather than a
   smaller one: a data table has no honest narrow form, so it becomes cards;
   and a dialog has to answer to the visible viewport rather than to 100vh. */

@media (max-width: 900px) {
  .kr-apply-cms__grid { grid-template-columns: minmax(0, 1fr); }
}

@media (max-width: 640px) {
  /* Tabs stay full size and scroll rather than shrinking to fit. Four
     microscopic labels would be worse than a swipe. */
  .kr-apply-cms__tabs {
    gap: 18px;
    /* Bleeds to the content edge so it is obvious the strip scrolls. */
    margin-left: -16px;
    margin-right: -16px;
    padding-left: 16px;
    padding-right: 16px;
    scroll-snap-type: x proximity;
  }
  .kr-apply-cms__tab { scroll-snap-align: start; padding-bottom: 14px; }

  .kr-apply-cms__section-head { align-items: stretch; }
  /* A primary action people are meant to find goes full width. */
  .kr-apply-cms__section-head .kr-apply-cms__btn--primary { justify-content: center; }

  .kr-apply-cms__active { padding: 16px; }
  .kr-apply-cms__active-name { font-size: 18px; }

  .kr-apply-cms__app-actions { flex-wrap: wrap; }
  .kr-apply-cms__app-actions .kr-apply-cms__btn { min-height: 40px; }
  .kr-apply-cms__app-spacer { display: none; }

  /* ── question rows ──────────────────────────────────────
     The label keeps the full width and the controls sit under it. Squeezing a
     question, its type and four buttons onto one 320px line is how you end up
     with 9px text. */
  .kr-apply-cms__question {
    flex-wrap: wrap;
    align-items: flex-start;
    padding: 14px 16px;
  }
  .kr-apply-cms__question-index { width: 20px; }
  .kr-apply-cms__question-main { flex: 1 1 calc(100% - 36px); }
  .kr-apply-cms__question-actions {
    width: 100%;
    justify-content: flex-start;
    gap: 6px;
    margin-top: 4px;
    padding-left: 36px;
  }
  /* 44px targets, which is the point at which a thumb stops missing. */
  .kr-apply-cms__qbtn { min-width: 44px; height: 44px; }

  .kr-apply-cms__add-question { padding: 16px; }

  /* ── tables become cards ────────────────────────────────
     Four columns cannot be read at 320px, and forcing a min-width makes the
     whole page scroll sideways. Each row becomes a card, with the column name
     supplied from the cell's own data-label. */
  .kr-apply-cms__table,
  .kr-apply-cms__table tbody,
  .kr-apply-cms__table tr,
  .kr-apply-cms__table td { display: block; width: 100%; }

  .kr-apply-cms__table thead { display: none; }

  .kr-apply-cms__table tr {
    padding: 4px 0;
    border-bottom: 1px solid ${theme.border};
  }
  .kr-apply-cms__table tr:last-child { border-bottom: 0; }

  .kr-apply-cms__table td {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 14px;
    padding: 7px 16px;
    border-bottom: 0;
    text-align: left;
  }
  .kr-apply-cms__table td::before {
    content: attr(data-label);
    flex-shrink: 0;
    color: ${theme.textMuted};
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }
  /* The first cell is the record's name; it leads rather than being a row. */
  .kr-apply-cms__table td:first-child {
    display: block;
    padding-top: 14px;
    font-size: 15px;
  }
  .kr-apply-cms__table td:first-child::before { content: none; }
  .kr-apply-cms__table td:last-child { padding-bottom: 14px; }
  .kr-apply-cms__table td:last-child::before { content: none; }

  .kr-apply-cms__empty { min-height: 180px; padding: 28px 20px; }

  /* ── dialogs ────────────────────────────────────────────
     dvh, not vh: mobile browser chrome makes vh taller than what is actually
     visible, which pushed Save below the fold with no way to reach it. */
  .kr-apply-cms__veil {
    padding: 12px;
    align-items: flex-end;
  }
  .kr-apply-cms__dialog {
    max-width: 100%;
    max-height: 88dvh;
    padding: 20px 18px calc(20px + env(safe-area-inset-bottom));
  }
  .kr-apply-cms__dialog-actions .kr-apply-cms__btn { flex: 1 1 auto; justify-content: center; }
  .kr-apply-cms__input { min-height: 44px; font-size: 16px; }
  .kr-apply-cms__option-row .kr-apply-cms__btn { min-width: 44px; min-height: 44px; }
  .kr-apply-cms__switch { min-height: 44px; }
  .kr-apply-cms__btn { min-height: 42px; }

  /* ── walkthrough ────────────────────────────────────────
     Docked to the bottom so it can never land on the spotlight, and clear of
     the home indicator. */
  .kr-tut__callout {
    top: auto !important;
    left: 12px !important;
    right: 12px;
    bottom: calc(12px + env(safe-area-inset-bottom));
    width: auto !important;
    max-height: 62dvh;
    overflow-y: auto;
  }
  .kr-tut__actions .kr-tut__btn { min-height: 44px; }
}

@media (max-width: 380px) {
  .kr-apply-cms__question-actions { padding-left: 0; }
  .kr-apply-cms__app-actions .kr-apply-cms__btn { flex: 1 1 auto; justify-content: center; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-apply-cms__tab,
  .kr-apply-cms__btn { transition: none; }
}
`;

const template: ApplyTemplate = {
  css,
  rootClass: "kr-apply-cms",
  labels: {
    navLabel: "Application Builder",
    previewTitle: "Preview",
  },
};

export default template;
