// What is wrong, and what is merely not filled in yet.
//
// The distinction the whole workflow rests on:
//
//   error   — the value is WRONG. "abc" square feet, a negative rent, Show
//             Price chosen with nothing to show. This blocks Continue,
//             because carrying a broken value forward only means finding it
//             again at the end.
//
//   missing — the value is ABSENT. Bedrooms not typed yet, no description.
//             This does not block anything except publishing, because a
//             manager who has to go and look something up should be able to
//             carry on and come back rather than be held at step one.
//
// Put plainly: you can leave a field empty, you cannot leave it wrong. That is
// what stops validation being bureaucratic while still meaning something.
//
// No React and no DOM here, so every rule below is directly testable and the
// same rules drive the Continue button, the step ticks and the review screen.
// If those three ever disagreed, the user would be right and we would be
// wrong.

import type { PropertyDraft } from "./draft";
import { AVAILABILITY_VALUES, PROPERTY_TYPES } from "./vocabulary.ts";

export type IssueKind = "error" | "missing";

export type FieldIssue = {
  stepId: string;
  /** The control's DOM id, so Continue can move focus to it. */
  field: string;
  /** What the user calls this field. */
  label: string;
  message: string;
  kind: IssueKind;
};

const text = (value: unknown): string =>
  typeof value === "string" ? value.trim() : "";

const isBlank = (value: unknown): boolean => text(value).length === 0;

/**
 * Whether a number field holds something unusable.
 *
 * `undefined` is absent, not wrong — it is the state of a field nobody has
 * typed in yet. NaN is what an unparseable entry becomes, and that IS wrong.
 */
function badNumber(
  value: unknown,
  { min = 0, allowFraction = true }: { min?: number; allowFraction?: boolean } = {}
): boolean {
  if (value === undefined || value === null) return false;
  if (typeof value !== "number" || !Number.isFinite(value)) return true;
  if (value < min) return true;
  if (!allowFraction && !Number.isInteger(value)) return true;
  return false;
}

const absent = (value: unknown): boolean => value === undefined || value === null;

/* ── page 1 ──────────────────────────────────────────────── */

function basicsIssues(draft: PropertyDraft): FieldIssue[] {
  const issues: FieldIssue[] = [];
  const at = (
    field: string,
    label: string,
    message: string,
    kind: IssueKind
  ) => issues.push({ stepId: "basics", field, label, message, kind });

  if (isBlank(draft.title)) {
    at("kr-wiz-title", "Property name", "Enter a property name.", "missing");
  }

  if (isBlank(draft.location)) {
    at("kr-wiz-location", "Location", "Enter the town or city.", "missing");
  }

  if (isBlank(draft.type)) {
    at("kr-wiz-type", "Property type", "Choose a property type.", "missing");
  } else if (!PROPERTY_TYPES.includes(draft.type as never)) {
    at("kr-wiz-type", "Property type", "Choose one of the listed property types.", "error");
  }

  if (badNumber(draft.bedrooms, { min: 0, allowFraction: false })) {
    at(
      "kr-wiz-bedrooms",
      "Bedrooms",
      "Enter a whole number of bedrooms, or 0 for a studio.",
      "error"
    );
  } else if (absent(draft.bedrooms)) {
    at("kr-wiz-bedrooms", "Bedrooms", "Enter the number of bedrooms.", "missing");
  }

  /* Halves are ordinary in American listings and the model stores a plain
     number, so 1.5 is allowed rather than rounded away. */
  if (badNumber(draft.bathrooms, { min: 0 })) {
    at("kr-wiz-bathrooms", "Bathrooms", "Enter a valid number of bathrooms.", "error");
  } else if (absent(draft.bathrooms)) {
    at("kr-wiz-bathrooms", "Bathrooms", "Enter the number of bathrooms.", "missing");
  }

  if (badNumber(draft.area, { min: 1, allowFraction: false })) {
    at("kr-wiz-area", "Square feet", "Enter a valid square-foot value.", "error");
  } else if (absent(draft.area)) {
    at("kr-wiz-area", "Square feet", "Enter the size in square feet.", "missing");
  }

  if (isBlank(draft.availability)) {
    at("kr-wiz-availability", "Availability", "Choose the availability.", "missing");
  } else if (!AVAILABILITY_VALUES.includes(String(draft.availability))) {
    at(
      "kr-wiz-availability",
      "Availability",
      "Choose one of the listed availability options.",
      "error"
    );
  }

  /* Pricing. Only meaningful when the property has chosen to show a figure —
     Ask for Pricing is a complete answer, not an unfinished one. */
  if (draft.priceDisplay !== "ask") {
    if (badNumber(draft.rent, { min: 1, allowFraction: false })) {
      at(
        "kr-wiz-rent",
        "Monthly price",
        "Enter the monthly price, or choose Ask for Pricing.",
        "error"
      );
    } else if (absent(draft.rent)) {
      at(
        "kr-wiz-rent",
        "Monthly price",
        "Enter the monthly price, or choose Ask for Pricing.",
        "missing"
      );
    }
  }

  return issues;
}

/* ── page 2 ──────────────────────────────────────────────── */

function contentIssues(draft: PropertyDraft): FieldIssue[] {
  const issues: FieldIssue[] = [];

  if (isBlank(draft.summary)) {
    issues.push({
      stepId: "content",
      field: "kr-wiz-summary",
      label: "Short description",
      message: "Write a sentence or two about the property.",
      kind: "missing",
    });
  }

  return issues;
}

/* ── page 3 ──────────────────────────────────────────────── */

/**
 * Floor plans are optional; a floor plan that exists is not.
 *
 * Adding a unit and leaving it nameless would put a blank tab on the public
 * page, so the requirement attaches to the unit rather than to the step. A
 * property with no units at all raises nothing at all.
 */
function imageIssues(draft: PropertyDraft): FieldIssue[] {
  const issues: FieldIssue[] = [];

  (draft.floorPlans ?? []).forEach((plan, index) => {
    if (isBlank(plan.label)) {
      issues.push({
        stepId: "images",
        field: `kr-wiz-plan-${plan.id}-label`,
        label: `Floor plan ${index + 1}`,
        message: "Give this floor plan a name, or remove it.",
        kind: "error",
      });
    }

    if (badNumber(plan.squareFeet, { min: 1, allowFraction: false })) {
      issues.push({
        stepId: "images",
        field: `kr-wiz-plan-${plan.id}-area`,
        label: `${plan.label || `Floor plan ${index + 1}`} — square feet`,
        message: "Enter a valid square-foot value.",
        kind: "error",
      });
    }
  });

  return issues;
}

/* ── the public interface ────────────────────────────────── */

const BY_STEP: Record<string, (draft: PropertyDraft) => FieldIssue[]> = {
  basics: basicsIssues,
  content: contentIssues,
  images: imageIssues,
};

export function issuesForStep(stepId: string, draft: PropertyDraft): FieldIssue[] {
  const rule = BY_STEP[stepId];
  return rule ? rule(draft) : [];
}

export function allIssues(draft: PropertyDraft): FieldIssue[] {
  return Object.keys(BY_STEP).flatMap((stepId) => issuesForStep(stepId, draft));
}

export const errorsOf = (issues: FieldIssue[]): FieldIssue[] =>
  issues.filter((issue) => issue.kind === "error");

/** The first thing wrong on a step, which is where focus should go. */
export function firstIssue(stepId: string, draft: PropertyDraft): FieldIssue | null {
  return issuesForStep(stepId, draft)[0] ?? null;
}

/**
 * Whether a step's own information is finished.
 *
 * Used for the tick in both navigations, so a tick means the same thing the
 * review screen means by it.
 */
export function isStepSatisfied(stepId: string, draft: PropertyDraft): boolean {
  return issuesForStep(stepId, draft).length === 0;
}

/**
 * Everything standing between this property and the website.
 *
 * Deliberately the same rules as the steps rather than a second, stricter set
 * discovered at the end. Photographs and floor plans are absent from it on
 * purpose: the architecture has always held that a property without
 * photography is a real state, and a workflow that refuses to publish without
 * pictures teaches people to upload anything to get past it.
 */
export function publishBlockers(draft: PropertyDraft): FieldIssue[] {
  return allIssues(draft);
}

export function canPublish(draft: PropertyDraft): boolean {
  return publishBlockers(draft).length === 0;
}

/**
 * Whether Continue may proceed.
 *
 * Wrong values block; absent ones do not. The name is the one exception — every
 * later step is about a property this one has not yet identified, so there is
 * nothing to continue to without it.
 */
export function canContinueFromStep(stepId: string, draft: PropertyDraft): boolean {
  if (isBlank(draft.title)) return false;
  return errorsOf(issuesForStep(stepId, draft)).length === 0;
}

/** What to say when Continue is disabled. */
export function continueBlockedReason(
  stepId: string,
  draft: PropertyDraft
): string | null {
  if (isBlank(draft.title)) return "Give the property a name to continue.";

  const error = errorsOf(issuesForStep(stepId, draft))[0];
  return error ? error.message : null;
}
