// @ppm--version--1.0
//
// Per-field decryption for stored form submissions.
//
// Extracted verbatim from src/ppm/plugins/GetTest.tsx (the working lead reader
// behind /form) so the CMS Leads plugin and that page share one implementation
// instead of keeping two copies of the same crypto.
//
// WIRE FORMAT — this is NOT the same as crypt.ts / decoder.ts.
//   crypt.ts / decoder.ts  : whole payload, chunked, `{"chunks":[b64,...]}`
//   here                   : one field at a time, a single bare base64 RSA
//                            block per string, object keys left in plaintext
//
// Stored submissions use the second format, so a field's plaintext must fit in
// one RSA-2048 OAEP/SHA-256 block (190 bytes). Longer values cannot be read
// back by this path.



/** Decrypts one base64 RSA-OAEP block back to its plaintext string. */
export const decryptValue = async (
  encrypted: string,
  privateKeyPem: string
): Promise<string> => {
  const pemContents = privateKeyPem
    .replace("-----BEGIN PRIVATE KEY-----", "")
    .replace("-----END PRIVATE KEY-----", "")
    .replace(/\s/g, "");

  const binaryDer = Uint8Array.from(
    atob(pemContents),
    (char) => char.charCodeAt(0)
  );

  const privateKey = await crypto.subtle.importKey(
    "pkcs8",
    binaryDer.buffer,
    {
      name: "RSA-OAEP",
      hash: "SHA-256",
    },
    false,
    ["decrypt"],
  );

  const encryptedBytes = Uint8Array.from(
    atob(encrypted),
    (char) => char.charCodeAt(0),
  );

  const decrypted = await crypto.subtle.decrypt(
    {
      name: "RSA-OAEP",
    },
    privateKey,
    encryptedBytes,
  );

  return new TextDecoder().decode(decrypted);
};

/**
 * Walks a fetched submission and decrypts every string leaf in place.
 * Object keys, numbers, booleans and null pass through untouched, so the
 * decrypted record keeps exactly the shape the repository stored.
 */
export const decryptObject = async (

  value: any, 
  privateKey : any
): Promise<any> => {
  if (typeof value === "string") {
    return decryptValue(value, privateKey);
  }

  if (Array.isArray(value)) {
    return Promise.all(
      value.map((item) => decryptObject(item, privateKey)),
    );
  }

  if (
    value !== null &&
    typeof value === "object"
  ) {
    const entries = await Promise.all(
      Object.entries(value).map(
        async ([key, childValue]) => [
          key,
          await decryptObject(childValue, privateKey),
        ],
      ),
    );

    return Object.fromEntries(entries);
  }

  return value;
};
