import React, { useState } from "react";
import { LuPlus, LuX } from "react-icons/lu";

import ApplyDialog from "./ApplyDialog";
import type { GFormField } from "../gh-leads/GForm";
import type { ApplicationQuestion, QuestionType } from "./types";

/** The five types, in plain language. No developer terminology. */
export const QUESTION_TYPES: {
  type: QuestionType;
  label: string;
  hint: string;
  /** Whether the type needs a list of options. */
  choices: boolean;
}[] = [
  {
    type: "text",
    label: "Short Answer",
    hint: "For names and short responses",
    choices: false,
  },
  {
    type: "radio",
    label: "Multiple Choice",
    hint: "Choose one option",
    choices: true,
  },
  {
    type: "checkbox",
    label: "Checkbox",
    hint: "Choose one or more options",
    choices: true,
  },
  {
    type: "select",
    label: "Drop Down",
    hint: "Choose one option from a menu",
    choices: true,
  },
  { type: "date", label: "Date", hint: "Choose a date", choices: false },
];

export function typeLabel(type: string | undefined): string {
  const known = QUESTION_TYPES.find((entry) => entry.type === type);
  if (known) return known.label;
  // The seeded application uses email, tel and textarea, which the editor does
  // not offer as new types but must still describe honestly.
  if (type === "email") return "Short Answer (email)";
  if (type === "tel") return "Short Answer (phone)";
  if (type === "textarea") return "Long Answer";
  return "Short Answer";
}

export function needsChoices(type: string | undefined): boolean {
  return QUESTION_TYPES.some((entry) => entry.type === type && entry.choices);
}

/** Field names are derived from the label so an editor never sees one. */
export function nameFromLabel(label: string, existing: string[]): string {
  const base =
    label
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "")
      .slice(0, 40) || "question";

  if (!existing.includes(base)) return base;

  let suffix = 2;
  while (existing.includes(`${base}-${suffix}`)) suffix += 1;
  return `${base}-${suffix}`;
}

export type QuestionEditorProps = {
  /** The question being edited, or null when adding a new one. */
  question: ApplicationQuestion | null;
  /** Chosen type when adding. Ignored when editing an existing question. */
  type: QuestionType;
  /** Names already in use, so a derived name cannot collide. */
  usedNames: string[];
  /* GFormField rather than Omit<ApplicationQuestion, "id">: GFormField carries
     an index signature, and Omit over one collapses to [x: string]: unknown,
     which loses the required `name`. The caller adds the id. */
  onSave: (question: GFormField) => void;
  onClose: () => void;
};

export default function QuestionEditor({
  question,
  type,
  usedNames,
  onSave,
  onClose,
}: QuestionEditorProps) {
  const effectiveType = (question?.type as QuestionType) ?? type;
  const choices = needsChoices(effectiveType);

  const [label, setLabel] = useState(String(question?.label ?? ""));
  const [required, setRequired] = useState(Boolean(question?.required));
  const [options, setOptions] = useState<string[]>(
    question?.options?.length
      ? question.options.map((option) => option.label)
      : choices
        ? ["", ""]
        : []
  );
  const [error, setError] = useState("");

  const usable = options.map((option) => option.trim()).filter(Boolean);

  const save = () => {
    if (!label.trim()) {
      setError("Give the question some wording so applicants know what to answer.");
      return;
    }

    // A choice question with nothing to choose from renders as an empty space
    // on the public form, so it is refused here rather than shipped.
    if (choices && usable.length < 2) {
      setError("Add at least two options for people to choose between.");
      return;
    }

    onSave({
      name:
        question?.name ??
        nameFromLabel(label, usedNames.filter((name) => name !== question?.name)),
      type: effectiveType,
      label: label.trim(),
      required,
      ...(choices
        ? {
            options: usable.map((option) => ({
              label: option,
              value: option.toLowerCase().replace(/[^a-z0-9]+/g, "-"),
            })),
          }
        : {}),
    });
  };

  return (
    <ApplyDialog
      title={question ? "Edit Question" : "Add Question"}
      text={typeLabel(effectiveType)}
      onConfirm={save}
      confirmLabel="Save"
      onClose={onClose}
    >
      {error ? (
        <div className="kr-apply-cms__banner kr-apply-cms__banner--bad" role="alert">
          {error}
        </div>
      ) : null}

      <div className="kr-apply-cms__field">
        <label className="kr-apply-cms__label" htmlFor="kr-question-label">
          Question
        </label>
        <input
          id="kr-question-label"
          className="kr-apply-cms__input"
          value={label}
          placeholder="What is your full name?"
          onChange={(event) => setLabel(event.target.value)}
        />
      </div>

      <div className="kr-apply-cms__field">
        <label className="kr-apply-cms__switch">
          <input
            type="checkbox"
            checked={required}
            onChange={(event) => setRequired(event.target.checked)}
          />
          Required — applicants must answer this
        </label>
      </div>

      {choices ? (
        <div className="kr-apply-cms__field">
          <span className="kr-apply-cms__label">Options</span>

          {options.map((option, index) => (
            <div className="kr-apply-cms__option-row" key={index}>
              <input
                className="kr-apply-cms__input"
                value={option}
                placeholder={`Option ${index + 1}`}
                aria-label={`Option ${index + 1}`}
                onChange={(event) =>
                  setOptions((current) =>
                    current.map((value, i) =>
                      i === index ? event.target.value : value
                    )
                  )
                }
              />
              <button
                type="button"
                className="kr-apply-cms__btn kr-apply-cms__btn--icon"
                aria-label={`Remove option ${index + 1}`}
                disabled={options.length <= 2}
                onClick={() =>
                  setOptions((current) => current.filter((_, i) => i !== index))
                }
              >
                <LuX size={14} />
              </button>
            </div>
          ))}

          <button
            type="button"
            className="kr-apply-cms__btn"
            onClick={() => setOptions((current) => [...current, ""])}
          >
            <LuPlus size={14} /> Add Option
          </button>
        </div>
      ) : null}
    </ApplyDialog>
  );
}
