// The wizard's rules, with no React and no DOM in them.
//
// Which step you are on, which you may jump to, whether a step is finished,
// and what the two navigations should show — all of it decided here, so the
// shell renders decisions rather than making them, and so MTC-KRP-026 can add
// real fields without touching navigation at all.
//
// The important design point: a step is complete when its DATA says so, never
// because somebody pressed Continue. A tick that only means "you walked past
// this" is worse than no tick, because it tells the user they have finished
// something they have not.

export type StepId = string;

export type WizardStep<Draft> = {
  id: StepId;
  /** Full name, used as the step heading. */
  title: string;
  /** Short name for the side navigation, where space is tighter. */
  shortTitle: string;
  /** One line under the heading saying what this step is for. */
  description: string;
  /**
   * Whether this step's required information is present.
   *
   * Returning true from a step that asks for nothing is deliberate: an
   * optional step should not hold the wizard open. Omit it entirely and the
   * step is always considered complete.
   */
  isComplete?: (draft: Draft) => boolean;
  /**
   * Blocks Continue while false. Distinct from `isComplete`: a step can be
   * incomplete but still passable — the review step is what refuses to publish.
   */
  canContinue?: (draft: Draft) => boolean;
};

export type StepState = "complete" | "current" | "incomplete";

export type StepView = {
  id: StepId;
  title: string;
  shortTitle: string;
  description: string;
  index: number;
  /** 1-based, for "Step 2 of 5". */
  position: number;
  state: StepState;
  /**
   * Whether tapping it should navigate.
   *
   * Any step at or before the furthest one reached, plus any completed step.
   * Jumping to an untouched step five ahead would show a form for something
   * the user has not been introduced to yet.
   */
  reachable: boolean;
};

export function stepIndex<D>(steps: WizardStep<D>[], id: StepId | null): number {
  if (!id) return 0;
  const index = steps.findIndex((step) => step.id === id);
  return index === -1 ? 0 : index;
}

export function isStepComplete<D>(step: WizardStep<D>, draft: D): boolean {
  return step.isComplete ? step.isComplete(draft) : true;
}

/**
 * The furthest step the user has legitimately got to.
 *
 * Tracked rather than derived from completion, because a user who fills in
 * step 1, moves to step 2 and then deletes something in step 1 has still SEEN
 * step 2 — sending them back would be the wizard fighting them.
 */
export function reachIndex<D>(
  steps: WizardStep<D>[],
  currentId: StepId | null,
  furthestId: StepId | null
): number {
  return Math.max(stepIndex(steps, currentId), stepIndex(steps, furthestId));
}

export function buildSteps<D>(
  steps: WizardStep<D>[],
  draft: D,
  currentId: StepId | null,
  furthestId: StepId | null
): StepView[] {
  const current = stepIndex(steps, currentId);
  const reach = reachIndex(steps, currentId, furthestId);

  return steps.map((step, index) => {
    const complete = isStepComplete(step, draft);

    return {
      id: step.id,
      title: step.title,
      shortTitle: step.shortTitle,
      description: step.description,
      index,
      position: index + 1,
      /* Current wins over complete: the user needs to know where they are
         more than they need a tick on the step they are looking at. */
      state: index === current ? "current" : complete ? "complete" : "incomplete",
      reachable: index <= reach || complete,
    };
  });
}

export const isFirst = (index: number) => index === 0;
export const isLast = <D>(steps: WizardStep<D>[], index: number) =>
  index >= steps.length - 1;

/** Null at the ends, so the shell disables rather than wrapping around. */
export function nextStepId<D>(steps: WizardStep<D>[], id: StepId | null): StepId | null {
  const index = stepIndex(steps, id);
  return isLast(steps, index) ? null : steps[index + 1].id;
}

export function previousStepId<D>(steps: WizardStep<D>[], id: StepId | null): StepId | null {
  const index = stepIndex(steps, id);
  return isFirst(index) ? null : steps[index - 1].id;
}

export function canContinueFrom<D>(
  steps: WizardStep<D>[],
  id: StepId | null,
  draft: D
): boolean {
  const step = steps[stepIndex(steps, id)];
  if (!step) return false;
  return step.canContinue ? step.canContinue(draft) : true;
}

/** Every step whose required information is still missing. */
export function incompleteSteps<D>(steps: WizardStep<D>[], draft: D): WizardStep<D>[] {
  return steps.filter((step) => !isStepComplete(step, draft));
}

export function isWizardComplete<D>(steps: WizardStep<D>[], draft: D): boolean {
  return incompleteSteps(steps, draft).length === 0;
}

/**
 * Resolves a step id that came from the URL.
 *
 * An unknown or missing id falls back to the first step rather than throwing —
 * a mistyped address should open the wizard, not break it.
 */
export function resolveStepId<D>(steps: WizardStep<D>[], candidate: string | undefined): StepId {
  if (!candidate) return steps[0].id;
  return steps.some((step) => step.id === candidate) ? candidate : steps[0].id;
}
