// The wizard's doorway into the Images CMS.
//
// There is ONE image library on this site and this is not a second one. Every
// call below goes through `imageApi` — the same adapter the Images section
// uses, hitting the same worker, writing to the same repository. A photograph
// uploaded from the property workflow is an ordinary CMS image: it appears in
// the Images section, it can be reused by another property, and deleting it
// there removes it here.
//
// That is the whole reason this file is thin. It exists to give the property
// steps a small, honest surface — a list, an upload, an error — rather than to
// own anything.
//
// ── on the current state of this site ────────────────────────────────────
// The Kelley Road image worker is not deployed and the images repository does
// not exist yet, so `fetchFiles` returns only the static images bundled with
// the site and `upload` fails. Both failures are surfaced as text the manager
// can act on. Nothing here pretends an upload worked.

import { useCallback, useEffect, useRef, useState } from "react";

import { createThumbnail } from "../../gh-image/createThumbnail";
import { imageApi } from "../../gh-image/imageApi";
import type { ImageRecord } from "../../gh-image/imageApi";

export type LibraryImage = {
  id: string;
  /** A URL the browser can render. */
  src: string;
  name: string;
};

export type UploadReport = {
  uploaded: LibraryImage[];
  /** One entry per file that did not make it, with the reason it gave. */
  failures: { name: string; reason: string }[];
};

const toLibraryImage = (record: ImageRecord): LibraryImage => ({
  id: record.id,
  src: record.path,
  name: record.name,
});

export function useImageLibrary() {
  const [library, setLibrary] = useState<LibraryImage[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);

  const alive = useRef(true);
  useEffect(() => () => {
    alive.current = false;
  }, []);

  const load = useCallback(async () => {
    setLoading(true);
    setLoadError(null);

    try {
      const records = await imageApi.fetchFiles();
      if (!alive.current) return;
      setLibrary(records.map(toLibraryImage));
    } catch (error) {
      if (!alive.current) return;
      setLoadError(
        error instanceof Error
          ? error.message
          : "The image library could not be reached."
      );
    } finally {
      if (alive.current) setLoading(false);
    }
  }, []);

  /**
   * Uploads files, one at a time, and reports honestly on each.
   *
   * Sequential rather than parallel: these go to a single worker that commits
   * to a git repository, and firing eight at once is how you get half of them
   * back as conflicts. A slow upload that works beats a fast one that loses
   * pictures.
   *
   * A file that fails does not stop the ones after it, and every failure is
   * named — "three uploaded, one failed" with no indication of which is a
   * message that costs the manager the afternoon.
   */
  const upload = useCallback(async (files: File[]): Promise<UploadReport> => {
    const uploaded: LibraryImage[] = [];
    const failures: { name: string; reason: string }[] = [];

    for (const file of files) {
      setBusy(`Uploading ${file.name}…`);

      try {
        const result = await imageApi.uploadImage(file, (message) => {
          if (alive.current) setBusy(message);
        });

        const src = result.webpUrl || result.pagesUrl || result.downloadUrl;

        if (!src) {
          failures.push({
            name: file.name,
            reason: "The upload finished but returned no address for the image.",
          });
          continue;
        }

        uploaded.push({ id: `${Date.now()}-${file.name}`, src, name: file.name });
      } catch (error) {
        failures.push({
          name: file.name,
          reason:
            error instanceof Error
              ? error.message
              : "The upload service could not be reached.",
        });
      }
    }

    if (alive.current) setBusy(null);
    if (uploaded.length) void load();

    return { uploaded, failures };
  }, [load]);

  return { library, loading, loadError, busy, load, upload };
}

/**
 * A local preview of a file the browser already has.
 *
 * Used only while an upload is failing or in flight, so the manager can see
 * which picture the message is about. It is never stored on the property: a
 * data URL in a property record would be a photograph that exists in one
 * person's browser and nowhere else.
 */
export async function previewFor(file: File): Promise<string> {
  try {
    return await createThumbnail(file, 240, 0.72);
  } catch {
    return "";
  }
}
