import React, { useMemo, useState } from "react";
import {
  LuArrowDown,
  LuArrowUp,
  LuEyeOff,
  LuGripVertical,
  LuInfo,
  LuPin,
  LuRotateCcw,
  LuSearch,
  LuX,
} from "react-icons/lu";

import { matchesTerm } from "../../../properties-search/useSearchState";
import { resolveProperty } from "../../../../primitives/property/property-images";
import type { PropertyRecord } from "../../../property/types";
import {
  allowAgain,
  exclude,
  isExcluded,
  isPinned,
  movePinned,
  pin,
  reorderPinned,
  resolveSimilar,
  unpin,
} from "../similar";
import type { StepProps } from "./types";

/**
 * Page 4 — what to suggest at the bottom of the page.
 *
 * Doing nothing here is the expected outcome and a correct one. The automatic
 * choice already exists, already runs on the public site, and is what every
 * property uses today. Everything on this page is an adjustment to it, which
 * is why the automatic list is shown first and in full rather than being
 * something you switch on.
 *
 * Reordering can be done by dragging or with two buttons. The buttons are not
 * a fallback bolted on afterwards — they are the implementation, and the
 * dragging calls the same function. An order that can only be changed with a
 * mouse is an order some people cannot change at all.
 */
export default function SimilarStep({ draft, onChange, properties }: StepProps) {
  const [term, setTerm] = useState("");
  const [dragging, setDragging] = useState<string | null>(null);

  const refs = draft.similar;

  const resolution = useMemo(
    () => resolveSimilar(draft, properties),
    [draft, properties]
  );

  const results = useMemo(() => {
    if (!term.trim()) return [];
    return properties
      .filter(
        (record) =>
          record.slug !== draft.slug && record.id !== draft.id
      )
      .filter((record) => matchesTerm(record, term))
      .slice(0, 8);
  }, [properties, term, draft.slug, draft.id]);

  const setRefs = (next: ReturnType<typeof pin>) => onChange({ similar: next });

  const pinnedSlugs = refs?.pinned ?? [];

  return (
    <div className="kr-wiz__fields">
      <p className="kr-wiz__note">
        <LuInfo size={15} className="kr-wiz__note-icon" aria-hidden="true" />
        <span>
          Similar properties are chosen automatically, based on where they are,
          what kind of home they are, their size and their price. You can leave
          this page alone.
        </span>
      </p>

      {/* ── what will actually show ─────────────────────── */}
      <section className="kr-wiz__group">
        <h3 className="kr-props__label">On the page now</h3>
        <p className="kr-wiz__help kr-wiz__help--above">
          In this order. Anything you pin below goes first.
        </p>

        {resolution.shown.length === 0 ? (
          <p className="kr-wiz__help">
            Nothing to suggest yet — there needs to be more than one property.
          </p>
        ) : (
          <ol className="kr-wiz__similar">
            {resolution.shown.map((record, index) => {
              const pinnedHere = isPinned(refs, record.slug);

              return (
                <li
                  key={record.slug}
                  className={`kr-wiz__similar-row${
                    pinnedHere ? " kr-wiz__similar-row--pinned" : ""
                  }${dragging === record.slug ? " kr-wiz__similar-row--dragging" : ""}`}
                  draggable={pinnedHere}
                  onDragStart={() => setDragging(record.slug)}
                  onDragEnd={() => setDragging(null)}
                  onDragOver={(event) => {
                    if (pinnedHere && dragging) event.preventDefault();
                  }}
                  onDrop={(event) => {
                    event.preventDefault();
                    if (dragging && pinnedHere) {
                      setRefs(
                        reorderPinned(refs, dragging, pinnedSlugs.indexOf(record.slug))
                      );
                    }
                    setDragging(null);
                  }}
                >
                  {pinnedHere ? (
                    <span className="kr-wiz__grip" aria-hidden="true">
                      <LuGripVertical size={15} />
                    </span>
                  ) : (
                    <span className="kr-wiz__rank" aria-hidden="true">
                      {index + 1}
                    </span>
                  )}

                  <PropertyRow record={record} />

                  <p className="kr-wiz__similar-state">
                    {pinnedHere ? "Pinned" : "Automatic"}
                  </p>

                  <div className="kr-wiz__similar-actions">
                    {pinnedHere ? (
                      <>
                        <button
                          type="button"
                          className="kr-wiz__icon-btn"
                          disabled={pinnedSlugs.indexOf(record.slug) === 0}
                          onClick={() => setRefs(movePinned(refs, record.slug, -1))}
                        >
                          <LuArrowUp size={15} aria-hidden="true" />
                          <span className="kr-sr-only">Move {record.title} up</span>
                        </button>

                        <button
                          type="button"
                          className="kr-wiz__icon-btn"
                          disabled={
                            pinnedSlugs.indexOf(record.slug) === pinnedSlugs.length - 1
                          }
                          onClick={() => setRefs(movePinned(refs, record.slug, 1))}
                        >
                          <LuArrowDown size={15} aria-hidden="true" />
                          <span className="kr-sr-only">Move {record.title} down</span>
                        </button>

                        <button
                          type="button"
                          className="kr-props__btn kr-props__btn--quiet"
                          onClick={() => setRefs(unpin(refs, record.slug))}
                        >
                          <LuX size={13} aria-hidden="true" /> Unpin
                          <span className="kr-sr-only">{record.title}</span>
                        </button>
                      </>
                    ) : (
                      <>
                        <button
                          type="button"
                          className="kr-props__btn"
                          onClick={() => setRefs(pin(refs, record.slug))}
                        >
                          <LuPin size={13} aria-hidden="true" /> Pin
                          <span className="kr-sr-only">{record.title}</span>
                        </button>

                        <button
                          type="button"
                          className="kr-props__btn kr-props__btn--quiet"
                          onClick={() => setRefs(exclude(refs, record.slug))}
                        >
                          <LuEyeOff size={13} aria-hidden="true" /> Leave out
                          <span className="kr-sr-only">{record.title}</span>
                        </button>
                      </>
                    )}
                  </div>
                </li>
              );
            })}
          </ol>
        )}

        {pinnedSlugs.length > 1 ? (
          <p className="kr-wiz__help">
            Drag a pinned property to reorder it, or use the arrows.
          </p>
        ) : null}
      </section>

      {/* ── search ──────────────────────────────────────── */}
      <section className="kr-wiz__group">
        <h3 className="kr-props__label">Add another property</h3>

        <div className="kr-wiz__search">
          <LuSearch size={15} aria-hidden="true" />
          <label className="kr-sr-only" htmlFor="kr-wiz-similar-search">
            Search properties
          </label>
          <input
            id="kr-wiz-similar-search"
            className="kr-props__input"
            value={term}
            placeholder="Search properties by name, town or type"
            onChange={(event) => setTerm(event.target.value)}
          />
        </div>

        {term.trim() ? (
          results.length === 0 ? (
            <p className="kr-wiz__help">Nothing matches that.</p>
          ) : (
            <ul className="kr-wiz__similar">
              {results.map((record) => (
                <li key={record.slug} className="kr-wiz__similar-row">
                  <PropertyRow record={record} />

                  <p className="kr-wiz__similar-state">
                    {isPinned(refs, record.slug)
                      ? "Pinned"
                      : isExcluded(refs, record.slug)
                        ? "Left out"
                        : ""}
                  </p>

                  <div className="kr-wiz__similar-actions">
                    <button
                      type="button"
                      className="kr-props__btn"
                      disabled={isPinned(refs, record.slug)}
                      onClick={() => setRefs(pin(refs, record.slug))}
                    >
                      <LuPin size={13} aria-hidden="true" /> Pin
                      <span className="kr-sr-only">{record.title}</span>
                    </button>

                    <button
                      type="button"
                      className="kr-props__btn kr-props__btn--quiet"
                      disabled={isExcluded(refs, record.slug)}
                      onClick={() => setRefs(exclude(refs, record.slug))}
                    >
                      <LuEyeOff size={13} aria-hidden="true" /> Leave out
                      <span className="kr-sr-only">{record.title}</span>
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )
        ) : (
          <p className="kr-wiz__help">
            Type a name, a town or a property type. This property is never
            offered — it cannot suggest itself.
          </p>
        )}
      </section>

      {/* ── exclusions ──────────────────────────────────── */}
      {resolution.excluded.length > 0 ? (
        <section className="kr-wiz__group">
          <h3 className="kr-props__label">Left out</h3>
          <p className="kr-wiz__help kr-wiz__help--above">
            These are never suggested here, however well they match.
          </p>

          <ul className="kr-wiz__similar">
            {resolution.excluded.map((record) => (
              <li key={record.slug} className="kr-wiz__similar-row">
                <PropertyRow record={record} />
                <p className="kr-wiz__similar-state">Left out</p>
                <div className="kr-wiz__similar-actions">
                  <button
                    type="button"
                    className="kr-props__btn"
                    onClick={() => setRefs(allowAgain(refs, record.slug))}
                  >
                    <LuRotateCcw size={13} aria-hidden="true" /> Allow again
                    <span className="kr-sr-only">{record.title}</span>
                  </button>
                </div>
              </li>
            ))}
          </ul>
        </section>
      ) : null}
    </div>
  );
}

/** Enough of a property to tell it apart from another. */
function PropertyRow({ record }: { record: PropertyRecord }) {
  const resolved = resolveProperty(record);

  return (
    <div className="kr-wiz__similar-body">
      <img
        className="kr-wiz__similar-image"
        src={resolved.image}
        alt=""
        loading="lazy"
        decoding="async"
      />
      <div>
        <p className="kr-wiz__similar-name">{record.title}</p>
        <p className="kr-wiz__similar-meta">
          {[
            record.location,
            record.type,
            record.bedrooms === 0
              ? "Studio"
              : `${record.bedrooms} bed${record.bedrooms === 1 ? "" : "s"}`,
            record.area ? `${record.area.toLocaleString("en-US")} sq ft` : "",
          ]
            .filter(Boolean)
            .join(" · ")}
        </p>
      </div>
    </div>
  );
}
